INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gfmw6', 'gfmw6', 'A notícia como fábula: realidade e ficção se confundem na mídia', NULL, '["Renato Modernell"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] Às vezes, a única coisa verdadeira num jornal é a data?, disse Luis Fernando Verissimo. Tomar ao pé da letra essa frase bem-humorada do cronista pode não ser um bom negócio. Porém, ainda mais temerário seria aceitar a hipótese oposta, ou seja, de que tudo acontece do jeito que o jornalista nos conta. Certos recursos de escrita e de edição aumentam tanto a temperatura do texto que provocam a fusão entre a fantasia e a realidade. Esse fenômeno misterioso, com seu toque de alquimia, é o que Renato Modernell investiga em A notícia como fábula.', '["journalism","fiction and reality","news writing","news editing","media","fables","truth in journalism"]', '10.7476/9788582930526', '9788582930526', 'https://books.scielo.org/id/gfmw6', NULL, NULL, 'https://books.scielo.org/id/gfmw6/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gfnsy', 'gfnsy', 'Cooperação e desenvolvimento humano: a agenda emergente para o novo milênio', NULL, '["Carlos Lopes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Nesse livro o representante da ONU e do PNUD no Brasil, Carlos Lopes, nos apresenta, através de textos escritos entre 2001 e 2003, a necessidade de um amplo debate político na definição da agenda de desenvolvimento e transformação da sociedade para a redução da pobreza no mundo globalizado. A compreensão das sociedades em sua complexidade e aceitação do multiculturalismo é que irão permitir a construção de capacidades para a expansão dos campos de oportunidades do países em desenvolvimento. O grande desafio ético de hoje é, portanto, tornar as diferenças enriquecedoras e não restringir o processo de globalização à realização de obrigações comerciais, à idéia de que o comércio competitivo seria, simplesmente, a chave para a redução da pobreza.', '["international cooperation","human development","poverty reduction","globalization","development agenda","multiculturalism","capability approach","developing countries","trade and poverty","UNDP","Carlos Lopes"]', '10.7476/9788539302925', '9788571396203', 'https://books.scielo.org/id/gfnsy', NULL, NULL, 'https://books.scielo.org/id/gfnsy/cover/cover_thumbnail.jpeg', 214, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ggfcb', 'ggfcb', 'De portas abertas para o lazer: a cultura lúdica nas comunidades de bairro', NULL, '["Elaine Melo de Brito Costa Lemos","Eduardo Ribeiro Dantas","Cheng Hsin Nery Chao"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Acompanhando a tendência de atenuação das condições de injustiça e exclusão social, a partir do esporte recreativo e do lazer, o Grupo de Pesquisa Corpo, Educação e Movimento - GCEM, do Departamento de Educação Física da Universidade Estadual da Paraíba - UEPB, propôs o desenvolvimento de uma investigação sobre a situação do lazer na cidade de Campina Grande – PB, considerando a Pesquisa de Informações Básicas Municipais (MUNIC, 2003), a partir do universo das comunidades de bairro. (trecho retirado do texto "Abrindo as portas da pesquisa: Pressupostos teóricos e metodológicos" do livro)', '["leisure","play culture","neighborhood community","recreational sports","social exclusion","social justice","Campina Grande"]', '10.7476/9788578791223', '9788578791223', 'https://books.scielo.org/id/ggfcb', 'https://books.scielo.org/id/ggfcb/pdf/lemos-9788578791223.pdf', NULL, 'https://books.scielo.org/id/ggfcb/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ggrv9', 'ggrv9', 'História ambiental e migrações: diálogos', NULL, '["Marcos Gerhardt","Nodari, Eunice Sueli","Moretto, Samira Peruchi"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'ApresentaçãoEste livro tem um tema específico: aborda os possíveis diálogos entre dois campos do conhecimento histórico.De um lado, os estudos sobre migrações humanas; de outro, as pesquisas em história ambiental, que ganharam importância na historiografia brasileira das últimas década.Este diálogo é promovido, desde 1992, pelo Laboratório de Imigração, Migração e História Ambiental (LABIMHA), vinculado ao Programa de Pós-Graduação em História da Universidade Federal de Santa Catarina (UFSC), que reúne, também, pesquisadores de outras universidades e programas de pósgraduação stricto sensu em História.Os diálogos possíveis entre esses dois campos consideram os movimentos populacionais pretéritos e contemporâneos, a movimentação de grupos humanos das etnias Kaingang e Guarani por seus territórios, as grandes ondas de imigração de população de origem europeia não ibérica iniciadas no século XIX, as migrações internas posteriores dos descendentes de imigrantes europeus instalados, principalmente, no sul do Brasil e as emigrações, imigrações e deslocamentos atuais, de grupos humanos movidos por razões econômicas ou socioambientais.Consideram, ainda, a atração que os bens naturais disponíveis em outros lugares exerceram, como possibilidade de subsistência ou de ganho econômico, as condições favoráveis e as limitações do meio ambiente aos grupos humanos que passaram a habitá-lo e, com mais ênfase, as transformações que esses grupos migrantes realizaram nos ambientes que ocuparam ou repovoaram.O capítulo de Sandro Dutra e Silva, José Luiz de Andrade Franco e José Augusto Drummond, abordando Colonização, desflorestamento e a expansão da fronteira agrícola em Goiás nas décadas de 1930 e 1940, abre o livro.Ele aborda a história ambiental do desmatamento e da transformação de vegetação nativa do bioma Cerrado, isto é, foca a história das florestas de Goiás, conhecidas como o "Mato Grosso de Goiás", um enclave de Floresta Estacional Decidual no Cerrado que recebeu, no século XX, um fluxo de imigrantes e sofreu profundas transformações econômicas e socioambientais.O segundo capítulo, escrito por Marcos Gerhardt, apresenta e interpreta O relato de Wilhelm Vallentin, um viajante alemão que percorreu parte Florestal de Nonoai, no norte do estado do Rio Grande do Sul, com destaque para o protagonismo indígena.María Cecilia Gallero, uma historiadora argentina que vem dialogando com os pesquisadores brasileiros, escreveu o texto La yerba mate en el prisma de la historia ambiental, no qual objetiva mostrar as transformações ambientais ocorridas na província de Misiones, Argentina, a partir da introdução dos ervais cultivados, no início do século XX.Estuda o caso da Cooperativa de Productores de Yerba Mate de Santo Pipó, fundada por imigrantes vindos da Suíça que se dedicaram à produção de erva-mate.Considerando outro espaço, o vale do Rio Doce, no estado de Minas Gerais, o capítulo "O tempo é a minha testemunha": só as pedras estavam aqui, todo o resto é imigrante, de Haruf Salmen Espindola e Maria Terezinha Bretas Vilarino, aborda as sucessivas transformações naquele ambiente, ao longo de dois séculos.Parte dessas transformações socioambientais, em particular aquelas que atingiram as florestas do vale, esteve ligada à imigração e à formação de colônias.Outras transformações foram provocadas por diferentes processos históricos, grupos e atores sociais, com destaque para a mineração, que "produziram uma paisagem híbrida no vale do Rio Doce".Fechando o livro, por ter um recorte temporal contemporâneo, o capítulo A imigração senegalesa: dimensões históricas, econômicas e socioambientais, de João Carlos Tedesco, discute a saída de população do Senegal, na África e sua imigração para a América, em especial para o centro-sul do Brasil e para a área metropolitana de Buenos Aires, na Argentina.Tedesco explica, nos limites do texto, "a dimensão histórica da atual diáspora senegalesa".Dentre suas complexas, "múltiplas e correlacionais" causas, estão os problemas socioambientais, isto é, a "emigração passa a ser uma estratégia para permitir o equilíbrio entre a população e as possibilidades do meio em fazer face às dificuldades socioeconômicas".Aos leitores, agradecemos o interesse pelo livro que organizamos e desejamos proveitosa leitura.Esperamos que ele sirva para aprofundar a compreensão das muitas interfaces possíveis entre os processos migratórios, um tema há muito tempo estudado, e a jovem história ambiental brasileira.', '["environmental history","human migration","Goiás","Cerrado deforestation","seasonal deciduous forest","European immigration","internal migration","emigration","resource extraction","Brazilian historiography","1930s"]', '10.7476/9788564905689', '9788564905689', 'https://books.scielo.org/id/ggrv9', 'https://books.scielo.org/id/ggrv9/pdf/gerhardt-9788564905689.pdf', NULL, 'https://books.scielo.org/id/ggrv9/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gj6qm', 'gj6qm', 'As revoluções russas e o socialismo soviético', NULL, '["Daniel Aarão Reis Filho"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O movimento em favor de uma mudança radical ganhava um número cada vez maior de participantes, em várias partes do mundo, culminando na Revolução Russa de 1917, que deu início a uma nova era. O processo revolucionário no início do século XX, sob inspiração de socialistas e comunistas, transcendia as fronteiras da Europa e da América e o caminho seguido pela União Soviética alarmou alguns e serviu de inspiração a outros, provocando debates e confrontos internos e externos que marcaram a história do século XX. Com o fim de guerra fria e o desaparecimento da União Soviética é possível reavaliar os acontecimentos.', '["Russian Revolution","Soviet socialism","Soviet Union","revolutionary movements","communism","socialism","Cold War","collapse of the Soviet Union","20th-century history"]', '10.7476/9788539302703', '9788571394827', 'https://books.scielo.org/id/gj6qm', NULL, NULL, 'https://books.scielo.org/id/gj6qm/cover/cover_thumbnail.jpeg', 179, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gj8dk', 'gj8dk', 'Sociedade industrial no Brasil', NULL, '["Juárez Rubens Brandão Lopes"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os estudos sociológicos reunidos neste volume pelo Prof. Juarez Rubens Brandão Lopes, da Universidade de São Paulo, representam uma valiosa contribuição à inteligência do processo de industrialização na sociedade brasileira contemporânea. Representam, por vários aspectos, um trabalho pioneiro que, por suas marcadas e amadurecidas diretrizes metodológicas, está destinada a influenciar decisivamente as futuras indagações nesse campo. Como poucas vezes se tem logrado entre nós nas pesquisas de ciências sociais, o autor consegue um equilíbrio e acerto felizes. Entre uma ampla interpretação sociológica e a precisão e minúcia dos dados coletados, na sua grande maioria, diretamente.', '["industrial society","industrialization","Brazilian society","sociology of work"]', '10.7476/9788599662779', '9788599662779', 'https://books.scielo.org/id/gj8dk', 'https://books.scielo.org/id/gj8dk/pdf/lopes-9788599662779.pdf', NULL, 'https://books.scielo.org/id/gj8dk/cover/cover_thumbnail.jpeg', NULL, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gkrs4', 'gkrs4', 'Pessoas com deficiência e doenças raras: o cuidado na atenção primária', NULL, '["Daniela Koeller Rodrigues Vieira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'O livro apresenta importantes experiências e esforços realizados no Brasil, nas últimas décadas, na inserção e na adaptação de pessoas com deficiência e doenças raras aos sistemas de saúde e de gestão. Organizado pela médica pediatra Daniela Koeller Rodrigues Vieira, pesquisadora do Instituto Nacional de Saúde da Mulher, da Criança e do Adolescente Fernandes Figueira (IFF/Fiocruz), a coletânea apresenta artigos de profissionais de diferentes campos científicos e especialidades como Biologia, Genética e Fonoaudiologia. Os textos refletem importantes contribuições acadêmicas e práticas que mostram a importância da recente inclusão em políticas públicas para a saúde de pessoas que apresentam uma ou mais deficiências e de indivíduos com condições raras. Inclusão surgida no contexto de avanços na estruturação e na ampliação do Sistema Único de Saúde (SUS). Assim, os autores abordam e dimensionam questões fundamentais como as experiências existentes nos cuidados a pessoas com deficiência e doenças raras na atenção primária, a genética médica e a integralidade na atenção à saúde, as ferramentas e as percepções dos profissionais de atenção primária para as abordagens e para as práticas de cuidado. O livro é o sexto título da coleção Fazer Saúde, que pretende contribuir para a qualificação de profissionais, pesquisadores e gestores do SUS, estimulando o diálogo entre conhecimentos científicos, educação, inovações tecnológicas, saberes e práticas em saúde. Para a professora da Faculdade de Ciências Médicas da Universidade do Estado do Rio de Janeiro (Uerj), Heloísa Viscaíno Pereira, a obra organizada por Daniela Koeller é um exemplo de “como o pensamento acadêmico pode influenciar diretamente a vida das pessoas, construindo uma ponte entre mundos considerados tão distantes: os atendimentos das clínicas da família e os laboratórios de biologia molecular”.', '["people with disabilities","rare diseases","primary care","Unified Health System (SUS)","medical genetics","comprehensive care","family health clinic","health professional perceptions","care practices","Brazil"]', '10.7476/9786557080610', '9788575416303', 'https://books.scielo.org/id/gkrs4', NULL, NULL, 'https://books.scielo.org/id/gkrs4/cover/cover_thumbnail.jpeg', 160, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gks62', 'gks62', 'Visión prospectiva de la actividad turística en Villa de Leyva', NULL, '["García Molano, Olga Judit","Zárate Solano, Franci Yolima","Alfonso Bernal, Nohora"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Una mirada desde la prospectiva territorial de la actividad turística en el municipio de Villa de Leyva, Boyacá, Colombia, permitió conocer y comprender las dinámicas que se dan entre los diversos protagonistas de la actividad en este destino, considerado como uno de los más importantes a nivel regional e internacional. Esta investigación se concentró en las relaciones, las tensiones y el factor de influencia de cada uno en la actividad. Para esto parte de la contextualización del territorio a través del estado del arte y la caracterización de sus actores, continuando con su valoración de la actividad turística, para llegar a los factores de cambio y el juego de dichos agentes, insumos vitales para la prospección de escenarios y la formulación de estrategias para lograr un escenario apuesta. Finalmente, este tipo de prospectiva constituye un plan de orientación colectiva que aporta a las diferentes perspectivas de los actores que se entretejen en la actividad turística de Villa de Leyva, convirtiéndose en elemento primordial para el desarrollo regional con enfoque territorial.', '["tourism activities","Villa de Leyva","territorial foresight","tourism stakeholders","tourism development strategy","regional development"]', '10.7476/9786287725126', '9786289572544', 'https://books.scielo.org/id/gks62', 'https://books.scielo.org/id/gks62/pdf/garcia-9786287725126.pdf', NULL, 'https://books.scielo.org/id/gks62/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gkt8v', 'gkt8v', 'Com brasileiros, não há quem possa! Futebol e identidade nacional em José Lins do Rego, Mário Filho e Nelson Rodrigues', NULL, '["Fatima Martin Rodrigues Ferreira Antunes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'As idéias de José Lins do Rego, Mário Filho e Nelson Rodrigues expressas por meio de um discurso acalorado que identifica o futebol como um dos elementos mais importantes na construção do imaginário popular do que significa ser brasileiro. Os textos desses escritores são documentos históricos por mobilizarem as atenções de uma época e participarem do processo de construção da identidade nacional. Com base na análise de suas crônicas publicadas em jornais e revistas, o livro revisita o passado, verifica como ele ecoa no presente e traça elos entre o futebol e a brasilidade.', '["football","national identity","Brazilian national identity","José Lins do Rego","Nelson Rodrigues","popular imaginary","chronicles","Brazilian literature"]', '10.7476/9788539302789', '9788571395237', 'https://books.scielo.org/id/gkt8v', NULL, NULL, 'https://books.scielo.org/id/gkt8v/cover/cover_thumbnail.jpeg', 301, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gkyrc', 'gkyrc', 'Aedes de A a Z', NULL, '["Denise Valle","Raquel Aguiar","Denise Nacif Pimenta","Vinicius Costa Nunes Ferreira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-03-16', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro reúne especialistas com diferentes formações - uma bióloga, uma antropóloga e dois profissionais de comunicação - para um panorama do mosquito Aedes aegypti. A obra da coleção Temas em Saúde responde a questões como as particularidades que tornam o Aedes tão presente em nossa rotina e as estratégias de controle e vigilância do vetor. Segundo os quatro autores, o título oferece ao leitor "um meio do caminho entre um texto corrido e um glossário", além de apresentar uma lista de siglas e termos técnicos. Os cinco capítulos são divididos em tópicos - com títulos curtos e objetivos – com abordagens específicas sobre o Aedes.', '["Aedes aegypti","mosquito vectors","dengue vector control","vector surveillance","mosquito biology","vector-borne diseases","terminology"]', '10.7476/9786557080986', '9786557080306', 'https://books.scielo.org/id/gkyrc', NULL, NULL, 'https://books.scielo.org/id/gkyrc/cover/cover_thumbnail.jpeg', 172, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gm5jz', 'gm5jz', 'Hortas: sob um olhar que você nunca viu', NULL, '["Cardoso, Antonio Ismael Inácio","Magro, Felipe Oliveira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'É indiscutível a importância econômica das hortaliças no Brasil, cuja cadeia produtiva movimenta bilhões de reais por ano. Porém, são poucas as publicações sobre o aspecto didático, lúdico e terapêutico que elas podem estimular. Nesta obra estão reunidos exemplos de como a horta pode, além de fornecer à população alimentos frescos e saudáveis, ser uma ferramenta de prática educativa, integração social e preservação ambiental. São apresentados aqui diferentes projetos que tem a horta como atividade central para envolver variados grupos: crianças, pessoas com necessidades especiais, reeducandos do sistema prisional, estudantes e a população em geral. Entre os resultados desses diferentes projetos, temos em comum a economia de recursos financeiros; o aumento do consumo de hortaliças, a satisfação pelo trabalho ao ar livre, a conscientização ambiental e o estímulo do senso de equipe. A partir dessas experiências, os autores analisam os projetos que tiveram a horta como ferramenta de integração social para promover benefícios a todos os envolvidos no seu cultivo, inclusive com a participação de docentes, alunos e ex-alunos da Universidade Estadual Paulista (Unesp).', '["school gardens","vegetable production","educational project","social integration","environmental awareness","children","people with special needs","environmental education","teamwork","fresh food consumption"]', '10.7476/9786557140574', '9786557140574', 'https://books.scielo.org/id/gm5jz', 'https://books.scielo.org/id/gm5jz/pdf/cardoso-9786557140574.pdf', NULL, 'https://books.scielo.org/id/gm5jz/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gm87z', 'gm87z', 'Figurações contemporâneas do espaço na literatura', NULL, '["Sérgio Vicente Motta","Susanna Busato"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'NOVAS CONFIGURAÇÕESFigurações contemporâneas do espaço na literatura abre-se a uma diversidade de acepções que o conceito de espaço abriga nos objetos e cenários literários contemporâneos.O próprio texto como um espaço espacializante, na sua textualidade como corpo ou na visualidade da escrita, configura um espaço de linguagem.O contexto cultural e histórico envolve referências e dados situados em determinados momentos que articulam um espaço de relações com o texto literário.O espaço da institucionalização, com as representações de poder, o espaço social, o espaço como paisagem, nas configurações natural, regional, física e psicológica, e o espaço do mito, com suas imagens e sentidos simbólicos, são outras formas de mobilização do conceito.O espaço pictórico, quer como elemento componente da pintura ou como a própria linguagem na composição da escritura, que se vale de técnicas plásticas, também é contemplado, assim como esse tipo de diálogo abriga outros meios e linguagens, como o cinema, a propaganda, a fotografia, nas relações entre as artes.Há também a possibilidade de se rever o objeto literário, em termos de espacialidade, sob essa perspectiva múltipla do olhar contemporâneo.Ou seja, no lugar daquele sentido restrito de categoria estrutural, o conceito incorpora uma visão ampla e metafórica, dentro da qual o próprio texto faz emergir uma concepção e função da espa-cialidade por meio de suas estratégias de construção.Diante de tantas possibilidades de leitura do conceito, o presente livro reúne textos de docentes do Programa de Pós-Graduação em Letras da Universidade Estadual Paulista (UNESP), campus de São José do Rio Preto, que abordam aspectos da simbolização espacial em obras literárias que implicam um olhar contemporâneo para essas figurações.No primeiro texto, Susanna Busato traz uma reflexão sobre a experiência da recusa ou do deslocamento na poesia brasileira contemporânea em "A consciência do zero como a lógica da razão antropofágica da poesia brasileira contemporânea".A partir da imagem do "vazio" como um espaço de contradições do tempo presente, o ensaio se concentra na poesia de Frederico Barbosa, cuja linguagem poética atua como uma revisão crítica da linguagem que se torna criação, afirmando-se como um processo de invenção.Em "O espaço libidinal da leitura e da escrita em Llansol", Sônia Helena de O. Raymundo Piteri explora a confluência da escrita e da leitura na obra da escritora portuguesa contemporânea Maria Gabriela Llansol.O texto mostra como a escritora, sob uma perspectiva diferenciada, alia corpo e mente num todo indiscernível e harmônico ao criar combinações como "sexo de ler" e "luar libidinal".Também demonstra como, paralelamente, há uma consonância entre o escrevente e o legente, na medida em que o ato de leitura é incitado pela energia procedente do sexo, que, por sua vez, advém da luz que incide sobre o escrevente no momento da construção do texto.Arnaldo Franco Junior aborda, no capítulo "Da literatura como espaço fotográfico-pictórico em textos reescritos de Dalton Trevisan", relações entre literatura, fotografia e artes plásticas.O ensaísta demonstra que, no projeto literário e na escrita singulares do escritor, a literatura, desde o seu suporte primeiro -o espaço em branco da folha de papel -até a sua constituição como espaço plástico, é passível de ser concebida como imagem que remete à fotografia e/ou à pintura.O texto "À procura de ilhas (des)conhecidas", de Maria Heloísa Martins Dias, desenvolve uma análise crítica de distintos textos com o propósito de desvendar como se configuram, por procedimentos de construção da linguagem, espaços em que se tramam relações iden-Como trilhar os caminhos que hoje a poesia brasileira constrói em termos de uma consciência crítica da linguagem?Seguir o roteiro das dimensões de espaço e tempo, por meio das quais a poesia de hoje organiza o seu espaço de linguagem, é uma trilha possível e necessária para compreender um tempo de traçados vários, que vão alinhavando e indicando os roteiros que pretendem seguir, de modos diferentes, uma trajetória de recusa para o mesmo.A experiência da recusa ou do deslocamento implica sempre um gesto crítico.A consciência de um tempo presente revela-se hoje como flagrante do "vazio" e como imagem do "obstáculo".Consciência que emerge, por exemplo, como aquela que, para o sujeito do poema de Manuel Bandeira (1982, p.93):Momento num café, tomara o sentido do espaço, ocupado num primeiro momento enquanto imagem denotada da existência, para perceber-se como margem para um espaço metafísico, transcendente e conotado, considerado como desvio no paradoxo flagrado: "a vida é traição", [diante da matéria] que passava/Liberta para sempre da alma extinta.* Doutora em Letras pela Universidade Estadual Paulista (UNESP) e professora-as sistente da mesma instituição, campus de São José do Rio Preto.de poesia, fazer desse "nada" formal a busca da forma poética no verso novamente, auscultando aquilo que a época do presente do poeta lhe oferece como eco de tantas experimentações no campo do poético.As possibilidades de trabalho com o verso são várias, e Frederico Barbosa (1990, p.31) irá colher nesses espaços sua "flor de farol", sua metáfora da poesia entrelaçada aos resíduos do agora.Referências bibliográficas', '["space in literature","spatiality","contemporary Brazilian poetry","emptiness","zero"]', '10.7476/9788579830990', '9788579830990', 'https://books.scielo.org/id/gm87z', 'https://books.scielo.org/id/gm87z/pdf/motta-9788579830990.pdf', NULL, 'https://books.scielo.org/id/gm87z/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gmfms', 'gmfms', 'Práticas musicais afrodiaspóricas e seus atravessamentos: perspectivas para pensar a formação em artes no Brasil', 'perspectivas para pensar a formação em artes no Brasil', '["Souza, Luan Sodré de"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra, reúne textos de pessoas negras pesquisadoras no campo das Artes e engajadas com uma intelectualidade negra no Brasil, característica que se faz notória por meio das perspectivas, das escritas, das experiências, das formas de ser e de estar no mundo, mas também por seus posicionamentos políticos. Dessa forma, esta obra é um convite para uma imersão, para pensarmos as práticas musicais afrodiaspóricas e seus atravessamentos como perspectivas para pensar formação em artes no Brasil.', '["music practice","Black intellectuals","Black researchers","art education","Brazil"]', '10.7476/9788555921599', '9786589524731', 'https://books.scielo.org/id/gmfms', NULL, NULL, 'https://books.scielo.org/id/gmfms/cover/cover_thumbnail.jpeg', 210, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gmjq4', 'gmjq4', 'Mudanças climáticas, desastres e saúde', NULL, '["Christovam Barcellos","Corvalán, Carlos","Silva, Eliane Lima e"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-09-28', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'O livro pretende contribuir com estratégias para aumentar a resiliência do setor Saúde e das comunidades em face das mudanças climáticas e seus impactos. A obra mostra que mudanças ambientais e climáticas interagem entre si, abordando como a complexa relação entre saúde e ambiente vem sendo cada vez mais discutida. Apesar de avanços na saúde e considerando um aumento na expectativa de vida no Brasil, diversos estudos apontam que, nas últimas décadas, desequilíbrios ambientais têm causado efeitos negativos à sociedade, afetando direta e indiretamente a saúde humana. No país, os desastres de origem climática que mais se destacam têm origem em processos hidrológicos - chuvas intensas, inundações bruscas, deslizamentos de terra relacionados às chuvas e inundações graduais - e climatológicos (secas, estiagens e crises hídricas). Composto por 12 capítulos, o título reúne cerca de 30 especialistas das mais diversas áreas, confirmando a inquestionável capacidade técnico-científica de pesquisadores brasileiros que se dedicam à temática da mudança climática nos seus diferentes aspectos.', '["climate change","climate-related disasters","health impacts of climate change","community resilience","environmental health","floods","landslides","drought","water crisis"]', '10.7476/9786557081679', '9786557081259', 'https://books.scielo.org/id/gmjq4', NULL, NULL, 'https://books.scielo.org/id/gmjq4/cover/cover_thumbnail.jpeg', 343, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gnfy3', 'gnfy3', 'Circos e palhaços brasileiros', NULL, '["Mário Fernando Bolognesi"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O Circo di Roma foi visitado duas vezes.Na primeira, em agosto de 1997, na cidade de Marília-SP; a segunda, em Palmeira das Missões-RS, em 30 de janeiro de 1999.O circo era grande, com boa estrutura física e muitos recursos sonoros e de iluminação.O primeiro espetáculo assistido foi de grande diversidade, com artistas que demonstraram perícia técnica, porém carentes de melhor acabamento nos números, tais como uma coreografia melhor trabalhada, um figurino de realce e melhor integração entre movimento e música.Na segunda vez, no Sul do país, o encontro foi casual.Em Quilombo-SC, foi encontrado o Circo Xangai.Os contatos com as prefeituras da região indicavam que a viagem deveria prosseguir para a cidade de Coronel Martins, em busca do Circo Teatro Brasil e, depois, para Palmeira das Missões, ao encontro do Biriba.Nada ocorreu como planejado.O caminho de Quilombo para Coronel Martins não era asfaltado, com aproximadamente 40 quilômetros de região serrana.O tempo estava chuvoso.O itinerário foi alterado e a viagem tomou o rumo de Palmeira das Missões, no Rio Grande do Sul, um percurso de 210 quilômetros.Pelas informações obtidas na prefeitura local, Biriba estaria em Palmeira das Missões.Porém, ali chegando, foi encontrado o Circo di Roma.O Circo di Roma foi, então, visitado pela segunda vez.O contato com o Roma também elucidou o paradeiro do Biriba: estava em Redentora, uma pequena cidade a 40 quilômetros de Palmeira das Missões.Primeiro espetáculo: Marília (SP) Primeira parte: Pêndulo; Clowns musicais; Pombas amestradas; Acrobacia com facas e bolas; Chevrolé e Parafuso em "Os atiradores de facas"; Bicicleta; Equilibrismo de bolas; Urso amestrado; Chevrolé e Parafuso em "O salto mortal na escada com a lata na mão"; Malabares.Segunda parte: Trapézio Voador, com a participação do palhaço Chevrolé; Chevrolé e Parafuso em "A magia com patos"; Rola-rola; Corda indiana; Volteio; Pôneis amestrados; Elefante; Globo da Morte; Apoteose.Segundo espetáculo: Palmeira das Missões (RS) Primeira parte: Trapézio Voador, com a participação do palhaço Chevrolé; Chevrolé e Parafuso em "O salto mortal na escada com a lata na mão"; Laços e chicotes; Chevrolé e Parafuso em "O namoro dos palhaços"; Bambolê; Malabares.Segunda parte: Double trapézio; Cavalo amestrado; Chevrolé e Parafuso em "A magia com patos"; Pôneis amestrados; Trapézio em Balanço; Corda indiana; Elefantes. ChevroléOs palhaços eram os mesmos nos dois espetáculos: Chevrolé e Parafuso.Chevrolé participou do trapézio.A trupe de voos era composta de três elementos apenas, o aparador, um volante e o palhaço.', '["clowns","circus performance","Marília","Palmeira das Missões","quilombos","Rio Grande do Sul"]', '10.7476/9788579830211', '9788579830211', 'https://books.scielo.org/id/gnfy3', 'https://books.scielo.org/id/gnfy3/pdf/bolognesi-9788579830211.pdf', NULL, 'https://books.scielo.org/id/gnfy3/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gnqms', 'gnqms', 'Epidemiologia no pós-pandemia: de ciência tímida a ciência emergente', NULL, '["Naomar de Almeida Filho"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Naomar de Almeida Filho, renomado epidemiologista brasileiro, apresenta uma análise crítica da evolução da epidemiologia, que passou de uma ciência "tímida" a um campo central na saúde coletiva, especialmente no contexto da pandemia de COVID-19. O autor revisita conceitos como risco, causalidade e desigualdades em saúde, propondo uma abordagem integradora que combina saberes biomoleculares, sociais e culturais. Nesta tradução, revista e ampliada, com capítulos inéditos sobre sindemias, infodemiologia e transdisciplinaridade, Almeida Filho propõe uma teoria unificada de saúde-enfermidade-cuidado e uma revisão da epidemiologia sob a ótica da complexidade. A obra também introduz a "etnoepidemiologia", que integra saberes socioculturais na compreensão dos processos de saúde. Com uma escrita crítica e rigorosa, o autor desafia os limites da disciplina, sugerindo que a epidemiologia deve considerar as interações sociais e históricas que moldam a saúde. O livro é essencial para profissionais da saúde, pesquisadores e todos os interessados na evolução da epidemiologia pós-pandemia.', '["epidemiology","COVID-19 pandemic","risk","causality","health disparities","syndemic","infodemiology","transdisciplinarity","complexity","sociocultural knowledge"]', '10.7476/9786557082300', '9786557081945', 'https://books.scielo.org/id/gnqms', NULL, NULL, 'https://books.scielo.org/id/gnqms/cover/cover_thumbnail.jpeg', 699, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gp99j', 'gp99j', 'Retórica à moda brasileira: transições da cultura oral para a cultura escrita no ensino fluminense de 1746 a 1834', NULL, '["Maria Renata da Cruz Duran"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nas palavras da autora, o estudo seguiu “um impulso de explicar, por um lado, o modo de ser do brasileiro, seu gosto pela conversa fiada, suas silabadas políticas; e, por outro, de descobrir a genealogia dos sistemas acadêmicos luso-brasileiros, revelando o fraco dos intelectuais tupiniquins pelo louvor, pela exibição pública, pela esgrima das palavras”. A pesquisa, porém, levou a autora a investigar e analisar a instrução de caráter retórico ministrada desde o tempo do Marquês de Pombal e seus reflexos no Brasil sob Pedro I. O período é balizado por duas obras relevantes para a história das relações escolares no país: O verdadeiro método de estudar, de Luís Antônio Verney, de 1746, base teórica para a reforma na instrução lusófona, e as Lições elementares de eloquência nacional para uso da mocidade de ambos os hemisférios, de Francisco Freire de Carvalho, de 1834, que uniformizaram o ensino da retórica no Brasil. Por meio de um texto claro e com pitadas de bom humor, a autora revela a importância que o ensino da retórica teve no uso da língua portuguesa, na medida em que a matéria contribuiu no estabelecimento de regras comuns para o idioma e influenciou a formação de “um conjunto de palavras comuns e de um jeito de falar peculiar que, depois, chamou-se de brasileiro”. A partir desse quadro, a historiadora analisa como a cultura oral marcada pela retórica transferiu-se para a cultura escrita, representada pela imprensa da época, e de que forma fomentou o gosto pela leitura e pela escrita no Rio de Janeiro da época.', '["rhetoric education","orality","written culture","history of education","Marquis of Pombal","Brazilian national character","reading and writing","Rio de Janeiro","colonial Brazil","18th century","19th century"]', '10.7476/9786557144909', '9786557144909', 'https://books.scielo.org/id/gp99j', 'https://books.scielo.org/id/gp99j/pdf/duran-9786557144909.pdf', NULL, 'https://books.scielo.org/id/gp99j/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gpp3z', 'gpp3z', 'Europa, França e Bahia: difusão e adaptação de modelos urbanos (Paris, Rio e Salvador)', NULL, '["Eloísa Petti Pinheiro"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Nesta obra, a autora discute o processo de modernização e a constituição de um pensamento de prática urbanística no Brasil, analisando a influência europeia nas criações urbanas. O ponto de partida são as relações entre a reforma de Paris realizada em meados do século XIX pelo Barão Haussmann, a reforma capitaneada por Pereira Passos no Rio de Janeiro no início do século XX e a reforma ocorrida em Salvador durante a primeira gestão do Governador José Joaquim Seabra, entre os anos de 1912 e 1916.', '["urban modernization","urban planning","urban reform","Baron Haussmann","Paris","Pereira Passos","Rio de Janeiro","Salvador, Bahia","Bahia","19th century","early 20th century"]', '10.7476/9788523211912', '9788523211912', 'https://books.scielo.org/id/gpp3z', 'https://books.scielo.org/id/gpp3z/pdf/pinheiro-9788523211912.pdf', NULL, 'https://books.scielo.org/id/gpp3z/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gqp9f', 'gqp9f', 'Um intelectual na urgência: Pasolini lido no Brasil', NULL, '["Amoroso, Maria Betânia","Alves, Cláudia Tavares"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro reúne, em um mesmo volume, certa crítica brasileira que vem sendo escrita desde os anos 1960 sobre a obra e a figura do intelectual italiano Pier Paolo Pasolini. Para tanto, autores e autoras dos textos aqui reunidos foram convidados(as) a adentrar o universo pasoliniano pela fresta que melhor lhes conviesse, traçando, dessa forma, rotas próprias pela obra do autor. Cinema, literatura, teatro, crítica, ensaísmo, enfim, percursos abertos pelo pensamento pasoliniano.', '["Pier Paolo Pasolini","Italian intellectuals","film criticism","literary criticism","essay writing","theatre"]', '10.7476/9788526816701', '9788526815582', 'https://books.scielo.org/id/gqp9f', NULL, NULL, 'https://books.scielo.org/id/gqp9f/cover/cover_thumbnail.jpeg', 290, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gr7y8', 'gr7y8', 'V:\SciELOLivros\books\eduepb\VIII Reunião\eng_can_acu_par\epub', NULL, '["José Luciano Albino Barbosa"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Estudar a dinâmica cultural de transformação da cachaça de engenho paraibana, compreendendo como algo se transforma, em termos simbólicos, tornou-se o objetivo deste livro. O estudo foi realizado na região do Brejo paraibano, conhecido pelos conflitos de terra, a exemplo das Ligas Camponesas, e a cultura da cana-de-açúcar processada em engenhos seculares, tal romanceou José Lins do Rego. Assim, este livro se propõe a uma sociologia da cachaça. Uma viagem analítica, mas também de inspiração literária, ao cenário paraibano onde a mesma é produzida e sofre ressignificação, tornando-se requintada e sinônimo de originalidade em cachaçarias e pousadas campestres.', '["cachaça","sugarcane","sugar mills","cultural change","Brejo Paraibano","land disputes","José Lins do Rego","Pará"]', '10.7476/9788578793302', '9788578793302', 'https://books.scielo.org/id/gr7y8', 'https://books.scielo.org/id/gr7y8/pdf/barbosa-9788578793302.pdf', NULL, 'https://books.scielo.org/id/gr7y8/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-grnqp', 'grnqp', 'Reconceituações contemporâneas do patrimônio', NULL, '["Marco Aurélio A. de Filgueiras Gomes","Elyane Lins Corrêa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta publicação faz parte da Coleção ArquiMemória, e origina-se de discussões desenvolvidas no quadro de um encontro organizado pelo Instituto de Arquitetos do Brasil, em 2008. Dentre os temas abordados em Reconstituições contemporâneas do patrimônio, estão os pressupostos teóricos das políticas para o patrimônio; as tendências contemporâneas na Teoria da Restauração; a preservação da Feira de São Joaquim; o patrimônio cultural e os problemas urbanos.', '["heritage policy","restoration theory","cultural heritage","urban problems","architectural heritage"]', '10.7476/9788523212278', '9788523207434', 'https://books.scielo.org/id/grnqp', NULL, NULL, 'https://books.scielo.org/id/grnqp/cover/cover_thumbnail.jpeg', 286, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gsfw7', 'gsfw7', 'Bilac vivo', NULL, '["Álvaro Santos Simões"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Com Poesias (1888) e Tarde (1919), entre outras obras, Olavo Bilac (1865-1918) insere seu nome na história da literatura brasileira como um dos principais poetas parnasianos, dos quais é certamente o mais popular, graças à sensualidade decorosa e ao sentimentalismo mitigado, além da habilidade versificatória. Junto a seus contemporâneos, o escritor adquire também sólida reputação como jornalista, orador e intelectual politicamente empenhado. Neste livro, estão reunidos ensaios que contemplam várias facetas da múltipla atuação pública de Bilac e põem em relevo algumas de suas intervenções em favor da liberdade de imprensa, da democracia, do saneamento e da modernização urbanística do Rio de Janeiro, do serviço militar obrigatório (no contexto da Primeira Guerra Mundial) e do ensino (básico) universal, público, gratuito e de qualidade. Autor de sátiras e crônicas políticas, Olavo Bilac, nos primeiros anos da República, afirma-se inclusive como um dos mais aguerridos críticos do presidente Floriano Peixoto (1839-1895), que o encarcera e obriga-o a autoexilar-se em Minas Gerais.', '["Olavo Bilac","Brazilian literature","Parnassianism","freedom of the press","democracy","sanitation","urban modernization","Rio de Janeiro","conscription","World War I","universal education","political satire"]', '10.7476/9788595461796', '9788595461796', 'https://books.scielo.org/id/gsfw7', 'https://books.scielo.org/id/gsfw7/pdf/simoes-9788595461796.pdf', NULL, 'https://books.scielo.org/id/gsfw7/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gshz7', 'gshz7', 'A diplomacia da americanização de Salvador de Mendonça (1889-1898)', NULL, '["Gabriel Terra Pereira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'A transição da Monarquia para a República no Brasil foi cercada de conturbados eventos no plano interno, em razão do "vazio de poder" decorrente das instituições decaídas, e no plano externo, eleito como ponto de referência e de legitimidade para a boa condução do país. Partindo do pressuposto de que havia porosidade entre a política interna e a política externa, a diplomacia exerceu alta influência nos acontecimentos domésticos nacionais, referendando principalmente o relacionamento com os Estados Unidos como o ponto de apoio à instável política interna. O maior representante dessa linha de atuação foi Salvador de Mendonça, diplomata do Brasil nos Estados Unidos. Americanista convicto, ele diplomata trabalhou pela aproximação - leia-se americanização - do Brasil, intervindo em três ocasiões: na Conferência Americana de 1889-1890 em Washington, na assinatura do Tratado de Reciprocidade Comercial de 1891 e durante a Revolta da Armada no Rio de Janeiro em 1893-1894. Fundamentando a pesquisa em sua na correspondência diplomática, o autor desta obra mostra a importância da atuação de Salvador de Mendonça na aproximação com os Estados Unidos, processo que ao longo de quase uma década tornou sinônimas as idéias de republicanização e americanização da esfera política brasileira.', '["Americanization","Brazilian diplomacy","Brazil–United States relations","republicanization","diplomatic correspondence"]', '10.7476/9788579830068', '9788579830068', 'https://books.scielo.org/id/gshz7', 'https://books.scielo.org/id/gshz7/pdf/pereira-9788579830068.pdf', NULL, 'https://books.scielo.org/id/gshz7/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gsqc9', 'gsqc9', 'Hegemonías y subalteridades urbanas: la configuración metropolitana de Quito', NULL, '["Víctor Hugo Torres Dávila"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'El libro propone una interpretación cultural de la configuración metropolitana de Quito. El argumento es más allá del interés municipal en fortalecer su capacidad institucional para controlar la expansión urbana, la adopción de la condición metropolitana implicó una “formación simbólica”, un sistema de sentidos y significados especiales que contenían una visión de la urbe como una ciudad ordenada. Explica algo que parece fluido y natural; el sometimiento del sentido metropolitano de la ciudad a las ideas y valores de las élites quiteñas, y que los demás grupos sociales consienten sin mayores resistencias. La investigación se adentra en el desconcertante ámbito de los circuitos ideológicos que cohesionan a la sociedad urbana, para comprender la predisposición de sus habitantes a emular formas de vida de las clases acomodadas, activada por la capacidad de persuasión simbólica de la modernidad colonial urbana, a través de la cual la mayoría de sus residentes, lejos de cuestionar el sometimiento al individualismo disuelven las identidades colectivas, para integrarlas a la dinámica metropolitana. El autor polemiza sobre la respuesta social mediante el análisis del movimiento barrial quiteño y las inserciones urbanas de los pueblos indígenas y afroquiteños.', '["hegemony","subalternity","Quito","urban expansion","symbolic formation","urban elites","individualism","collective identity","indigenous settlements","urban periphery"]', '10.7476/9789978105757', '9789978105757', 'https://books.scielo.org/id/gsqc9', 'https://books.scielo.org/id/gsqc9/pdf/torres-9789978105757.pdf', NULL, 'https://books.scielo.org/id/gsqc9/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gv75q', 'gv75q', 'Genocidios indígenas en América Latina', NULL, '["Salamanca Villamizar, Carlos","Rita Ramos, Alcita"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2023, '2023-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Todas las naciones americanas se construyeron sobre los escombros de múltiples mundos indígenas. A partir de testimonios e investigaciones realizadas en Argentina, Brasil y Colombia, en este libro se documentan los severos abusos perpetrados por agentes del Estado, colonos y empresas desde el surgimiento mismo de los Estados hasta la actualidad. El libro Genocidios indígenas en América Latina (Carlos Salamanca y Alcida Rita Ramos, comps. 2023) tiene como origen un seminario internacional realizado en la Universidad de Brasilia en 2019 y se compone de testimonios de antropólogos, documentalistas, abogados y otros profesionales de la rama judicial, indígenas y no indígenas.', '["indigenous genocide","colonialism","indigenous testimony","human rights violations","indigenous rights","Latin America","Argentina","Brazil","Colombia"]', '10.7476/9789942099419', '9789942098825', 'https://books.scielo.org/id/gv75q', NULL, NULL, 'https://books.scielo.org/id/gv75q/cover/cover_thumbnail.jpeg', 389, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gvzb8', 'gvzb8', 'O louco, a rua, a comunidade: as relações da cidade com a loucura em situação de rua', NULL, '["Angela María Pagot"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os ‘loucos’ em situação de rua não escolheram viver nessa condição. Não estão vinculados a Centros de Atenção Psicossocial (Caps), a Unidades Básicas de Saúde (UBS) nem às Equipes de Saúde da Família (ESF). Não se conhece a história de vida desses indivíduos. E o único vínculo que eles mantêm é com a população do bairro por onde vagueiam. Os moradores do bairro, então, mesmo sem se darem conta disso, adquirem um saber sobre aqueles ‘loucos’. Investigar os ‘olhares’ desses moradores, para compreender o que pensem, sentem, dizem e fazem em relação aos ‘loucos’, é o objetivo do livro. Neste estudo, embasado na teoria das representações sociais, a autora defende que, apesar das dificuldades e até dos preconceitos, os moradores do bairro têm potencial para atuarem como agentes de saúde mental. “Pois enquanto o ‘louco’ permanecer na rua pertencerá não apenas ao Estado, mas também às pessoas do bairro onde se encontra”, destaca.', '["homeless people with mental illness","street homelessness","social representations","mental health","prejudice","neighborhood residents","urban mental health"]', '10.7476/9788575415771', '9788575412961', 'https://books.scielo.org/id/gvzb8', NULL, NULL, 'https://books.scielo.org/id/gvzb8/cover/cover_thumbnail.jpeg', 230, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gxm8v', 'gxm8v', 'Aves do Parque Nacional da Furna Feia', NULL, '["Vitor de Oliveira Lunardi","Diana Gonçalves Lunardi","Rafael Dantas Lima"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'O Parque Nacional da Furna Feia – uma Unidade de Conservação de Proteção Integral da Natureza – foi criado em 05 de junho de 2012, Dia Mundial do Meio Ambiente, com o objetivo de conservar a biodiversidade da Caatinga oeste potiguar. A criação desta área natural protegida foi fruto de esforços do Ministério do Meio Ambiente, em especial do Instituto Chico Mendes de Conservação da Biodiversidade/ICMBio e do Centro Nacional de Pesquisa e Conservação de Cavernas/CECAV, além de ter contado com o apoio de diferentes representações governamentais e não-governamentais desta região. O Parque Nacional da Furna Feia abrange aproximadamente 8.500ha, contemplando lajedos, mais de 200 cavernas e um relevante remanescente florestal de Caatinga, que juntos abrigam uma diversa fauna, flora e microbiota. É com enorme carinho e muita satisfação que apresentamos ''Aves do Parque Nacional da Furna Feia'', obra que divulga a riqueza de espécies de aves e informações sobre a sua biologia e ecologia nesta região, registradas durante expedições científicas mensais, realizadas entre 2013 e 2018. Esperamos que esta obra estimule pessoas de todas as idades, em especial, crianças e jovens, a conhecerem e apreciarem a beleza das aves, a diversidade de formas, a intensidade de cores e a musicalidade de cantos, que nos fascinam e despertam, em nós, os melhores sentimentos. Convidamos você a viajar conosco para este rico universo das Aves do Parque Nacional da Furna Feia!', '["birds","Caatinga","bird species richness","bird biology","avian ecology","protected areas","biodiversity conservation","Lajas","caves","birdwatching"]', '10.7476/9788557571587', '9786587108308', 'https://books.scielo.org/id/gxm8v', 'https://books.scielo.org/id/gxm8v/pdf/lunardi-9788557571587.pdf', NULL, 'https://books.scielo.org/id/gxm8v/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gz7y4', 'gz7y4', 'Alocações, estabilidade e otimização: uma introdução passo a passo', NULL, '["Aline Guarnieri Gubitoso"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', '"Este livro trata da formação de correspondências estáveis entre agentes ou entidades de qualquer natureza, como, por exemplo, casar homens e mulheres de modo que dois participantes não se sintam frustrados por não estarem casados entre si. Um procedimento passo a passo para atingir esse objetivo foi documentado de modo geral em 1962 e teve tanto desenvolvimento e aplicabilidade que foi reconhecido em uma premiação Nobel cinquenta anos depois. É, portanto, assunto perfeito para desenvolver o raciocínio lógico, tomar contato com tópicos de Economia, Computação e Matemática, conhecer o trabalho acadêmico e investigar soluções para problemas correlatos. Os estudantes do ensino médio ou no início da formação universitária encontram, aqui, um tema para estudo individual ou sob supervisão do professor. Apresentamos os problemas dessa área e metodologias para resolvê-los, com destaque para o algoritmo Gale-Shapley; considerações sobre eficiência; as variantes que incluem indiferenças, grupos com números diferentes de agentes e agentes com várias conexões, como universidades com múltiplas vagas para vestibulandos e o caso histórico da residência médica nos EUA; a otimização linear, o algoritmo Simplex e a resolução desses problemas no Excel; a possibilidade de manipulação das alocações, ou ""trapaça"", e práticas para sua redução; a questão de parear elementos de um único grupo, com colegas em quartos. Como um desafio concreto, o último capítulo explora o sistema de matrículas em disciplinas na Universidade Federal do ABC, que privilegia a livre formação curricular, e uma sugestão dos autores para uma implementação das técnicas desenvolvidas."', '["stable matching","Gale-Shapley algorithm","matching markets","efficiency","indifference","linear programming","simplex algorithm","roommate problem","course registration system","curriculum flexibility"]', '10.7476/9788568576823', '9788568576823', 'https://books.scielo.org/id/gz7y4', 'https://books.scielo.org/id/gz7y4/pdf/gubitoso-9788568576823.pdf', NULL, 'https://books.scielo.org/id/gz7y4/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gzfqw', 'gzfqw', 'Etnomusicologia no Brasil', NULL, '["Angela Lühning","Rosângela Pereira de Tugny"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Com o objetivo de apresentar a área da etnomusicologia ao público brasileiro e fortalecer a discussão sobre a diversidade cultural e musical no país, o livro reúne textos de coletivos de autores que vêm realizando, nas duas últimas décadas, pesquisas expressivas no cenário cultural brasileiro. Colocando-se no diálogo teórico com a etnomusicologia de outros países, a obra se desdobra sobre o papel e o perfil da etnomusicologia brasileira, destacando sua qualidade etnográfica, a qual aparece como uma teoria alternativa, nova, radical e transformada pela prática ativista e o surgimento de vozes e agentes antes silenciados nos processos de legitimação acadêmica.', '["cultural diversity","musical diversity","ethnographic fieldwork","activist research","marginalized voices","alternative theories"]', '10.7476/9788523218805', '9788523215538', 'https://books.scielo.org/id/gzfqw', NULL, NULL, 'https://books.scielo.org/id/gzfqw/cover/cover_thumbnail.jpeg', 323, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gzqf6', 'gzqf6', 'Análisis estratégico en salud y gestión a través de la escucha', NULL, '["Francisco Javier Uribe Rivera"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Este libro reúne una serie de trabajos, cuyo hilo conductor representa una propuesta teórico metodológica de gestión, que se traduce en el título: Análisis Estratégico en Salud y Gestión a través de la Escucha. Javier Uribe y sus colaboradores exploran la particularidad institucional de los sistemas de salud que se configuran como organizaciones profesionales. Estas organizaciones dependen, fundamentalmente, de sus centros operadors y no responden bien a mecanismos de formalización y control de sus procesos de trabajo. El libro se articula en torno del concepto de liderazgo como posibilidad intersubjetiva de desarrollo del consenso necesário para el funcionamiento productivo de una organización y la promoción de los câmbios necesários. Un libro indispensable para los que enseñan y practican la gestión de sistemas y servicios de salud.', '["strategic analysis","health management","listening","leadership","organizational change","consensus building"]', '10.7476/9788575415429', '9788575415429', 'https://books.scielo.org/id/gzqf6', 'https://books.scielo.org/id/gzqf6/pdf/rivera-9788575415429.pdf', NULL, 'https://books.scielo.org/id/gzqf6/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h2cyy', 'h2cyy', 'Geo Foto Grafia: narrativas espaciais nas imagens de Sebastião Salgado', NULL, '["Flora Sousa Pidner"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra apresenta um rico material de pesquisa que cria, por meio de uma incursão no universo fotográfico de Sebastião Salgado e de sua relação com a geografia, uma abordagem dialética e fenomenológica. A partir das diferentes “possibilidades de leitura de mundo” expressas pelo trabalho do fotógrafo, é possível explorar diversos momentos da marcante linguagem visual criada pelas imagens de Sebastião. Por meio das ferramentas sensíveis da emoção, da arte e da ciência, o(a) leitor(a) se torna capaz de adentrar o universo do grande fotógrafo brasileiro ao mesmo tempo que descobre os meandros da visão de Sebastião sobre o mundo e seus compromissos intelectuais e políticos.', '["Sebastião Salgado","spatial narrative","visual language","phenomenology","art and science","Brazilian photography"]', '10.7476/9786556302003', '9788523219109', 'https://books.scielo.org/id/h2cyy', NULL, NULL, 'https://books.scielo.org/id/h2cyy/cover/cover_thumbnail.jpeg', 293, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h3kby', 'h3kby', 'Crise global e sistemas de saúde na América Latina', NULL, '["José Antônio de Freitas Sestelo","Lígia Bahia","Eduardo Levcovitz"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-11-21', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra segue um fio condutor que apresenta ao leitor a ideia de que a estrutura de proteção social e, em particular, os sistemas de saúde de países importantes da América Latina experimentam uma série de mudanças em escala que configuram um novo padrão de articulação entre os Estados Nacionais, suas estruturas de governo e os principais agentes econômicos e políticos com interesses no setor saúde. Ela é fruto do trabalho desenvolvido pelo Grupo de Pesquisa e Documentação sobre o Empresariamento da Saúde Henry Jouval Jr. (GPDES), no Instituto de Estudos em Saúde Coletiva (IESC), Universidade Federal do Rio de Janeiro.', '["global crisis","health care system","Latin America","social protection","health policy"]', '10.7476/9786556304144', '9786556303499', 'https://books.scielo.org/id/h3kby', NULL, NULL, 'https://books.scielo.org/id/h3kby/cover/cover_thumbnail.jpeg', 319, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h3ncq', 'h3ncq', 'Dissidências sexuais e de gênero', NULL, '["Leandro Colling"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"As temáticas discutidas por toda a obra permeiam os estudos sobre as normatizações, as normalizações, as naturalizações, binarismos, sexualidades e os gêneros, para um eixo além da produção científica. Os artigos que compõem o livro problematizam e tencionam a forma permanente em que a produção científica na área é realizada e busca levar a compreensão de que produzir saber científico é um ato político, que o ativismo social também produz conhecimentos e toda essa produção precisa estar à serviço de políticas públicas para que as pessoas respeitem, reconheçam e aprendam com as múltiplas sexualidades e gêneros existentes na sociedade."', '["sexual dissidence","gender dissidence","sexuality","gender","normalization","naturalization","binarism","social activism","public policy","knowledge production"]', '10.7476/9788523220037', '9788523215385', 'https://books.scielo.org/id/h3ncq', NULL, NULL, 'https://books.scielo.org/id/h3ncq/cover/cover_thumbnail.jpeg', 240, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h48zk', 'h48zk', 'El presente permanente. Por una antropografía de la violencia a partir del caso de Urabá, Colombia', NULL, '["Silvia Monroy Álvarez"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2013, '2013-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este libro es un experimento que dialoga con la propuesta de una antropografía de la violencia a partir del caso de Urabá. Evitando la enunciación descarnada del horror y algunas tendencias de la “violentología”, busca dinamizar las narrativas de algunos eventos, de los momentos de los personajes y de las vivencias del investigador en el día a día. Al señalar cómo la violencia se torna matriz de las relaciones sociales, se identifica una orientación temporal denominada presente permanente, que es constituyente de un horizonte cosmológico en esta región, considerada una de las más violentas del país desde hace más de cuatro décadas. Los capítulos discuten algunos principios relativos al sistema de intercambio; la caracterización étnica definida por el vínculo al origen o a la procedencia; las dinámicas relacionadas con el cambio de afiliación de los combatientes y la diferenciación entre tierra y territorio, vinculada tanto a los estereotipos acerca de la “tierra caliente” y de las “zonas rojas” como a determinadas concepciones sobre los procesos de colonización, conquista y pacificación.', '["anthropology of violence","Urabá","temporality","exchange systems","ethnic identity","land and territory","stereotypes","colonization","pacification","everyday life narratives"]', '10.7476/9789585005396', '9789587383430', 'https://books.scielo.org/id/h48zk', 'https://books.scielo.org/id/h48zk/pdf/monroy-9789585005396.pdf', NULL, 'https://books.scielo.org/id/h48zk/cover/cover_thumbnail.jpeg', NULL, 17, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h4dh8', 'h4dh8', 'Antonio Carlos Nóbrega em acordes e textos armoriais', NULL, '["Luís Adriano Mendes Costa"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Escrito originalmente sob a forma de dissertação de mestrado, tendo como título "Movimento Armorial: o erudito e o popular na obra de Antônio Carlos Nóbrega", orientada pelo professor Sébastien Joachim e aprovada com distinção pela banca examinadora do Mestrado em Literatura e Interculturalidade da universidade Estadual da Paraíba, a presente obra traz para o conhecimento público e debate acadêmico mais um capítulo da história do Movimento Armorial. Antônio Carlos Nóbrega em acordes e textos Armoriais se caracteriza como uma contribuição para a ampliação do acervo e das pesquisas sobre o Movimento Armorial, através da música, atividade essa de maior repercussão nacional do Movimento, ainda em carência no universo das pesquisas científicas. Ampliam-se, dessa forma, as possibilidades de abordagens para com um capítulo importante da cultura brasileira, que ainda carrega marcas e reflete o Movimento criado por Ariano Suassuna.', '["Ariano Suassuna","Brazilian popular music","music and text","Brazilian popular culture","song lyrics"]', '10.7476/9788578791865', '9788578791865', 'https://books.scielo.org/id/h4dh8', 'https://books.scielo.org/id/h4dh8/pdf/costa-9788578791865.pdf', NULL, 'https://books.scielo.org/id/h4dh8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h4qmp', 'h4qmp', 'O desafio ambiental contemporâneo e a sustentabilidade ambiental local de comunidades', NULL, '["Paulo César Bahia de Aguiar","Mônica de Moura Pires"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra discute os desafios ambientais contemporâneos no contexto do capitalismo e do desenvolvimento sustentável, destacando a necessidade de uma visão holística e interdisciplinar. Estruturada em quatro textos, aborda desde aspectos históricos da relação entre capitalismo e crise ambiental até a realidade da Reserva Extrativista Marinha de Canavieiras, na Bahia. São analisados conflitos, paisagens, sustentabilidade local e a economia da pesca artesanal, revelando desigualdades socioeconômicas e limites do modelo capitalista. A coletânea contribui para ampliar o debate científico sobre sustentabilidade e comunidades, instigando reflexão e novas perspectivas de desenvolvimento.', '["environmental problems","environmental sustainability","local sustainability","community","capitalism","environmental crisis","sustainable development","fisheries dispute","landscape","socioeconomic disparities","Bahia"]', '10.7476/9788574556321', '9788574556123', 'https://books.scielo.org/id/h4qmp', 'https://books.scielo.org/id/h4qmp/pdf/aguiar-9788574556321.pdf', NULL, 'https://books.scielo.org/id/h4qmp/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h4qz3', 'h4qz3', 'Trajetórias e histórias insurgentes: os Kariri-Sapuyá da Pedra Branca, Recôncavo Sul Baiano', NULL, '["Maria Rosário de Carvalho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'No livro a autora busca reconstruir, por meio de documentação produzida no âmbito do Fundo de Documentação Histórica Manuscrita sobre os Índios da Bahia (Fundocin)/Programa de Pesquisas sobre Povos Indígenas do Nordeste Brasileiro (Pineb), a trajetória dos Kariri-Sapuyá, complementando-a, embora de modo limitado, com outras trajetórias e histórias indígenas. O livro está organizado em duas partes. A avaliação da autora sobre a relevância de certos temas para a compreensão do(a) leitor(a) serviu como termômetro para a composição da Parte I. Os capítulos subsequentes, na Parte II, têm como objeto o exame da documentação histórica manuscrita que compõe a denominada Coleção Pedra Branca.', '["indigenous peoples of Brazil","indigenous history","Pedra Branca","Recôncavo Baiano","indigenous oral narratives","historical documentation"]', '10.7476/9786556305066', '9786556303147', 'https://books.scielo.org/id/h4qz3', NULL, NULL, 'https://books.scielo.org/id/h4qz3/cover/cover_thumbnail.jpeg', 535, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h53wj', 'h53wj', 'As raças humanas e a responsabilidade penal no Brasil', NULL, '["Raymundo Nina Rodrigues"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[...] me limitarei a tentar a justificação do mais saliente, aliás, talvez o menos importante deles – o abuso e a extensão das citações –, pela necessidade de apoiar a contradita oferecida a doutrinas correntes e a opiniões de mestres justamente reputados as primeiras autoridades na matéria.', '["human races","criminal liability","criminal law doctrine","Brazil"]', '10.7476/9788579820755', '9788579820755', 'https://books.scielo.org/id/h53wj', 'https://books.scielo.org/id/h53wj/pdf/rodrigues-9788579820755.pdf', 'https://books.scielo.org/id/h53wj/epub/rodrigues-9788579820755.epub', 'https://books.scielo.org/id/h53wj/cover/cover_thumbnail.jpeg', 95, 54, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h5hnw', 'h5hnw', 'O estilo da Modernidade de Schinkel ao Werkbund', 'estudo sobre uma persistente ilusão a acompanhar a arquitetura moderna até nossos dias', '["Marcos Faccioli Gabriel"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Atribui-se ao arquiteto neoclássico prussiano Karl Friedrich Schinkel (1781-1841) o apelo à criação de um estilo próprio da modernidade em vez da imitação do passado. O historiador da arquitetura Reyner Banham (1922-1988) considerava a arquitetura moderna um estilo por não seguir a mudança incessante que lhe ditava a tecnologia. Entre a participação modesta na teoria da arquitetura anterior a Schinkel e a ação de uma entidade cultural, tão importante quanto o Deutscher Werkbund (1907), pela criação do design e da arquitetura modernos, a Alemanha tornou-se ativa na teoria arquitetônica. Se houve repercussão tanto do materialismo estético, como de várias doutrinas da estética filosófica, nem por isso deixou de haver teorias próprias do estilo arquitetônico, como as de Bötticher e Semper, que introduziram o espaço arquitetônico como problema a ser tratado pela escola formalista em história da arte. Neste livro, Marcos Faccioli Gabriel procura tornar os debates das vanguardas, dentro e ao redor do Deutscher Werkbund, mais transparentes e mais ricos em matizes, como o discurso tardio do crítico da arquitetura Sigfried Giedion por uma Nova Monumentalidade.', '["Karl Friedrich Schinkel","Deutscher Werkbund","architectural style","modernity in architecture","Reyner Banham","architectural theory","Semper","formalism","avant-garde architecture","Sigfried Giedion","German architecture"]', '10.7476/9786557145524', '9786557145524', 'https://books.scielo.org/id/h5hnw', 'https://books.scielo.org/id/h5hnw/pdf/gabriel-9786557145524.pdf', NULL, 'https://books.scielo.org/id/h5hnw/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h5jt2', 'h5jt2', 'Identidades brasileiras: composições e recomposições', NULL, '["Cristina Carneiro Rodrigues","Tania Regina de Luca","Valéria Guimarães"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A coleção Desafios Contemporâneos proposta pela Pró-Reitoria de Pesquisa (PROPe) da Unesp tem por objetivo disponibilizar, em linguagem acessível aos não familiarizados com o jargão dominante nos estudos especializados e sem prejuízo do rigor científico, ensaios a respeito de temas de amplo interesse da sociedade brasileira.Assim, a universidade cumpre uma de suas tarefas essenciais: a difusão dos resultados do conhecimento que produz.Neste volume, dedicado às questões sociais, os autores enfrentaram a difícil tarefa de lançar um olhar panorâmico sobre a complexa questão da identidade brasileira, sem perder de vista a maneira como a temática se expressa nos dilemas enfrentados nos dias que correm.Estruturados em amplos recortes, os textos tomam como ponto de partida o momento atual para delinear um balanço retrospectivo da produção sobre o assunto, pontuando o estado atual das pesquisas e para dialogar com as abordagens mais clássicas, com o intuito de apontar possíveis desdobramentos para a pesquisa na área das Ciências Humanas. Introdução Tania Regina de Luca 1Unesp/CNPq A questão da identidade nacional continua a desafiar os estudiosos das Ciências Humanas; basta observar os conflitos em curso nesta segunda década do século XXI para perceber o quanto projetos identitários de cunho geográfico, étnico, linguístico, religioso e cultural continuam a se mesclar num jogo complexo a despeito da globalização e de seus efeitos homogeneizadores.Esse cenário convida a revisitar o debate sobre a identidade brasileira, tema que tem ocupado a nossa intelectualidade desde a Independência.Não nos faltam estudos específicos -dedicados a perscrutar instituições, personagens, períodos e eventos -com o intuito de dar conta da nação brasileira, seus impasses e desafios, avanços e recuos que assumiram formas muito variadas no decorrer do tempo.Igualmente ricos são os balanços e as análises que pas-6 CRISTINA C. RODRIGUES -TANIA R. DE LUCA -VALÉRIA GUIMARÃES (ORGS.)tensão nacional/estrangeiro que tem atravessado, com matizes e graus diversos, a cultura brasileira.Num mundo interconectado e marcado pela simultaneidade das informações e grandes corporações do entretenimento, que não conhecem fronteiras, a noção de trocas culturais -entendida como uma via de mão dupla -apresenta-se como uma possibilidade instigante.A questão da identidade religiosa, por sua vez, constitui-se num dos temas mais candentes do cenário brasileiro atual, com repercussões no jogo político-partidário, na economia, na cultura, nos meios de comunicação de massa e na vida cotidiana das pessoas.Os dados censitários são eloquentes quando se trata de evidenciar a pluralização das formas de identificação da população.No ensaio consagrado ao tema, confrontam-se três projetos de identificação e analisam-se suas narrativas fundacionais: o católico, o umbandista e o pentecostal.O capítulo final, a exemplo do que ocorreu no de abertura, objetiva fornecer um balanço, e a opção aqui foi a de examinar um elenco representativo de coletâneas publicadas no início do novo milênio, com o intuito de analisar as formas de utilização e apropriação do conceito de identidade nacional pelos pesquisadores brasileiros que se dedicam ao tema.Este livro foi concebido para ser disponibilizado em ambiente virtual, o que coloca novos desafios para o processo de escrita e para o trabalho editorial.Não parece despropositado afirmar que ainda temos um longo caminho até que se produza material que explore, de forma efetiva, todas as possibilidades desse novo suporte.Aqui não se foi além de solicitar aos autores que, sempre que possível e pertinente, indicassem material disponível na rede mundial, ainda figurando na sua forma tradicional de nota de rodapé, isso porque não foi possível dar acesso direto aos documentos, trechos de música ou excertos de imagens em movimento.Escrever, de fato, no e para esse novo meio é um desafio que continuamos a enfrentar.', '["Brazilian national identity","national identity","identity construction","ethnic identity","linguistic identity","religious identity","cultural identity","globalization","identity politics"]', '10.7476/9788579835155', '9788579835155', 'https://books.scielo.org/id/h5jt2', 'https://books.scielo.org/id/h5jt2/pdf/rodrigues-9788579835155.pdf', NULL, 'https://books.scielo.org/id/h5jt2/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h5n2k', 'h5n2k', 'Pele e Aids: manifestações dermatológicas na síndrome da imunodeficiência adquirida', NULL, '["Carlos Alberto Basílio de Oliveira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Informações sobre os principais problemas dermatológicos, infecciosos ou não, que acometem pacientes com Aids foram reunidas neste CD-ROM, cujo objetivo é auxiliar os profissionais de saúde no atendimento e tratamento desses pacientes. A obra traz 44 pranchas e respectivos verbetes descritivos sobre as manifestações cutâneas na síndrome da imunodeficiência humana. As imagens usadas pertencem ao acervo do Laboratório de Anatomia Patológica do Hospital Universitário Gafrée e Guinle da Universidade Federal do Estado do Rio de Janeiro (UniRio). A obra é fruto do trabalho e da experiência de uma equipe de 11 profissionais, entre dermatologias e especialistas em anatomia patológica e Aids, a maioria da UniRio, mas também da Pontifícia Universidade Católica do Rio de Janeiro (PUC-Rio) e da Universidade Federal Fluminense (UFF).', '["AIDS","HIV infection","cutaneous manifestations","skin lesions","immunodeficiency","dermatopathology"]', '10.7476/9788575416006', '9788575416006', 'https://books.scielo.org/id/h5n2k', 'https://books.scielo.org/id/h5n2k/pdf/oliveira-9788575416006.pdf', NULL, 'https://books.scielo.org/id/h5n2k/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h6k46', 'h6k46', 'Competências digitais de professores e estudantes: contribuições para a formação emancipatória', 'contribuições para a formação emancipatória', '["Eniel do Espírito Santo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Competências digitais de professores e estudantes: contribuições para a formação emancipatória apresenta um panorama sobre o desenvolvimento das competências digitais na educação com pesquisas luso-brasileiras, propondo estratégias para uma formação crítica e reflexiva. Com foco nas competências emancipatórias, a obra contribui para a prática pedagógica ao preparar as novas gerações para os desafios do século XXI. Destinada a pesquisadores, educadores e gestores, apresenta uma abordagem crítica sobre as implicações sociais, políticas e econômicas da cultura digital na educação, oferecendo um olhar plural sobre as mudanças necessárias para uma educação mais justa e conectada com as necessidades contemporâneas.', '["digital skills","teachers","students","emancipatory education","critical pedagogy","digital culture in education","digital divide","educational equity","teaching practice"]', '10.7476/9786556309415', '9786556308449', 'https://books.scielo.org/id/h6k46', 'https://books.scielo.org/id/h6k46/pdf/santo-9786556309415.pdf', NULL, 'https://books.scielo.org/id/h6k46/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h6kh6', 'h6kh6', 'Mudanças na classe política brasileira', NULL, '["Leôncio Martins Rodrigues"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro analisa os dados do levantamento que realizamos durante os anos 2003-2004 sobre as mudanças na composição socioprofissional na Câmara dos Deputados decorrentes das eleições de 1998 e de 2002. Como resultado dessas disputas, houve importante alteração no quadro político brasileiro. [...]', '["Brazilian Chamber of Deputies","political class","1998 elections","2002 elections","political transition"]', '10.7476/9788579820113', '9788579820113', 'https://books.scielo.org/id/h6kh6', 'https://books.scielo.org/id/h6kh6/pdf/rodrigues-9788579820113.pdf', NULL, 'https://books.scielo.org/id/h6kh6/cover/cover_thumbnail.jpeg', NULL, 24, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h6pj6', 'h6pj6', 'Vozes da docência nas ruralidades: viagem pelas narrativas documentadas de professoras/es no Ensino Médio', 'viagem pelas narrativas documentadas de professoras/es no Ensino Médio', '["Adelson Dias de Oliveira"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Em Vozes da docência nas ruralidades: viagem pelas narrativas documentadas de professoras/es no Ensino Médio, convido-os a embarcar em uma jornada profundamente pessoal e coletivamente significativa, guiada pelas memórias e experiências do autor, que moldam a estrutura desta obra. Através da lente da Documentação Narrativa de Experiências Pedagógicas, o livro desdobra-se como um testemunho de resistência, uma crítica às políticas educacionais vigentes e um manifesto pela transformação pedagógica em contextos de ruralidade.', '["rural education","secondary school teachers","women teachers","teacher narratives","pedagogical resistance","education policy critique","pedagogical transformation","teacher testimonies"]', '10.7476/9788585813604', '9788585813475', 'https://books.scielo.org/id/h6pj6', 'https://books.scielo.org/id/h6pj6/pdf/oliveira-9788585813604.pdf', NULL, 'https://books.scielo.org/id/h6pj6/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h6tgw', 'h6tgw', 'Família contemporânea e saúde: significados, práticas e políticas públicas', NULL, '["Leny Alves Bomfim Trad"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Coletânea resultante de trabalho interdisciplinar em pesquisas de amplo alcance, no Brasil, nos estudos sobre família. Desde a definição do objeto – família –, este livro tem como ponto de partida as rápidas e continuadas mudanças vividas por essa instituição, que se refletem na sua composição interna. Nas relações de gênero e intergeracionais, e na tessitura de um sentimento de parentesco e pertencimento, a obra sinaliza que a família é, na atualidade, alvo de programas e políticas públicas aplicadas ao setor da saúde no Brasil, problematizando a pertinência de suas respectivas diretrizes diante das necessidades sociais e possibilidades culturais da família brasileira.', '["contemporary family","family health","family structure","gender relations","intergenerational relations","public health policy","Family Health Strategy","Brazilian families"]', '10.7476/9788575413227', '9788575411971', 'https://books.scielo.org/id/h6tgw', NULL, NULL, 'https://books.scielo.org/id/h6tgw/cover/cover_thumbnail.jpeg', 380, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h77ny', 'h77ny', 'O fascismo em dez lições', NULL, '["Sinésio Ferraz Bueno"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os textos que compõem a presente obra oferecem uma percepção aguda do dilema ético-político contemporâneo, especialmente no contexto nacional, ao colocar o fascismo em questão, e vão além, ao propor a radical questão: como reagir a ele, sem ao mesmo tempo, nos tornarmos fascistas? Trata-se de um livro com dez valiosas lições que mobilizam os principais conceitos da Escola de Frankfurt, especialmente os cunhados por Theodor Adorno e Max Horkheimer, dialogando também com Freud e autores da tradição filosófica, com destaque para os contemporâneos. É uma obra fortemente recomendada na formação de professoras e professores, de todas as modalidades de ensino, na medida em que todas e todos sentimos os efeitos do fascismo na trama social. Nesta obra, o foco do enfrentamento não está no Outro, não está na ação fascista, mas no cuidado e no enfrentamento do fascismo que, em maior ou menor grau, conforma nosso olhar. Reconhecer o fascismo no Outro é menos trabalhoso e menos complicado do que reconhecer o fascismo que habita em cada um de nós.', '["fascism","Frankfurt School","Theodor W. Adorno","Max Horkheimer","Sigmund Freud","ethics and politics","anti-fascism","teacher professional development"]', '10.7476/9786557143049', '9786557143049', 'https://books.scielo.org/id/h77ny', 'https://books.scielo.org/id/h77ny/pdf/bueno-9786557143049.pdf', NULL, 'https://books.scielo.org/id/h77ny/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h7yz9', 'h7yz9', 'Étienne Decroux e a artesania de ator: caminhadas para a soberania', NULL, '["Bya Braga"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Pela primeira vez um livro apresenta, em língua portuguesa, um conjunto de reflexões em torno da obra singular do artista francês Etienne Decroux (1898-1991), aliado, de modo instigante, ao pensamento filolosófico de Georges Bataille em sua noção de arte soberana e à pesquisa prática cênica da autora. Decroux, ator-artesão, conviveu e atuou ao lado de importantes nomes do teatro e cinema, como Copeau, Dullin, Jouvet, Baty, Artaud, Barrault, Herrand e Carné. Seu grande valor artístico está na criação da Mímica Corporal Dramática mais do que uma técnica, uma arte inovadora que reflete a visão de Decroux sobre o teatro como arte de ator. Trata-se de um livro bem documentado, rigoroso e original em sua essência, escrito com competência e humor, sempre pautado pelo teatro contemporâneo, em contínua construção.', '["Étienne Decroux","Georges Bataille","actor training","contemporary theatre","theatre and cinema","Antonin Artaud","Jean-Louis Barrault","Jacques Copeau"]', '10.7476/9786558580997', '9788570419712', 'https://books.scielo.org/id/h7yz9', NULL, NULL, 'https://books.scielo.org/id/h7yz9/cover/cover_thumbnail.jpeg', 516, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h8pyf', 'h8pyf', 'Educação infantil: discurso, legislação e práticas institucionais', NULL, '["Lucimary Bernabé Pedrosa de Andrade"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O presente estudo inscreve-se no campo das políticas públicas para a infância destacando a questão da educação infantil como um dos direitos da criança. Atualmente, a criança é reconhecida como sujeito pleno de direitos, ganhando a infância maior visibilidade na sociedade, respaldada por dispositivos legais de âmbito internacional. Em contrapartida, os discursos teóricos e a realidade de milhares de crianças em todo o mundo têm revelado o estado paradoxal da condição da criança e da efetivação dos seus direitos. Portanto, o objetivo deste estudo foi o de analisar as concepções de criança, seus direitos e educação infantil apresentadas pelas educadoras das creches de Franca, e de que forma essas categorias são manifestadas nas práticas institucionais. A construção da pesquisa, referenciada na abordagem qualitativa, teve como aporte teórico-metodológico a teoria das representações sociais e o emprego de questionários e entrevistas semiestruturadas como instrumentos metodológicos para a coleta dos dados empíricos, posteriormente analisados pela técnica da análise de conteúdo. Com base nas análises desenvolvidas, constatou-se nos discursos e nas ações das profissionais representações da criança como um sujeito marcado pela condição de "vir a ser", dependente do adulto, frágil e inocente, associadas a um modelo de educação infantil escolarizante e preparatório de futuras aprendizagens. Desta forma, as representações acerca das categorias criança, direitos e educação infantil não favorecem, efetivamente, para que as crianças exerçam a condição de sujeitos de direitos e protagonistas nos espaços institucionais, e para que as creches sejam legitimadas enquanto espaços de exercício da cidadania da infância.', '["early childhood education","children''s rights","conceptions of childhood","social representations","childcare teachers","institutional practices","children''s citizenship","children''s rights legislation"]', '10.7476/9788579830853', '9788579830853', 'https://books.scielo.org/id/h8pyf', 'https://books.scielo.org/id/h8pyf/pdf/andrade-9788579830853.pdf', NULL, 'https://books.scielo.org/id/h8pyf/cover/cover_thumbnail.jpeg', NULL, 24, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h8sn8', 'h8sn8', 'Design coletivo: grupos, movimentos e escolas do moderno ao contemporâneo', NULL, '["Mônica Cristina De Moura"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Design coletivo apresenta, ao longo da história do design, entre 1800 e 1990, as escolas, os movimentos e os grupos com propostas interdisciplinares, atuação conjunta e colaborativa entre as áreas do artesanato, da arte, do design, da arquitetura, da engenharia e de outros segmentos, como moda, estamparia, joalheria, espaços interiores e urbanos, sem separações, preconceitos ou corporativismos. Conhecer a atuação interdisciplinar, a somatória do conhecimento de diversas áreas na concepção, na criação e na produção que constituem um novo objeto, comum a todos os envolvidos, nos leva a perceber a essência do design e as bases do design moderno e contemporâneo. A pesquisa histórica reunida neste livro é parte dos resultados do doutorado da autora, à qual foi somada a vivência de mais de trinta anos nas salas de aula nos cursos de graduação e pós-graduação em design, fato que a levou a perceber a necessidade de comprovar que a ação coletiva, colaborativa e interdisciplinar existe no design há muito tempo, por várias gerações e entre diversas culturas.', '["collective design","design movements","design schools","interdisciplinary collaboration","co-design","modern design","contemporary design","design history","design education","craft and design","architecture and design","fashion design"]', '10.7476/9786557142967', '9786557142967', 'https://books.scielo.org/id/h8sn8', 'https://books.scielo.org/id/h8sn8/pdf/moura-9786557142967.pdf', NULL, 'https://books.scielo.org/id/h8sn8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h95n9', 'h95n9', 'Pequeno Glossário Ilustrado de Metáforas para o corpo, ensino e aprendizagem em dança', NULL, '["Sueli Ramos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Para Sueli Ramos, os movimentos do corpo estão atrelados ao nosso universo afetivo e cultural, e constroem pontes entre as nossas ações motoras e o nosso mundo imaginário. Fruto de sua pesquisa de mestrado, este Pequeno glossário ilustrado de metáforas foi pensado para ser um instrumento de trabalho que possa, por meio de metáforas verbais e gestuais, contribuir com professoras(es) no sentido de facilitar e promover uma reverberação mais duradoura do movimento/exercício.', '["dance education","dance learning","metaphor","body movement","teacher professional development"]', '10.7476/9786556309910', '9786556307435', 'https://books.scielo.org/id/h95n9', 'https://books.scielo.org/id/h95n9/pdf/ramos-9786556309910.pdf', NULL, 'https://books.scielo.org/id/h95n9/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-h9ypr', 'h9ypr', 'Identidades judaicas no Brasil contemporâneo', NULL, '["Bila Sorj"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro procura contribuir para o conhecimento de um setor da sociedade que não se enquadra nos temas tradicionais, na medida em que trata de um grupo cuja identidade cultural foge dos padrões e preocupações típicas do que foi a agenda dominante das Ciências Sociais no Brasil até bem pouco tempo. Apesar de os judeus terem um papel importante na construção de movimentos políticos e ideológicos, na vida econômica e científica do Brasil, são pouquíssimos os trabalhos que procuraram compreender os processos socioculturais de formação e transformação da comunidade judaica no Brasil.', '["Jewish identity","Jewish community","contemporary Brazil","cultural identity","sociocultural formation","Jewish history","Jewish diaspora","political movements"]', '10.7476/9788599662601', '9788599662601', 'https://books.scielo.org/id/h9ypr', 'https://books.scielo.org/id/h9ypr/pdf/sorj-9788599662601.pdf', NULL, 'https://books.scielo.org/id/h9ypr/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hbhbr', 'hbhbr', 'SUS: o debate em torno da eficiência', NULL, '["Alexandre Marinho","Carlos Octávio Ocké‐Reis"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-08-10', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O volume debate o uso do termo "eficiência" para avaliar a gestão do Sistema Único de Saúde. A obra busca examinar a eficiência no SUS a partir do fato de que tal argumento é sistematicamente utilizado para defender a mercantilização do próprio sistema. Segundo os autores, que se dedicam aos estudos da disciplina da economia da saúde desde a década de 1990, isso acaba encobrindo um constante ataque à ampliação do acesso à saúde promovido pela reforma sanitária brasileira. Os economistas Alexandre Marinho e Carlos Octávio Ocké-Reis argumentam que a palavra eficiência acaba sendo, dessa forma, vulgarizada e servindo para enfraquecer as políticas públicas de saúde. Segundo eles, não há dúvidas sobre as possibilidades de aperfeiçoamentos na gestão do SUS, especialmente por meio da ampliação do financiamento de seus recursos humanos. No entanto, não basta ser eficiente se os resultados não são atingidos e, principalmente, se as necessidades de saúde da população não são atendidas.', '["Unified Health System (SUS)","efficiency","health services administration","commodification of health care","Brazilian health reform","health care access","health economics","public health policy","health care financing"]', '10.7476/9786557081662', '9786557081334', 'https://books.scielo.org/id/hbhbr', NULL, NULL, 'https://books.scielo.org/id/hbhbr/cover/cover_thumbnail.jpeg', 132, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hbx3m', 'hbx3m', 'Brasil, 1989: um estudo sócio-econômico da indigência e da pobreza urbana', NULL, '["Juárez Rubens Brandão Lopes"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste trabalho eu procuro traçar um quadro da pobreza urbana no Brasil contemporâneo, com a precisão permitida pelos dados de pesquisas de amostragem de domicílios. Para isso eu utilizo da abordagem das linhas de pobreza. [trecho retirado da introdução do livro]', '["urban poverty","poverty line","socioeconomic conditions","household surveys","Brazil"]', '10.7476/9788599662755', '9788599662755', 'https://books.scielo.org/id/hbx3m', 'https://books.scielo.org/id/hbx3m/pdf/lopes-9788599662755.pdf', NULL, 'https://books.scielo.org/id/hbx3m/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hc4m7', 'hc4m7', 'Crises da democracia e esfera pública: debates contemporâneos', NULL, '["Fabrino Mendonça, Ricardo","Sarmento, Rayza"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Em tempos de crise da democracia, o conceito de esfera pública mostra-se novamente útil para gerar compreensão sobre os desafios que se apresentam. Seja pela fragmentação saturada dos fluxos discursivos em plataformas digitais, pela explosão de fenômenos vinculados à desinformação, pela centralidade adquirida por entidades não humanas na estruturação da opinião pública hodierna, ou pelas lutas sociais e a tematização de problemas públicos como têm se organizado, eis que a noção é retomada, 60 anos após a publicação de Mudança Estrutural da Esfera Pública, para dizer das possibilidades de sobrevivência da democracia. Este livro reúne um conjunto de capítulos que se propõem a mobilizar o conceito de esfera pública e de lentes deliberacionistas, para ler não apenas o quadro mais amplo de erosão democrática, mas também as reconfigurações de práticas comunicacionais e de embates públicos que marcam o contemporâneo.', '["crisis of democracy","public sphere","deliberative democracy","disinformation","digital platforms","public opinion","non-human entities","social movements","public problems","democratic backsliding"]', '10.7476/9786588592335', '9786588592076', 'https://books.scielo.org/id/hc4m7', NULL, NULL, 'https://books.scielo.org/id/hc4m7/cover/cover_thumbnail.jpeg', 358, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hc88g', 'hc88g', 'Em busca da comunidade: ciências sociais, desenvolvimento rural e diplomacia cultural nas relações Brasil-EUA (1930-1950)', NULL, '["Thiago da Costa Lopes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Integrante da coleção História e Saúde, o livro investiga o papel das ciências sociais e das políticas públicas no Brasil a partir dos estudos rurais e do lugar do rural na sociedade brasileira contemporânea. Doutor pelo Programa de Pós-Graduação em História das Ciências e da Saúde da Casa de Oswaldo Cruz/Fiocruz e pesquisador premiado com o Prêmio Capes de Tese 2019 - Comissão Fulbright, o autor analisa a trajetória das relações acadêmicas e diplomáticas entre Brasil e Estados Unidos, no período 1930-1950. Thiago Lopes concentrou seus estudos em dois importantes sociólogos da época: o norte-americano T. Lynn Smith e o brasileiro José Arthur Rios. A obra é dividida em quatro capítulos, e inclui também notas e referências, além de caderno de fotografias dos intelectuais em diversas ocasiões, como solenidades públicas, entrevistas concedidas à imprensa, cursos, seminários e reuniões.', '["social sciences","rural development","cultural diplomacy","Brazil–United States relations","academic exchange","rural sociology","public policy","history of social sciences","1930s-1950s"]', '10.7476/9786557080641', '9786557080085', 'https://books.scielo.org/id/hc88g', NULL, NULL, 'https://books.scielo.org/id/hc88g/cover/cover_thumbnail.jpeg', 281, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hc8qb', 'hc8qb', 'O encontro da antropologia com a favela: Anthony e Elizabeth Leeds no Jacarezinho', NULL, '["Rachel de Almeida Viana"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-08-09', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro trata dos encontros entre o antropólogo Anthony Leeds, os jovens pesquisadores do Peace Corps no Brasil - entre os quais, a cientista política Elizabeth Leeds - os estudantes do Programa de Antropologia Social do Museu Nacional e os moradores das favelas do Rio de Janeiro, notadamente o Jacarezinho, na década de 1960. Rachel Viana, em tese distinguida pelo Prêmio Oswaldo Cruz de Teses, ora transformada em livro, escrutina as notas de campo, cartas e outros documentos que integram o acervo - hoje aberto à consulta-, doado por Elizabeth Leeds à Casa de Oswaldo Cruz/Fiocruz, para percorrer os passos da pesquisa que resultou na construção dos estudos urbanos no Rio de Janeiro.', '["Jacarezinho","favelas","urban anthropology","Peace Corps","social anthropology","Rio de Janeiro","Casa de Oswaldo Cruz","history of anthropology","field notes","1960s"]', '10.7476/9786557082133', '9786557081471', 'https://books.scielo.org/id/hc8qb', NULL, NULL, 'https://books.scielo.org/id/hc8qb/cover/cover_thumbnail.jpeg', 384, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hcf73', 'hcf73', 'Recortes da Memória: lembranças, compromissos e explicações sobre a EPM/UNIFESP na perspectiva da história oral', NULL, '["Dante Marcello Claramonte Gallian","Fabíola Holanda Barbosa","José Carlos Sebe Bom Meihy","Márcia Regina Barros da Silva","Suzana Lopes Salgado Ribeiro","Valdir Reginato"]', 'Editora Fap-Unifesp', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] Cinco capítulos, cinco autores, cinco temáticas e modos de abordagem diferentes. Recortes da Memória continua o trabalho iniciado no livro 75 x 75: epm/Unifesp, uma História, 75 Vidas, e mostra as múltiplas possibilidades de reflexão, análise e estudo que um projeto de história oral permite. Esta coletânea apresenta reflexões sobre diversos aspectos que o discurso da memória individual e coletiva configura: a questão geracional, os conflitos e acordos de classe e origem étnica; a construção de uma identidade científica; o problema da educação e da vocação médicas e a importância do espaço e da efetividade na reinvenção da memória. Fruto do engajamento de uma equipe motivada e envolvida com seu objeto de estudo – as histórias de vida de 75 pessoas que participaram dos 75 anos da epm/Unifesp –, que não se satisfez em apenas “coletar” a memória, mas procurou também dialogar com ela e construir interpretações.', '["oral history","collective memory","individual memory","life history (social science method)","science identity","medical education","medical vocation","intergenerational conflict","ethnicity","class struggle","memory and space"]', '10.7476/9788561673642', '9788561673642', 'https://books.scielo.org/id/hcf73', NULL, NULL, 'https://books.scielo.org/id/hcf73/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hcmrr', 'hcmrr', 'Mídias sociais: saberes e representações', NULL, '["José Carlos Ribeiro","Thiago Pereira Falcão","Tarcizio Roberto da Silva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'silva 8qual Walter Lippman acreditava, fica evidente que o papel dos pesquisadores em ciências sociais e humanas é o de adicionar critério, ler o fenômeno e suas ramificações de forma analítica e livre de juízo de valor, na tentativa de entender o processo, mais do que simplesmente enaltecer ou condenar qualquer parcela deste.O SIMSOCIAL -Simpósio em Tecnologias Digitais e Sociabilidade -, que aconteceu na Universidade Federal da Bahia, nos dias 13', '["social media","knowledge production","representation","digital technologies","sociability","Walter Lippmann","value-free research"]', '10.7476/9788523217341', '9788523217341', 'https://books.scielo.org/id/hcmrr', 'https://books.scielo.org/id/hcmrr/pdf/ribeiro-9788523217341.pdf', NULL, 'https://books.scielo.org/id/hcmrr/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hcnhr', 'hcnhr', 'Aplicaciones e innovación de la ingeniería en ciencia y tecnología', NULL, '["Juan Inga"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2019, '2019-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'El mundo ha avanzado con la llegada de la ciencia y tecnología desde los diversos campos que la conforman con una visión de innovación involucrando a la sociedad y así satisfacer las necesidades que se han convertido en una problemática para el campo científico. El camino para llegar a un concepto de ciudades inteligentes, por ejemplo, puede conjugar varias aistas que dan cuenta de un aporte de diversas competencias y destrezas por parte de la comunidad científica. De esta manera, podemos encontrar aportes de redes eléctricas inteligentes, servicios de comunicación masiva, aprovechamiento de los recursos hídricos, análisis de ondas sísmicas, manejo de datos en la nube o la interpretación de imagen para aplicaciones médicas, cumpliendo así una vasta demanda de oportunidades para la generación de nuevo conocimiento que aplica la ciencia y tecnología en favor de la sociedad.', '["engineering applications","innovation","smart cities","smart grid","communication services","water resources","seismic waveform analysis","cloud data management","medical image interpretation","scientific knowledge production","societal needs"]', '10.7476/9789978104910', '9789978104910', 'https://books.scielo.org/id/hcnhr', 'https://books.scielo.org/id/hcnhr/pdf/inga-9789978104910.pdf', NULL, 'https://books.scielo.org/id/hcnhr/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hcqvx', 'hcqvx', 'Lourenço Filho e literatura infantil e juvenil', NULL, '["Estela Natalina Mantovani Bertoletti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, a autora tece considerações sobre a obra de Manoel Bergström Lourenço Filho (1897-1970), que, além de ter escrito vários livros de literatura infantil e juvenil entre 1942 e 1968, também foi um importante educador e teórico da Educação. A intenção da pesquisadora é de compreender a relação entre a produção literária de Lourenço Filho – hoje pouco conhecida e explorada no país – e o lugar por ele ocupado na história da literatura infantil e juvenil brasileira. A autora parte do pressuposto de que a obra de Lourenço Filho teve enorme importância para o desenvolvimento deste gênero de literatura em terras brasileiras, com significativa influência na produção tanto dos seus contemporâneos como de seus pósteros, tendo ele fundado mesmo uma tradição. O escritor teria desenvolvido com padrões bastante elevados um modelo de literatura vinculado a finalidades educacionais – presente no Brasil desde o final do século XIX, mas em geral pouco eficaz – de modo a proporcionar à criança uma formação pedagógica e cultural consistente, sem deixar de ser agradável. O livro também monta um amplo painel histórico sobre a produção de literatura infantil e juvenil no Brasil, que teve em Monteiro Lobato um de seus precursores e vive um autêntico “boom” desde o começo da década de 1970.', '["children''s literature","young adult literature","Brazilian children''s literature","history of children''s literature","literary tradition","Monteiro Lobato","literary boom"]', '10.7476/9786557145005', '9786557145005', 'https://books.scielo.org/id/hcqvx', 'https://books.scielo.org/id/hcqvx/pdf/bertoletti-9786557145005.pdf', NULL, 'https://books.scielo.org/id/hcqvx/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hcxhz', 'hcxhz', 'Brasil Saúde Amanhã: complexo econômico-industrial da saúde', NULL, '["Gadelha, Carlos Augusto Grabois","Gadelha, Paulo","Noronha, José Carvalho de","Pereira, Telma Ruth"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Este volume é dedicado à reflexão sobre o complexo econômico-industrial da saúde (CEIS), a partir da proposição de que a articulação entre avanço tecnológico, desenvolvimento produtivo e promoção da saúde é fundamental para garantir efetividade na formulação de políticas públicas para o setor. Organizadores e autores do livro defendem a necessidade de conjugar conceitos de diversas áreas da ciência para o fortalecimento do CEIS, diante da “profunda desarticulação das competências tecnológicas e produtivas e da perda de oportunidades para avançar na estruturação de um sistema público de saúde”, efeitos da condução neoliberal da economia que prevaleceu na década de 1990. Os cinco capítulos são apresentados como parte “de uma visão integrada, sistêmica e de economia política”, analisando aspectos relacionados à produção e inovação no âmbito do CEIS, e buscando consolidar bases políticas e acadêmicas para a construção “de um projeto nacional assentado no avanço social e da estrutura produtiva”. O livro integra um conjunto de publicações resultantes da iniciativa Brasil Saúde Amanhã, rede multidisciplinar de pesquisa, coordenada pela Fiocruz, com apoio do Ministério da Saúde.', '["health economic-industrial complex","health technology","healthcare innovation","health promotion","public health policy","health system effectiveness","neoliberalism","health production","Brazil"]', '10.7476/9786557080924', '9786557080924', 'https://books.scielo.org/id/hcxhz', 'https://books.scielo.org/id/hcxhz/pdf/gadelha-9786557080924.pdf', NULL, 'https://books.scielo.org/id/hcxhz/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hd5d8', 'hd5d8', 'O ensino da filosofia no limiar da contemporaneidade : o que faz o filósofo quando seu ofício é ser professor de filosofia?', NULL, '["Rodrigo Pelloso Gelamo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A presente tese analisa o tema do ensino da filosofia no ensino superior, tendo em vista discutir o problema do ofício do filósofo quando sua tarefa é ensinar a filosofia. Nesse sentido, o tema analisado e o problema discutido na tese têm como ponto de partida as questões suscitadas no exercício da docência da disciplina Filosofia em cursos de graduação de outras áreas, objetivando contribuir tanto para buscar outros sentidos a essa prática quanto para os estudos sobre o ensino da filosofia no Brasil. Por meio de uma revisão bibliográfica sobre o ensino da filosofia no Brasil, e da leitura de autores clássicos (Kant e Hegel), procuramos encontrar ressonância de nosso problema na literatura sobre o assunto. Essa revisão além de não responder ao problema, ampliou-o, pois, pudemos notar que os questionamentos sobre o ensino da filosofia se agrupavam em três grupos: sobre a importância, sobre o conteúdo e sobre o método para se ensinar a filosofia. Com o objetivo de escapar dessas formas de problematização, recorremos a Gilles Deleuze e Michel Foucault para propor uma outra maneira de encaminhar uma problematização de modo que o problema do ensino da filosofia não recaísse nesse mesmo registro. Com Deleuze pudemos compreender que existem mecanismos, chamados por ele de imagens dogmáticas do pensamento, que aprisionam os problemas a respostas preestabelecidas. A partir disso, fizemos a relação dessa noção com os problemas que eram colocados pelo ensino da filosofia, os quais funcionavam como essas imagens dogmáticas do pensamento. Com Foucault procuramos um modo de problematizar no qual pudéssemos estar, simultaneamente, como elemento e ator desse problema. Com isso, circunscrevemos um problema presente no ensino da filosofia que se plasma no empobrecimento da experiência, causado pela excessiva preocupação com a transmissão de conhecimentos através da...', '["philosophy education","higher education","philosophy as a discipline","role of the philosopher","Gilles Deleuze","Michel Foucault","Immanuel Kant","Hegel","experience","knowledge transmission"]', '10.7476/9788598605951', '9788598605951', 'https://books.scielo.org/id/hd5d8', 'https://books.scielo.org/id/hd5d8/pdf/gelamo-9788598605951.pdf', NULL, 'https://books.scielo.org/id/hd5d8/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hdf5s', 'hdf5s', 'A saúde coletiva no curso de medicina, campus Chapecó: o ensino com pesquisa e extensão para a formação médica humanista e cidadã', NULL, '["Cruvinel, Agnes de Fátima Pereira","Fonsêca, Graciela Soares","Rossetto, Maíra"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Esta obra – com 17 capítulos, os quais revelam o potencial da inclusão da extensão e da pesquisa nos currículos de graduação no sentido de transformar os cursos e aproximá-los da sociedade – organiza-se em duas partes. A primeira parte apresenta dez experiências extensionistas desenvolvidas nos anos iniciais de implantação do Curso de Medicina no Campus Chapecó, no âmbito dos CCR de Saúde Coletiva, e traz uma diversidade de temas, cenários, público-alvo e estudantes envolvidos. Na segunda parte, são apresentadas sete experiências e resultados da participação dos estudantes em projetos de pesquisa. Os temas também são diversos, e as propostas tiveram o objetivo maior de gerar resultados capazes de responder às necessidades de saúde da população e/ou atender às demandas de formação dos estudantes. “A Saúde Coletiva no Curso de Medicina, Campus Chapecó: o ensino com pesquisa e extensão para a formação médica humanista e cidadã” constitui-se de temas eleitos em função das demandas sociais e da “expertise” dos docentes e conta com a participação de estudantes, os quais protagonizaram a prática da Saúde Coletiva, permitindo experiências marcantes que contribuem para alcançar a aprendizagem significativa.', '["public health education","medical education","undergraduate research projects","university extension","research-based teaching","citizenship education","meaningful learning","community health centers","medical students"]', '10.7476/9786550190224', '9786550190224', 'https://books.scielo.org/id/hdf5s', 'https://books.scielo.org/id/hdf5s/pdf/cruvinel-9786550190224.pdf', NULL, 'https://books.scielo.org/id/hdf5s/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hdjgq', 'hdjgq', 'Diálogos com Boris Porena: reflexões para a educação musical', 'reflexões para a educação musical', '["Samuel Campos de Pontes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra procura compreender, analisar e interpretar o pensamento do compositor italiano Boris Porena, em particular a problemática da aprendizagem de música na escola de Educação Básica. Depois de apresentar um breve perfil do compositor (com foco em aspectos biográfi cos e na obra ensaística), Samuel Campos de Pontes parte para a análise do que Boris Porena chama de Hipótese Metacultural e dos aspectos importantes para o desenvolvimento desse conceito, com foco nos processos de aprendizagem e nas particularidades da música dentro desse universo. O autor trata, em seguida, de aspectos que se referem a possíveis conexões entre o pensamento de Porena e a educação musical brasileira dos dias atuais. Ao fim, esse diálogo não estaria completo sem a leitura da série de cartas Vita die Martis, transcrita na íntegra no último apêndice desta publicação. Este livro é, portanto, um convite para que leitores interessados pela intersecção entre música e educação entrem no diálogo com esse importante compositor e pensador da cultura e da educação.', '["music education","basic education","Italian composers","Brazilian music education","philosophy of music","music and culture"]', '10.7476/9786557145555', '9786557145555', 'https://books.scielo.org/id/hdjgq', 'https://books.scielo.org/id/hdjgq/pdf/pontes-9786557145555.pdf', NULL, 'https://books.scielo.org/id/hdjgq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hdjh2', 'hdjh2', 'População LGBT+: demandas e necessidades para a produção do cuidado', NULL, '["Santos, Adriano Maia dos","Carmo, Edinaldo Medeiros","Magno, Laio","Prado, Nilia Maria de Brito Lima"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'A coletânea reúne textos que colocam em diálogo elementos conceituais e pesquisa empírica, articulando diferentes perspectivas teórico-metodológicas para refletir e analisar os desafios na produção do cuidado integral para a população LGBT+. As narrativas apresentam enfrentamentos e posicionamentos comprometidos com a superação da cis-heteronormatividade, demarcando e reforçando a importância de políticas sociais abrangentes. A obra é necessária não somente para o público acadêmico engajado e envolvido com a temática, mas para todas as pessoas que acreditam na contribuição da ciência para a qualidade de vida individual e coletiva.', '["LGBT population","comprehensive care","care production","cisheteronormativity","social policy","quality of life"]', '10.7476/9786556304007', '9786556302164', 'https://books.scielo.org/id/hdjh2', NULL, NULL, 'https://books.scielo.org/id/hdjh2/cover/cover_thumbnail.jpeg', 413, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hdq6f', 'hdq6f', 'Contos de Fatos: histórias de Manguinhos', NULL, '["Virgínia Torres Schall"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Resultado de entrevistas com cientistas famosos no campo da saúde pública, particularmente da Fundação Oswaldo Cruz, relata versões de histórias reais, escritas ao sabor da narrativa dos autores-personagens que as viveram ou contaram. Dotada de simplicidade, discrição e humor, a autora nos conduz à verdade sobre a imagem que habitualmente se faz dos cientistas. Ao discorrer sobre as ''faces ocultas'' - a da ciência, a do país -, este livro é importante relato histórico que desperta interesse por seu rico e raro conteúdo, muito bem-vindo em um Brasil que se apercebe mais e mais do real valor da ciência.', '["Manguinhos","Fiocruz","scientific history","public image of science"]', '10.7476/9788575416143', '9788575416143', 'https://books.scielo.org/id/hdq6f', 'https://books.scielo.org/id/hdq6f/pdf/schall-9788575416143.pdf', NULL, 'https://books.scielo.org/id/hdq6f/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hdyfg', 'hdyfg', 'Diplomacia da saúde e Covid-19: reflexões a meio caminho', NULL, '["Buss, Paulo Marchiori","Fonseca, Luiz Eduardo"]', 'Série Informação para ação na Covid-19 | Fiocruz', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Passados os primeiros meses da pandemia do novo coronavírus no Brasil, o Observatório Covid-19 Fiocruz, em parceria com a Editora Fiocruz e com o apoio da Rede SciELO Livros, traz para o público leitor um conjunto de livros instantâneos sobre as análises nele realizadas desde que foi criado para subsidiar o seu combate. Nesta série Informação para Ação na Covid-19 será apresentado um balanço do conjunto de documentos (notas e relatórios técnicos, boletins, ensaios, informes, recomendações, ensaios, artigos, entre outros) produzidos em resposta à pandemia. Cada volume da série se estrutura em torno de um tema: aspectos globais da pandemia e da diplomacia em saúde; cenários epidemiológicos e vigilância em saúde; as políticas e a gestão dos serviços e sistemas de saúde; orientações para os cuidados e a saúde dos trabalhadores da saúde; impactos sociais e desigualdades sociais na pandemia. Com a publicação destes estudos em livros instantâneos e de acesso aberto colocamos à disposição do público o conjunto de informações e conhecimentos gerados no âmbito do Observatório Covid-19 Fiocruz, realizamos um balanço e uma reflexão sobre como chegamos ao cenário atual e apontamos caminhos para um futuro próximo. E, ao mesmo tempo, mantemos o registro histórico desse conhecimento produzido a quente, no calor da hora.', '["health diplomacy","COVID-19 pandemic","international health cooperation","pandemic response","health policy","health services administration","social inequality","epidemiological scenarios","health surveillance"]', '10.7476/9786557080290', '9786557080290', 'https://books.scielo.org/id/hdyfg', 'https://books.scielo.org/id/hdyfg/pdf/buss-9786557080290.pdf', NULL, 'https://books.scielo.org/id/hdyfg/cover/cover_thumbnail.jpeg', NULL, 26, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hf4w9', 'hf4w9', 'A desconstrução do construtivismo na educação: crenças e equívocos de professores, autores e críticos', NULL, '["Cilene Ribeiro de Sá Leite Chakur"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Aos professores e professoras brasileiros que, com dedicação e perseverança, buscam ensinar, transmitir, corrigir e avaliar seus alunos, apesar de pacotes educacionais que tentam negar seu trabalho e sua função ao retirar-lhes a autonomia e a autoridade.SUMÁRIO Apresentação 9 Parte I -Construtivismo, psicologia e educação 15 1 Construtivismo e construção: conceitos-chave para compreender Piaget 17 2 A influência da Psicologia na educação e a recepção do Construtivismo no Brasil 27 3 Contextualizando as ideias pedagógicas de Piaget 31 Parte II -Uma pesquisa sobre os desvios do Construtivismo em professores do ensino fundamental 45 4 Pesquisando os desvios 47 5 Dez crenças sobre o Construtivismo e seus equívocos 55 6 Tentativa de interpretar a "assimilação deformante" dos professores 91 Parte III -Piaget e seus intérpretes 99 7 Os "pecados" dos "recados construtivistas" aos professores 101 8 Questionando algumas críticas 133 Conclusão', '["constructivism","Piaget","teacher beliefs","primary school teachers","assimilation","psychology and education","teacher autonomy","critique of education"]', '10.7476/9788568334485', '9788568334485', 'https://books.scielo.org/id/hf4w9', 'https://books.scielo.org/id/hf4w9/pdf/chakur-9788568334485.pdf', NULL, 'https://books.scielo.org/id/hf4w9/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hf9mk', 'hf9mk', 'Ensinar história no oitocentos: um estudo sobre a genealogia, a circulação transnacional e as apropriações do Método Zaba', 'um estudo sobre a genealogia, a circulação transnacional e as apropriações do Método Zaba', '["Carollina Carvalho Ramos de Lima"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Ensinar História no Oitocentos: um estudo sobre a genealogia, a circulação transnacional e as apropriações do Método Zaba investiga a trajetória de uma das mais inovadoras propostas pedagógicas para o ensino de História no século XIX. A partir da circulação do Método Zaba entre Europa, Américas e Australásia, a obra reconstrói os caminhos percorridos pelo educador polonês Napoleão Félix Zaba e revela as conexões transnacionais que marcaram a formação da escola moderna. Ao analisar a difusão, as apropriações e os debates em torno do método no Brasil oitocentista – especialmente em Salvador, onde chegou em 1871 – o livro oferece uma rica contribuição para os estudos sobre História da Educação, cultura material escolar e ensino de História, evidenciando o papel de sujeitos, objetos, práticas e deslocamentos na constituição dos sistemas escolares modernos.', '["history education","history of education","transnational circulation","19th-century education","history of pedagogy","Salvador, Bahia"]', '10.7476/9786556309897', '9786556309125', 'https://books.scielo.org/id/hf9mk', 'https://books.scielo.org/id/hf9mk/pdf/lima-9786556309897.pdf', NULL, 'https://books.scielo.org/id/hf9mk/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hfh4m', 'hfh4m', 'Visiones sobre construcción de paz, sociedad civil y fortalecimiento de la democracia: ponencias ganadoras del III Concurso Nacional de Semilleros de Investigación Facultad de Jurisprudencia', NULL, '["Torres V., María Lucía","Iregui P., Paola Marcela"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2013, '2013-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Como en los dos años anteriores, la Universidad del Rosario, por conducto del Observatorio Legislativo y el Grupo de Investigación en Derechos Humanos de la Facultad de Jurisprudencia, se ha asociado con la Fundación Hanns Seidel para organizar el III Concurso Nacional de Semilleros de Investigación, el cual tiene por objeto promover e incentivar la investigación entre los estudiantes de diferentes áreas del conocimiento, enfocada hacia temáticas de especial relevancia para el país, lo cual representa un aporte que, desde la etapa de formación, los futuros profesionales de nuestra nación hacen al análisis y la reflexión de esos temas que tanta relevancia tienen. La democracia, sus elementos, su materialización mediante la participación ciudadana, son un eje de especial importancia para investigar. La tercera versión del concurso permitió a los estudiantes participantes proponer interesantes tesis alrededor de la construcción de paz, la sociedad civil y el fortalecimiento de la democracia, tema de particular interés justo en este momento histórico del país, en el marco de los diálogos de paz que se adelantan desde octubre de 2012 en La Habana. Para lograr un estudio más profundo de las temáticas que se abordan en el concurso, la competencia se propone siempre en el marco de un seminario internacional que evoque el mismo tema. Este año, en asocio con el Observatorio de Restitución de Tierras y Derechos de la Propiedad Agraria, que representa el esfuerzo de cinco universidades colombianas por estudiar el tema de la tierra, tan emblemático en nuestro país, se organizó el diálogo mayor “Conflicto, desigualdad y desarrollo: trasformaciones agrarias y paz”, que contó con más de quinientos asistentes, procurando un análisis de expertos de alto nivel alrededor de las preguntas que deben plantearse los gobiernos, los líderes y la sociedad civil en la búsqueda de la anhelada paz. De las ponencias recibidas por parte de diferentes instituciones educativas del país en el marco de la convocatoria del concurso, veinte de ellas fueron seleccionadas para participar en la fase oral de los días 18 y 19 de septiembre de 2013 en la Universidad del Rosario. Tanto la fase oral como la escrita contaron con la participación de profesores de altas competencias profesionales y académicas que, como pares evaluadores y jurados en ambas fases, certificaron la calidad de las ponencias presentadas y con ello los resultados obtenidos. Por tercer año consecutivo las ponencias ganadoras del concurso son publicadas por la Editorial de la Universidad del Rosario y gracias a la financiación de la Fundación Hanns Seidel, que desde el principio creyó y respaldó esta iniciativa. Así pues, continuamos con nuestro deber académico de incentivar el debate a partir de la investigación en temas de actualidad jurídica, política y social realizada por los estudiantes y cumplimos con nuestro objetivo de seguir construyendo la Colección Semilleros de Investigación de la Universidad del Rosario, la cual es distribuida a las diferentes bibliotecas nacionales, departamentales y universitarias, con el fin de llegar al mayor número posible de destinatarios para que puedan conocer las reflexiones de nuestros estudiantes.', '["peacebuilding","civil society","democracy strengthening","citizen participation","Colombian peace process","Havana peace talks","agrarian conflict","land restitution","land reform","student research competition","Colombian armed conflict","human rights"]', '10.7476/9789587842814', '9789587384253', 'https://books.scielo.org/id/hfh4m', 'https://books.scielo.org/id/hfh4m/pdf/torres-9789587842814.pdf', 'https://books.scielo.org/id/hfh4m/epub/torres-9789587842814.epub', 'https://books.scielo.org/id/hfh4m/cover/cover_thumbnail.jpeg', 135, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hfj6p', 'hfj6p', 'Quimeras da socioeducação e o (não) lugar dos jovens: potencialidades da Educação em Direitos Humanos', 'potencialidades da Educação em Direitos Humanos', '["Débora Cristina Fonseca"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro revisita a trajetória de pesquisa e extensão desenvolvida por Débora Cristina Fonseca no campo da socioeducação com jovens pobres, marcados pelo fracasso escolar e pela exclusão, para discutir as potencialidades da escola frente à defesa de direitos humanos. A autora analisa as contradições do sistema educacional, socioeducativo e sociopenal e as formas perversas de culpabilização e eliminação daqueles que não se enquadram no modelo neoliberal de constituição da subjetividade. As reflexões apresentadas ao longo dos capítulos estão amparadas nos pressupostos da teoria sócio-histórica e têm como base a teoria vigotskiana e a compreesão dos processos de escolarização. A autora também apresenta o conceito de Educação em Direitos Humanos e suas possibilidades de transforma-ação do cotidiano escolar, oferecendo subsídios para o trabalho pedagógico em todos os níveis de ensino e indicando os caminhos para o desenvolvimento de sujeitos capazes de lutar por seus direitos e para a atuação preventiva contra os processos de abandono e exclusão escolar.', '["social education","human rights education","low-income youth","school failure","school exclusion","neoliberalism","school dropout prevention","school socialization","Vygotsky","socio-historical theory","culpabilization"]', '10.7476/9786557145500', '9786557145500', 'https://books.scielo.org/id/hfj6p', 'https://books.scielo.org/id/hfj6p/pdf/fonseca-9786557145500.pdf', NULL, 'https://books.scielo.org/id/hfj6p/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hg9jx', 'hg9jx', 'A figura do herói antigo nas crônicas medievais da Península Ibérica (século XIII e XIV)', NULL, '["Simone Ferreira Gomes de Almeida"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Por ser o herói uma construção determinada a partir das necessidades de sua época, ele se torna um ser extremamente singular e insubstituível. O processo de criação e apropriação da figura heróica que emerge dos textos da Península Ibérica dos séculos XIII e XIV é o objeto deste livro de Simone Ferreira Gomes de Almeida. A autora parte das antigas técnicas mnemônicas, que indicavam o uso de determinados símbolos como método de despertar a memória, para chegar à Idade Média. Na Antiguidade, ela demonstra, as melhores imagens que se podia evocar para recordar vícios e virtudes eram as dos deuses e heróis, como reza o texto conhecido como Dialexeis (400 a.C.). Almeida mostra que, na Idade Média, as figuras mitológicas são retomadas da Antiguidade para lembrar o que fosse considerado virtuoso, bom e verdadeiro, agora de acordo com a ética cristã. Dessa forma, deveriam transmitir o conhecimento que Deus proporcionou aos homens, ou seja, a salvação, a santidade e a vida eterna. Como os escritos antigos não se adequavam ao gosto do tempo e a seus valores, os cronistas medievais da Península Ibérica dos anos 1200 e 1300 decidiram revitalizá-los, reformando-os como fonte da verdade divina. As antigas figuras da mitologia passaram, então, a lembrar à sociedade que os vícios eram o caminho para o Inferno e as virtudes, para o Paraíso. Assim, a construção da figura do herói dos medievais, de acordo com a autora, levou em conta inclusive os interesses dos escritores das cortes ibéricas de enaltecer o homem que deixasse sua marca não apenas na sua geração, mas também nas posteriores. Ela escreve: “Tendo em vista que, assim como o herói clássico alcançou a sobrevivência da sua fama através dos séculos na memória coletiva, os cronistas dos séculos XIII e XIV desejaram alcançar a mesma glória para sua dinastia através da construção de linhagens forjadas, que procuravam afirmar ainda mais devido ao propósito da centralização do poder na Península Ibérica”.', '["medieval heroes","medieval chronicles","Iberian Peninsula","13th century","14th century","classical mythology","mnemonics","virtue and vice","Christian ethics","collective memory","classical reception","medieval historiography"]', '10.7476/9786557144893', '9786557144893', 'https://books.scielo.org/id/hg9jx', 'https://books.scielo.org/id/hg9jx/pdf/almeida-9786557144893.pdf', NULL, 'https://books.scielo.org/id/hg9jx/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hhf6n', 'hhf6n', '(Des)encontros trabalho-família: narrativas de familiares de trabalhadores migrantes do setor de produção de energia hidrelétrica', NULL, '["Daniele Almeida Duarte"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro convida o leitor a se aventurar no universo dos barrageiros por meio das narrativas de vida, desvelando que os empreendimentos hidrelétricos brasileiros não geraram apenas impacto ambiental, mas um processo de desenraizamento e rupturas socioafetivas que produziram distintos modos de ser-trabalhar-viver. A desterritorialização principiada por esses projetos integram um ideário desenvolvimentista e de progresso que ocultam o avesso dessa história. Na relatividade do dentro e fora do labor, verificou-se o tempo de trabalho e de vida capazes tanto de interditar a existência em sua potência criadora quanto de resistir, transformando a subjetividade e a vivência familiar em uma insistente reinvenção.', '["work-family interface","migrant workers","life stories","deterritorialization","development ideology","working hours","family life"]', '10.7476/9788579837012', '9788579837012', 'https://books.scielo.org/id/hhf6n', 'https://books.scielo.org/id/hhf6n/pdf/duarte-9788579837012.pdf', 'https://books.scielo.org/id/hhf6n/epub/duarte-9788579837012.epub', 'https://books.scielo.org/id/hhf6n/cover/cover_thumbnail.jpeg', 237, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hj25v', 'hj25v', 'Sinalização purinérgica: implicações fisiopatológicas', NULL, '["Andréia Machado Cardoso","Leandro Henrique Manfredi","Sarah Franco Vieira de Oliveira Maciel"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Biochemistry, Genetics and Molecular Biology', 'Embora existam diversos grupos brasileiros de pesquisa da sinalização purinérgica, o conhecimento sobre o tema tem sido amplamente difundido em língua inglesa em periódicos internacionais. Em língua portuguesa, os estudos, de um modo geral, constituem dissertações e teses. Todos os colaboradores do livro são pesquisadores brasileiros que estudam alguma situação fisiológica ou patológica envolvendo o sistema purinérgico. O livro trata do funcionamento da sinalização purinérgica em condições fisiológicas gerais e sobre a história das enzimas e dos receptores purinérgicos. Aborda situações fisiológicas, como a modulação do sistema purinérgico pelo exercício físico e por moléculas nutracêuticas. E dedica alguns capítulos para a relação da sinalização purinérgica em condições patológicas: diversos tipos de câncer; doenças endócrinas, como diabetes e disfunções da glândula tireoide; doença renal; hipertensão arterial sistêmica; doenças degenerativas, como doença de Alzheimer e doença macular relacionada à idade; doenças parasitárias e virais, dentre outras.', '["purinergic signaling","purinergic receptors","physical activity","nutraceuticals","cancer","diabetes mellitus","thyroid dysfunction","kidney disease","systemic arterial hypertension","Alzheimer''s disease","age-related macular degeneration","parasitic infection"]', '10.7476/9786586545494', '9786586545494', 'https://books.scielo.org/id/hj25v', 'https://books.scielo.org/id/hj25v/pdf/cardoso-9786586545494.pdf', NULL, 'https://books.scielo.org/id/hj25v/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hk62f', 'hk62f', 'Artefatos digitais para mobilização da sociedade civil: perspectivas para avanço da democracia', NULL, '["Pinho, José Antonio G. de"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'SOBRE OS AUTORESlos diseños y contenidos de las interfases generadas por los gobiernos locales.Así, retomando discusiones anteriores, realizadas sobre acceso a la información y transparencia, resignificamos en este trabajo la noción de accesibilidad, de uso corriente en el campo de la discusión tecnológica.Para esto intentamos salir del análisis de las barreras derivadas centralmente de las condiciones físicas del sujeto usuario de la tecnología, para poner sobre relieve los limites contextuales que afectan la capacidad comunicativa de los sujetos en ese campo y, en tal sentido, demandar en la utilización del medio por parte de los gobiernos la generación de entornos amigables, comprensibles, eficaces y apropiados para los procesos participativos.Con base en estas premisas observamos tres grandes dimensiones en las páginas web municipales: la identificación, la usabilidad y el contenido.Así, de acuerdo a lo observado en cada caso, el trabajo comparativo sobre los tres sitios web de los municipios considerados -Córdoba, Rosario y Morón-evidencia diferentes niveles de desarrollo del medio, en relación al intercambio comunicativo iniciado por el gobierno para difundir y sostener los espacios participativos.En términos generales, podríamos establecer un arco entre las experiencias, que ofrece cierta complejidad en el caso de Rosario y grandes limitaciones en el caso de Córdoba.Aunque en todas puede afirmarse que el ''contexto'' de implementación de las políticas tiñe la finalidad de la comunicación: la transparencia de resultados más que la información de procesos decisorios participativos.Privilegiando, entonces, el acceso a datos presupuestarios en el contenido, lo decidido, antes que a elementos que informen el proceso de toma de decisiones o que faciliten la integración/ articulación entre los ciudadanos en el propio proceso, para decidir lo que se va a hacer.A partir de los atributos del diseño también creemos que es posible en este punto generar algunas hipótesis sobre el mensaje gubernamental que nos permitan continuar a futuro los análisis, considerando los ''vínculos'' a los que se asocia el proceso participativo.Esto es, en', '["digital artifacts","civil society mobilization","democracy","municipal websites","local government communication","participatory processes","accessibility","usability","transparency","access to information","contextual barriers","Córdoba"]', '10.7476/9788523218775', '9788523218775', 'https://books.scielo.org/id/hk62f', 'https://books.scielo.org/id/hk62f/pdf/pinho-9788523218775.pdf', NULL, 'https://books.scielo.org/id/hk62f/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hkc44', 'hkc44', 'El resentimiento en el paramilitarismo. Análisis del discurso de Carlos Castaño Gil', NULL, '["Ángela Milena Salas García"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La idea del resentimiento como motivación política en el paramilitarismo suele tomarse como un lugar común. Este libro se resiste a aceptar la obviedad de esta afirmación y se ocupa de responder preguntas como ¿qué significa sentir resentimiento?, ¿cómo se manifiesta el resentimiento en los paramilitares como actores del conflicto armado colombiano?, ¿en qué medida los sentimientos como odio, rencor y venganza tienen un carácter político? Estas preguntas se ubican en el campo de la ética o la filosofía moral. El trabajo es una discusión en torno a estas preguntas, en la cual se toman prestados conceptos de áreas como la Ciencia Política y la Sociología, y así se construye una interesante reflexión acerca de la ética y el paramilitarismo. La aplicación de los conceptos y de la discusión se logró al abordar el caso concreto de Carlos Castaño Gil. Se tomaron las intervenciones públicas, los comunicados, las entrevistas en prensa y televisión que Castaño dio en sus años de comandante de las AUC para conformar la base del análisis de sus sentimientos. Con ello, se delineó una moralidad en este personaje y se señaló cómo se ponen de manifiesto algunos de sus sentimientos y la evolución que llegaron a tener. Los resultados de esta investigación muestran entonces, algunos rasgos de la personalidad de Castaño que dan respuesta a las preguntas formuladas. El libro es un ejercicio interdisciplinar en el que se combina la descripción histórica del paramilitarismo, una discusión teórica acerca de algunos aspectos políticos y éticos y, finalmente, los resultados de una investigación cualitativa. Sin omitir la necesidad de analizar otras motivaciones políticas, históricas, económicas y culturales del conflicto, este trabajo privilegia una aproximación desde la ética que hasta ahora no ha sido el enfoque al que más se acude para el estudio de este problema.', '["paramilitarism","resentment","political motivation","AUC","Colombian armed conflict","political ethics","hatred","revenge","political discourse","emotions in politics"]', '10.7476/9789585005358', '9789588378350', 'https://books.scielo.org/id/hkc44', 'https://books.scielo.org/id/hkc44/pdf/salas-9789585005358.pdf', NULL, 'https://books.scielo.org/id/hkc44/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hkhqp', 'hkhqp', 'Educación y pedagogía en política y relaciones internacionales: experiencias y reflexiones', NULL, '["Carlos Eduardo Maldonado"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Los avances más interesantes, desde cualquier punto de vista, en el conocimiento suceden en campos en los que la interdisciplinariedad es auténtica y real. Basta con echar una mirada desprevenida al estudio de los problemas más apasionantes y difíciles en nuestro entorno y alrededor del mundo para verificarlo. Pues bien, la vida misma de las Facultades de Ciencia Política y Gobierno y Relaciones Internacionales de la Universidad del Rosario constituyen un ejemplo próximo e inmediato del carácter abierto, cruzado e integrado entre ciencias, disciplinas, aproximaciones, lenguajes, métodos y enfoques que se nutren recíprocamente unos a otros. Este libro es una contribución a este espíritu y diálogo.', '["pedagogy","political science","international relations","interdisciplinarity","university teaching","Colegio Mayor de Nuestra Señora del Rosario"]', '10.7476/9789587385700', '9789587385694', 'https://books.scielo.org/id/hkhqp', NULL, NULL, 'https://books.scielo.org/id/hkhqp/cover/cover_thumbnail.jpeg', 164, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
