.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hmn5z', 'hmn5z', 'Teoria histórico-cultural no Brasil grupos de pesquisa e desenvolvimento histórico', NULL, '["Asbahr, Flávia da Silva Ferreira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro representa uma síntese dos resultados da pesquisa “A Psicologia Histórico-Cultural na pesquisa brasileira: levantamento dos grupos de pesquisa cadastrados no diretório do CNPq” e apresenta também alguns de seus desdobramentos. O objetivo geral foi analisar a inserção da Psicologia Histórico-Cultural no âmbito da investigação científica no Brasil, em grupos de pesquisa que a indicam formalmente como norteadora de seus trabalhos. Tomou-se como referência os grupos cadastrados no Diretório de Grupos de Pesquisa (DGP) do Conselho Nacional de Desenvolvimento Científico e Tecnológico (CNPq) que apontassem a Psicologia Histórico-Cultural como referencial teórico. Os dados foram extraídos do diretório durante o ano de 2018.', '["historical-cultural psychology","research groups","CNPq Research Groups Directory","history of psychology in Brazil","Brazilian psychology"]', '10.7476/9786557144565', '9786557144565', 'https://books.scielo.org/id/hmn5z', 'https://books.scielo.org/id/hmn5z/pdf/asbahr-9786557144565.pdf', NULL, 'https://books.scielo.org/id/hmn5z/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hn3q6', 'hn3q6', 'Cidadania e participação social', NULL, '["Andréa Fernanda Silveira","Catarina Gewehr","Luiz Fernando Rolim Bonin","Yara L. M. Bulgacov"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Pois é exatamente aqui que se coloca o presente livro: é um grupo de cidadãos/ãs que decidem dizer sua palavra, na nova “agorá”, que é a discussão e construção teórica que se realiza nas academias e nas práticas sociais. Esse livro não é somente “fala”: ele é ação, ele é dimensão essencial na construção da cidadania através da participação consciente e crítica dos diversos atores/ autores/as que a ABRAPSO vem congregando, incentivando e fundamentando para a construção de uma sociedade eticamente justa, economicamente equitativa, politicamente participativa, culturalmente plural, socialmente democrática e solidária.', '["citizenship","social participation","citizen participation","social movements","social justice","political participation","solidarity"]', '10.7476/9788599662885', '9788599662885', 'https://books.scielo.org/id/hn3q6', 'https://books.scielo.org/id/hn3q6/pdf/silveira-9788599662885.pdf', NULL, 'https://books.scielo.org/id/hn3q6/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hn4ff', 'hn4ff', 'As teorias das guerras preventivas e as relações internacionais', NULL, '["Alberto Montoya Correa Palacios"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nos dias atuais, a agressão militar vem sendo reeditada fre­quentemente em todos os continentes. Sob a máscara da “defesa preventiva”, são realizadas expedições punitivas, derrubadas de governos e outros tipos de ingerência na soberania nacional dos países. A defesa da democracia, a defesa do livre mercado, a defesa da livre manifestação da cidadania ante o Estado opressor, a defesa da segurança nacional e até a defesa de algum deus já soaram como escusa para a “guerra preventiva”. Neste livro, Alberto Montoya Correa Palacios Junior retorna aos textos clássicos da filosofia política para analisar as diferentes doutrinas sobre “guerra preventiva”. O resultado desse esforço intelectual é uma análise madura e profunda sobre um tema muito atual, cuja gênese é mostrada na história do pensamento das Relações Internacionais sob o prisma das considerações políticas, jurídicas e éticas que envolvem a questão.', '["preventive war","just war theory","military intervention","state sovereignty","international relations theory","political philosophy","ethics of war","history of international relations thought","defense of democracy","national security"]', '10.7476/9786557145173', '9786557145173', 'https://books.scielo.org/id/hn4ff', 'https://books.scielo.org/id/hn4ff/pdf/palacios-9786557145173.pdf', NULL, 'https://books.scielo.org/id/hn4ff/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hn4hr', 'hn4hr', 'Cacau: cultivo, pesquisa e inovação', NULL, '["José Olímpio de Souza Júnior"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Este livro é composto por 17 capítulos que abordam diferentes temáticas como: trajetória de cultivo na Bahia, ecofisiologia e ambiente, indução de resistência ao ataque de patógenos, melhoramento genético, produção de mudas, biologia, física, química e manejo de solos, nutrição e adubação, irrigação, mecanização e sustentabilidade de sistemas agrossilviculturais com o cacaueiro.', '["Theobroma cacao","cocoa cultivation","Bahia","ecophysiology","disease resistance induction","genetic improvement","seedling production","soil management","fertilization","irrigation","mechanization","agrisilviculture"]', '10.7476/9786586213188', '9788574554846', 'https://books.scielo.org/id/hn4hr', NULL, NULL, 'https://books.scielo.org/id/hn4hr/cover/cover_thumbnail.jpeg', 558, 26, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hn9cv', 'hn9cv', 'A evolução recente do setor bancário no Brasil', NULL, '["Patrícia Olga Camargo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'O setor bancário brasileiro possui características muito específicas em relação aos bancos instalados em outros países. Na segunda metade da década de 1990, com a entrada dos bancos estrangeiros no país, iniciou-se um processo de reestruturação bancária, que acarretou importantes mudanças na estrutura e nos padrões de concorrência do setor. Neste livro são analisadas a evolução e a forma de atuação dos maiores bancos após esse processo de reestruturação, considerando o tipo de controle, se público, privado nacional ou privado estrangeiro.', '["Brazilian banks","bank restructuring","foreign bank entry","bank competition","bank ownership structure","state-owned banks","private banks","foreign banks"]', '10.7476/9788579830396', '9788579830396', 'https://books.scielo.org/id/hn9cv', 'https://books.scielo.org/id/hn9cv/pdf/camargo-9788579830396.pdf', NULL, 'https://books.scielo.org/id/hn9cv/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hnbsg', 'hnbsg', 'A Universidade Federal de São Paulo aos 75 anos: ensaios sobre memória e história', NULL, '["Luigi Biondi","Karen Macknow Lisboa","Ana Nemi","Rodrigues Jaime"]', 'Editora Fap-Unifesp', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Ulysses Fagundes Neto O que diríamos, se estivéssemos frente a nossos fundadores, hoje, após estes 75 anos de vida da Unifesp?Mais que isto, frente a todos que um dia estiveram, participaram e foram responsáveis, em alguma medida, pelo percurso histórico do que é hoje esta Universidade?Antes de responder, é preciso primeiro se deliciar com a possibilidade de isto acontecer, o que anuncia nosso orgulho pelo passado e estimula nossa luta pelo presente.As universidades passam a ser, principalmente a partir do século xx, os produtores primários do conhecimento nas sociedades modernas.Incluem-se aí a manutenção e multiplicação do estoque de conhecimentos estratégicos, papéis exercidos respectivamente enquanto instituições educacionais e de pesquisa.A universidade é uma instituição ímpar, mantendo-se presente frente às mudanças históricas, sem, contudo, deixar de acompanhar as alterações da sociedade.Isso porque, focalizada no ser humano e em suas questões essenciais, tem como função produzir conhecimento capaz de se inserir nos contextos sociais e políticos.Mas o conhecimento não é neutro e seu valor é sempre contextual.A aproximação daquele que busca conhecer, organizado em instituições, com a sociedade é que define e baliza o papel, a organização e o modus operandi das universidades, que são ao mesmo tempo reflexo e 14 ulysses fagundes neto contraponto das sociedades nas quais estão inseridos e de seus movimentos históricos.Indo então à resposta daquela pergunta inicial: que a Unifesp continua a mesma e, ao mesmo tempo, é outra.Santo Agostinho pode explicar porque continua a mesma.Num de seus textos encontramos uma idéia que revela o papel das instituições de ensino e pesquisa, papel este sempre perseguido e, sem dúvida, alcançado pela Unifesp com louvor.Falando sobre o que é um professor, no seu contexto institucional, Agostinho diz que professor é aquele que gera conhecimento novo -que é, sem dúvida, o nosso caso.E diz mais: a educação acontece quando não há intervalo entre o falar e o aprender.Ou seja, o conhecimento flui entre pessoas, algumas estando no momento na função de professor, outras de aluno.Nestes 75 anos a Unifesp não cessou um único segundo nesta tarefa, portanto permanece a mesma, mantendo-se como instituição chave do sistema educacional brasileiro.Diríamos a nossos fundadores que acreditamos estar cumprindo a missão da universidade, que é dar prova de sua viabilidade no decorrer dos séculos e de sua habilidade para induzir mudanças e progressos na sociedade.Que esta universidade só tem compromissos com a sociedade na qual se insere, sendo esta o único sentido de sua existência.Reafirmaríamos aquelas intenções, as de 75 anos, em manter a gratuidade do ensino público de graduação e pós-graduação stricto sensu, lato sensu e em todos seus sensos de relevância pública, como forma de representar plenamente o Estado que educa e difunde conhecimentos.Diríamos que apostamos, sempre, na indissociabilidade entre o ensino, a pesquisa, a extensão e a prestação de serviços à sociedade, como forma da universidade cumprir seu papel histórico.E não abrimos mão da excelência acadêmica, que permite legitimar a existência da Unifesp no bojo da sociedade que a financia.Temos nos obrigado, para isto, a dedicação integral à produção do conhecimento e ao atendimento à sociedade, à promoção e ensino de ações cidadãs e valores democráticos.Lutamos para que a sociedade tenha livre acesso ao conhecimento, e a prova disto é nossa definição e exercício de um modelo de gestão institucional democrático, transparente e participativo.Por fim, desejamos manter a universidade integrada ao processo de desenvolvimento da nação, dele participando como agente de construção e de análise crítica.prefácio 15 Nestes tempos, respiramos os ares de todos os tempos que mudaram, como todas as instituições fariam.Mas, com certeza, fomos agentes e atores de muitas mudanças, como, em especial, aquelas mais recentes, que culminaram no incrível incremento da produção científica e de recursos humanos, na prestação de serviços à sociedade e no processo de expansão universitária ora em curso.E, talvez, eles nos dissessem, olhando para tudo o que está aí: hoje a Unifesp é maior e melhor ainda.1. Escola Paulista de Medicina e Hospital São Paulo O ensino superior no Brasil é recente, mesmo quando comparado ao de outros países das Américas: o primeiro curso de ensino superior instalado no país acaba de completar duzentos anos.Por decisão do príncipe regente D. João vi, a Escola de Cirurgia da Bahia foi criada em 18 de fevereiro de 1808.A Escola Paulista de Medicina (epm) foi fundada em 1933, época associada ao nascimento da medicina moderna: "É habitual datar o começo da medicina moderna em algum ponto no meio dos anos de 1930, com a inserção da sulfonamida e da penicilina na farmacopéia, e é costumeiro atribuir a esses eventos a força da revolução na prática médica" 1 .', '["UNIFESP","university history","institutional memory","university identity","role of universities in society","knowledge production","university and society"]', '10.7476/9788561673833', '9788561673833', 'https://books.scielo.org/id/hnbsg', 'https://books.scielo.org/id/hnbsg/pdf/nemi-9788561673833.pdf', NULL, 'https://books.scielo.org/id/hnbsg/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hp3x7', 'hp3x7', 'Introdução à pesquisa sobre atividades de ensino e de aprendizagem em sala de aula', NULL, '["Marcelo Giordan","Luciana Massi"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Transformar a prática docente em objeto de pesquisa é um constante desafio para a educação. Nesta obra, os autores discutem e orientam cada etapa do processo de planejamento e realização de uma pesquisa voltada para a análise de situações de sala de aula, por meio de um olhar reflexivo sobre outras pesquisas com objetos semelhantes. Ela é fruto de um contexto de pesquisa de formação continuada de professores e serviu como material de apoio para professores e orientadores durante curso de especialização que culminou com a elaboração de trabalhos de conclusão de curso. Os autores apresentam aqui uma proposta que serve à dupla mediação de ensinar e aprender por meio da investigação, desenvolvida a partir de experiências de docentes e estudantes de fazer da sala de aula um cenário de pesquisa para ambos. Com abordagem investigativa, este livro pretende ser instrumento e razão para que docentes e estudantes conquistem seus direitos a uma educação integral e crítica que os levem a sua transformação e da própria sociedade.', '["classroom teaching and learning","teacher research","reflective practice","continuing teacher education","teacher professional development","research planning","classroom observation","critical education"]', '10.7476/9786557144527', '9786557144527', 'https://books.scielo.org/id/hp3x7', 'https://books.scielo.org/id/hp3x7/pdf/giordan-9786557144527.pdf', NULL, 'https://books.scielo.org/id/hp3x7/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hpm37', 'hpm37', 'Mata Atlântica: a história que a história não contou', 'a história que a história não contou', '["Diego Pereira Costa","Felipe Micali Nuvoloni","Elfany Reis do Nascimento Lopes"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'A obra revela uma história que não é abordada nos relatos tradicionais sobre o Brasil, remontando à chamada "descoberta" pelos colonizadores portugueses em Porto Seguro. Indo além da narrativa histórica, o livro se aprofunda na atualidade, focando no Sul da Bahia, onde examina os avanços e retrocessos no uso dos recursos naturais e na degradação dos ecossistemas. Também aborda os processos sociais e econômicos que continuam a transformar a Mata Atlântica, oferecendo uma perspectiva contemporânea sobre essas dinâmicas.', '["Atlantic Forest","Portuguese colonization of Brazil","Porto Seguro","natural resource use","ecosystem degradation","social and economic transformation","environmental history","alternative historical narratives"]', '10.7476/9788574556024', '9788574555898', 'https://books.scielo.org/id/hpm37', NULL, NULL, 'https://books.scielo.org/id/hpm37/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hpttj', 'hpttj', 'Observatório de análise política em saúde: abordagens, objetos e investigações', NULL, '["Carmen Fontes Teixeira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra resulta da elaboração de um projeto voltado ao aprofundamento e desenvolvimento das análises de políticas públicas na área de saúde, executado por uma rede de pesquisadores vinculados a diferentes instituições de saúde. O livro, portanto, reúne textos que contemplam diversos eixos temáticos, incluindo reflexões acerca de questões teórico-metodológicas da pesquisa na área de PPGAS. Trazem também resultados finais ou parciais de estudos e pesquisas no âmbito desses temas, tendo em comum a preocupação com subsidiar o debate em torno dos problemas que vêm sendo enfrentados no processo de formulação e implementação de políticas, bem como contribuir para a continuidade e aperfeiçoamento da Reforma Sanitária Brasileira.', '["health policy analysis","public policy research","health policy","Brazilian health reform","policy formulation","policy implementation","health research networks"]', '10.7476/9788523220211', '9788523220211', 'https://books.scielo.org/id/hpttj', 'https://books.scielo.org/id/hpttj/pdf/teixeira-9788523220211.pdf', NULL, 'https://books.scielo.org/id/hpttj/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hqhrv', 'hqhrv', 'O poder da cultura e a cultura do poder: a disputa simbólica da herança cultural negra no Brasil', NULL, '["Jocélio Teles dos Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro discute as políticas públicas na área de cultura, no período dos anos 60 aos anos 90, demonstrando como os símbolos afro-brasileiros foram sendo ressignificados, a partir do estabelecimento de novas demandas, seja pela política institucional ou pelos movimentos negros. Trata-se de um estudo pioneiro, principalmente quando analisadas a dinâmica da sociedade brasileira e as mudanças na adoção da simbologia de origem africana por distintos atores sociais.', '["cultural heritage","Black culture","cultural policy","Black movement","symbolic politics","cultural appropriation","culture and power","Brazilian society","1960s-1990s"]', '10.7476/9788523208950', '9788523208950', 'https://books.scielo.org/id/hqhrv', 'https://books.scielo.org/id/hqhrv/pdf/santos-9788523208950.pdf', NULL, 'https://books.scielo.org/id/hqhrv/cover/cover_thumbnail.jpeg', NULL, 74, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hqpzx', 'hqpzx', 'Acesso às urgências e atenção hospitalar: uma questão de direitos humanos', NULL, '["Gisele O’Dwyer","Mariana Teixeira Konder"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-11-30', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Apesar do volumoso e extenso investimento nos diversos componentes da Rede de Atenção às Urgências (RAU), a experiência dos usuários continua sendo a de acesso limitado, quando não interditado, e de muita luta e sofrimento para terem suas demandas atendidas. Temos frequentemente uma situação de atendimento demorado, quando de fato acontece, orientado para a queixa e completamente deslocado do restante da rede. A superlotação das emergências hospitalares sintetiza bem esse fenômeno, tornando-se o local em que a violação de direitos é mais intensamente vivenciada pelo usuário. A rede hospitalar encontrase no centro das respostas para essa experiência, sobretudo porque muito pouco foi feito pelo hospital ao longo de mais de três décadas de desenvolvimento do SUS. As condições do parque hospitalar e do sistema de urgência, pela precariedade sustentada ao longo dos anos, produzem sistematicamente sofrimento ao paciente, com significativas consequências, como aumento da morbidade e mortalidade', '["emergency care access","emergency department overcrowding","human rights","hospital care","patient suffering","emergency care network"]', '10.7476/9786557081730', '9786557081426', 'https://books.scielo.org/id/hqpzx', NULL, NULL, 'https://books.scielo.org/id/hqpzx/cover/cover_thumbnail.jpeg', 168, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hqxxq', 'hqxxq', 'Rumo ao Ceticismo', NULL, '["Oswaldo Porchat Pereira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os artigos que compõem esta coletânea foram publicados entre 1969 e 2005, e têm uma temática persistente: a da vida cotidiana e comum que a filosofia não pode nem deve trair se não quer converter-se em mero jogo de palavras. Para o autor, o pirronismo repensado e rearticulado conforme a linguagem e os problemas filosóficos da contemporaneidade, preserva, no entanto, total consonância com a inspiração original do pirronismo histórico e a mensagem da Sképsis grega continua plenamente atual, respondendo às necessidades filosóficas também de nosso tempo. São abordados: o conflito das filosofias, a filosofia e a visão comum do mundo, oceticismo e o mundo exterior, o ceticismo e a argumentação, a verdade, o realismo e o ceticismo, o ceticismo pirrônico e os problemas filosóficos,a autocrítica da razão no mundo antigo,o empirismo e o ceticismoe o argumento da loucura.', '["Pyrrhonism","skepticism","everyday life","common sense","realism","empiricism","argumentation","madness","contemporary philosophical problems"]', '10.7476/9788539304486', '9788571397804', 'https://books.scielo.org/id/hqxxq', NULL, NULL, 'https://books.scielo.org/id/hqxxq/cover/cover_thumbnail.jpeg', 352, 31, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hrc5s', 'hrc5s', 'Estigma e saúde', NULL, '["Simone Monteiro","Wilza Vieira Villela"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Sumário 9 Prefácio Prefácio É muito bem-vindo este Estigma e Saúde.Bem-vindo, em primeiro lugar, porque é expressão e sistematização da marcante entrada no campo da saúde, de modo geral, de uma discussão quase restrita, até pouco mais de uma década atrás, aos campos da psicologia social e do direito.No momento em que autores de diferentes formações acadêmicas e atuantes em prestigiosas instituições de ensino e pesquisa em saúde, no Brasil e no exterior, são chamados a reunir e divulgar suas mais recentes pesquisas e reflexões sobre o assunto, esse movimento de expansão tem novas chances de progredir.E de fazê-lo em um patamar de qualidade que deve nos deixar a todos ainda mais esperançosos acerca dos seus impactos positivos sobre a saúde e a cidadania de modo geral.Entre muitos outros, talvez o maior mérito dos estudos aqui reunidos seja exatamente este, o de buscar dar consistência conceitual e compromisso prático à utilização das categorias ''estigma'' e ''discriminação'', ao mesmo tempo que estendem seu escopo e alcance.Partindo das investigações acerca dos seus efeitos sobre indivíduos e dos dispositivos jurídicos para lidar com suas implicações na proteção de direitos, caráter predominante nos estudos clássicos sobre o assunto, estes estudos ampliam o debate rumo à compreensão das raízes sociais de estigmas e discriminações e de suas relações com os modos coletivos como organizamos e significamos as práticas de saúde de coletivos humanos e a promoção de direitos sociais.Nesta ampliação e adensamento, e não poderia ser diferente, são chamados à discussão outros conceitos relacionados, como preconceito, violência, vulnerabilidade; diferentes temas, como HIV/Aids, Estratégia Saúde da Família, direitos sexuais e reprodutivos; diversas perspectivas teórico-metodológicas e epistemológicas, como a epidemiologia, as ciências sociais e humanas, a filosofia.Deste frutífero encontro, resulta um estimulante painel conceitual que nos faz sentir mais capazes de enxergar o adoecimento e o cuidado (ou a falta dele) nas suas dimensões propriamente públicas, iluminadas por conceitos que, ao indicar as contradições e fracassos das promessas emancipatórias de nossas sociedades tardomodernas, nos indicam, contrafaticamente, caminhos concretos para promover a saúde como um valor prático, a ser coletivamente construído no espaço público.No mesmo movimento, e por força do próprio caráter crítico das contribuições 10 Estigma e Saúde que aqui dialogam, importantes lacunas e desafios são descortinados, já desde a construção e legitimação das bases epistemológicas e metodológicas dos estudos capazes de apoiar tal construção, até os obstáculos políticos configurados por estruturas institucionais e simbólicas conservadoras e reprodutoras de iniquidades, injustiças e vulnerabilidades.Assim, embora as contribuições deste livro sejam aplicáveis a situações que não se restringem ao Brasil, mas dizem respeito a conjunturas e contextos políticos globalmente articulados, é impossível não destacar a relevância que as discussões aqui publicadas assumem no cenário do Sistema Único de Saúde (SUS), uma das mais potentes políticas públicas do Brasil contemporâneo e, por isso mesmo, foco de acirradas disputas entre interesses que extrapolam o âmbito estritamente técnico da organização das ações de saúde.E seria um engano reduzir esses confrontos, como é frequente fazermos, à disputa ideológica e política entre interesses econômicos privados e os compromissos do Estado na prestação de serviços de saúde -o que já não seria pouco.Estão também imediatamente em questão, nos embates aí travados, as concepções de público e privado e o lugar destas esferas na construção da cidadania e da saúde no país.Há, aqui, uma radical questão cultural em jogo -entendendo-se cultural na acepção de um devir de sentido, de uma totalidade abrangente, dinâmica e compartilhada, que amalgama e estrutura ciência, arte, crenças, saberes, técnica, política, economia, ética, direito etc., em um mundo vivido dotado de significados compartilhados e ''co-nstruídos''.O debate sobre o espaço e as relações entre o público e o privado na saúde, nesta perspectiva cultural, demonstra a relevância do SUS para a formação social brasileira e, ao mesmo tempo, a necessidade de examinar seus fundamentos e estruturas, atravessados por arraigadas práticas de apropriação privada do público, de um lado, e, de outro, pela invasão do privado por potentes normatividades emanadas de racionalidades supostamente públicas, mas que lhe são estranhas e, frequentemente, opressoras.Essas perversas relações, que obstaculizam uma construção radicalmente democrática da vida política e fixam, de forma naturalizada e absoluta, identidades e necessidades subjetivas, refletem-se no estigma e na discriminação como padrões recorrentes e reiterados de interação social, e dos quais nada podemos esperar senão desrespeito e violência, o que repercute nas diversas situações de vulnerabilidade no que se refere à saúde.Por isso, identificar, compreender e debater estigma e discriminação é mais do que explorar academicamente uma categoria da psicologia social ou do direito.Estigma e discriminação são fecundas categorias de apoio para uma hermenêutica Prefácio Referências', '["stigma","discrimination","health","prejudice","violence","vulnerability","HIV/AIDS","Family Health Strategy","sexual and reproductive rights","social rights","citizenship","social determinants of health"]', '10.7476/9788575415344', '9788575415344', 'https://books.scielo.org/id/hrc5s', 'https://books.scielo.org/id/hrc5s/pdf/monteiro-9788575415344.pdf', NULL, 'https://books.scielo.org/id/hrc5s/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hrnqn', 'hrnqn', 'Nós, professores: reflexões e memórias do trabalho com o ensino e aprendizagem de línguas', NULL, '["Simone Bueno Borges da Silva","Patrícia Argôlo Rosa","Raulino Batista Figueiredo Neto"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os oito textos reunidos no livro trazem a voz de professores que vivenciam cotidianamente os dilemas e os prazeres do ofício, apresentando textos ora memorialísticos que engendram reflexões sobre a práxis pedagógica, ora ensaísticos discutindo conceitos que embasam as escolhas did', '["language teaching","language learning","teacher reflection","teacher memories","pedagogical praxis","teacher dilemmas","teacher identity"]', '10.7476/9786586213225', '9786586213225', 'https://books.scielo.org/id/hrnqn', 'https://books.scielo.org/id/hrnqn/pdf/silva-9786586213225.pdf', NULL, 'https://books.scielo.org/id/hrnqn/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hsyw7', 'hsyw7', '“O que os pais vão falar?”: gênero, sexualidade e círculos dialógicos com educadoras', NULL, '["Fabiane Freire França"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“O que os pais vão falar?” Essa foi a pergunta realizada por uma professora da Educação Infantil expressa também em falas de outras 18 educadoras. Para a maioria delas, o trabalho sobre gênero e sexualidade precisa ser abordado no espaço escolar. Todavia, as educadoras consideram que ‘a sociedade não está preparada para este tipo de embate’. E como problematizar essas discussões? Encontramos nos círculos dialógicos a coexistência de vários pontos de vista das participantes e do grupo como um caminho possível para tais reflexões.', '["gender","sexuality","early childhood education","preschool teachers","dialogic circles","teacher professional development","social preparedness","teacher perceptions"]', '10.7476/9786587626116', '9786586383737', 'https://books.scielo.org/id/hsyw7', NULL, NULL, 'https://books.scielo.org/id/hsyw7/cover/cover_thumbnail.jpeg', 179, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-htjgj', 'htjgj', 'Ensaios: subjetividade, saúde mental, sociedade', NULL, '["Paulo Amarante"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Composta por textos históricos, filosóficos, antropológicos, sociológicos, clínicos, enfim, de diferentes abordagens relacionadas à área. O livro procura, em especial, dar prosseguimento às questões suscitadas pelos pensadores Michel Foucault e Franco Basaglia, visando a provocar um debate acerca dos modos de subjetivação vigentes em nossa sociedade, assim como propor alternativas aos processos de patologização da experiência trágica da loucura. Destaque para um documento histórico sobre a visita que Olavo Bilac fez à seção de crianças do Hospício Nacional de Alienados, em 1905. Obra de fundamental importância, de conteúdo indispensável para estudiosos e leigos no assunto.', '["subjectivity","mental health","madness","subjectivation","Michel Foucault","Franco Basaglia","Olavo Bilac","children''s psychiatric hospital","history of psychiatry","social construction of madness"]', '10.7476/9788575413197', '9788575413197', 'https://books.scielo.org/id/htjgj', 'https://books.scielo.org/id/htjgj/pdf/amarante-9788575413197.pdf', NULL, 'https://books.scielo.org/id/htjgj/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.c