INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-htnbt', 'htnbt', 'Ensino de ciências e matemática, II : temas sobre a formação de conceitos', NULL, '["Ana Maria de Andrade Caldeira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Coletânea de textos apresentados no Programa de Pós-Graduação em Educação para a Ciência, sediado na Faculdade de Ciências da UNESP, na área de ensino de Ciências e Matemática. O núcleo de pesquisa do Programa concentra-se em estudos sobre a ciência, a educação científica e nas relações entre o saber científico e seu ensino. Assim, incentiva a reflexão sobre os processos envolvidos na construção dos conhecimentos científicos e tecnológicos, além de contribuir para a produção de um corpo de conhecimentos filosóficos, científicos e pedagógicos destinados à formação de professores e outros profissionais da área', '["science education","mathematics education","concept formation","scientific knowledge construction","philosophy of science","teacher professional development","scientific and technological knowledge"]', '10.7476/9788579830419', '9788579830419', 'https://books.scielo.org/id/htnbt', 'https://books.scielo.org/id/htnbt/pdf/caldeira-9788579830419.pdf', NULL, 'https://books.scielo.org/id/htnbt/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hvsdh', 'hvsdh', 'Pesquisa qualitativa em geografia: reflexões teórico-conceituais e aplicadas', NULL, '["Glaúcio José Marafon","Júlio César de Lima Ramires","Miguel Ângelo Ribeiro","Vera Lúcia Salazar Pessôa"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Reúne 27 artigos que têm, como fio condutor, a pesquisa qualitativa em geografia, tratando ora de reflexões teórico-conceituais, ora de sua aplicação empírica, em diferentes recortes espaciais do território brasileiro. Os textos resultam de estudos envolvendo pesquisadores, assim como alunos de pós-graduação (mestrado e doutorado) e de iniciação científica. Enfatizam, com clareza e rigor didático, a relevância da aplicação da pesquisa qualitativa em geografia e abordam a realização dos procedimentos adequados para a coleta e análise de dados.', '["data collection methods","data analysis","Brazilian territory","graduate research"]', '10.7476/9788575114438', '9788575114438', 'https://books.scielo.org/id/hvsdh', 'https://books.scielo.org/id/hvsdh/pdf/marafon-9788575114438.pdf', NULL, 'https://books.scielo.org/id/hvsdh/cover/cover_thumbnail.jpeg', NULL, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hw33t', 'hw33t', 'Proteção à natureza e identidade nacional no Brasil, anos 1920-1940', NULL, '["José Luiz de Andrade Franco","José Augusto Drummond"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Aborda a realização da Primeira Conferência Brasileira de Proteção à Natureza, em 1934. E analisa, oportunamente, a maneira como um grupo de naturalistas ligados à proteção da natureza e articulados ao contexto político-intelectual desempenhou papel relevante na formulação de políticas públicas relacionadas à conservação do patrimônio natural brasileiro durante o governo Vargas. A conferência representou a concretização de todo o esforço de mobilização dos interessados na conservação da natureza, tendo inserido o Brasil nos debates internacionais preservacionistas e conservacionistas. Desde então, o tema ''proteção da natureza'' passou a ter cada vez mais visibilidade, sendo incorporado à Constituição brasileira de 1934 como assunto de responsabilidade da União, originando daí o nascimento de políticas efetivas por parte do governo - como legislações específicas, códigos de Caça e Pesca, de Águas, Florestal e outros -, além da criação dos primeiros parques nacionais brasileiros. As questões e soluções apontadas pelos quatro naturalistas e divulgadores científicos da época, que compunham este grupo - Alberto José Sampaio, Armando Magalhães Corrêa, Cândido de Mello Leitão e Frederico Carlos Hoehne - são atuais e constituem parte da discussão ambiental contemporânea. O trabalho histórico dos autores eleva o tema, de grande importância: a defesa do patrimônio natural do Brasil, demonstrando como os ideólogos precursores acabaram por ter suas idéias submersas pela ''maré desenvolvimentista''.', '["nature protection","naturalists","national identity","Vargas government","conservation policy","natural heritage","Brazilian Constitution of 1934","national parks","environmental law","conservationism","preservationism","developmentalism"]', '10.7476/9788575413548', '9788575411711', 'https://books.scielo.org/id/hw33t', NULL, NULL, 'https://books.scielo.org/id/hw33t/cover/cover_thumbnail.jpeg', 272, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
