ions.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hwhyp', 'hwhyp', 'Os diários de Langsdorff Vol. 2', NULL, '["Danuzio Gil Bernardino da Silva","Комиссаров Борис Николаевич","Hans Becher","Paulo Masuti Levy","Marcos P. Braga"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O zoólogo, botânico e médico alemão Langsdorff foi o mentor dessa grandiosa aventura naturalista: entre 1821 e 1829, conduziu um grupo de pesquisadores e desenhistas por uma viagem de 17 mil quilômetros, estudando a fauna, a flora e o modo de vida do interior do Brasil. Os registros, em textos e ilustrações, dessas cenas até então inéditas da natureza brasileira estão contidos nesses três primeiros volumes. Um quarto e último volume - contendo mapas e reproduções fac-similares de documentos originais - está em fase de preparo.', '["natural history expedition","Brazilian flora","scientific illustration","19th-century natural history"]', '10.7476/9788575412459', '9788575412459', 'https://books.scielo.org/id/hwhyp', 'https://books.scielo.org/id/hwhyp/pdf/silva-9788575412459.pdf', NULL, 'https://books.scielo.org/id/hwhyp/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) T