INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hws8h', 'hws8h', '“Todo lo que sabemos lo sabemos entre todos”: sistematización de dos experiencias escolares en las que se integran las TIC', NULL, '["Rosa, Adriana de la","Alexandra Roldán, Claudia","Rincón Bonilla, Gloria","Caicedo, Jorge","Camilo Zúñiga, Juan","Elena Yela, Carmen","Morales, Mario","Cortés, Arabella","Ramírez, Édgar","Pabón, Yadira","Herrera, Adriana","Alicia Espinoza, Carmen","Inés Castillo, Clara","Agudelo, Gloria"]', 'Editorial Universidad Autónoma de Occidente', 'Colombia', 'SciELO Books', 'books', 2018, NULL, 'es', 'book', 'engineering-tech', 'Ingeniería y Tecnología', NULL, '', '[]', '10.7476/9789586190046', '9789588994635', 'https://books.scielo.org/id/hws8h', NULL, NULL, 'https://books.scielo.org/id/hws8h/cover/cover_thumbnail.jpeg', 192, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hxdx4', 'hxdx4', 'Hilando fino. Voces femeninas en La Violencia', NULL, '["María Victoria Uribe"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'La propuesta que hace la autora de este libro es interpretar la figura del Ángel de la Historia desde un ángulo antropológico y hacer una lectura de la IX Tesis de Benjamín donde aparece dicha figura, a partir de consideraciones que provienen de una antropología de la guerra y el conflicto. Una lectura situada de esa imagen tan inquietante y misteriosa mediante la cual Benjamín puso de presente los desaciertos del historicismo y la fatalidad del progreso. En los relatos de las mujeres que aparecen en este libro se entrelazan emociones, recuerdos e interpretaciones que ponen en evidencia la ruptura traumática que producen los eventos de la guerra. Las sobrevivientes, aunque logran articular oralmente su relato, tienen dificultades para darle un sentido a los hechos vividos. La intención es hacer audible el silencio de medio siglo que ha rodeado la vida de las mujeres que fueron niñas durante La Violencia, y con ello contribuir a darle un sentido al sin sentido. Al hurgar en las ruinas del pasado necesariamente se entra en contacto con episodios catastróficos que, por lo general, no tienen explicación y que, aunque lo intentemos, no se pueden remediar.¬ El Ángel de la Historia quisiera detenerse, despertar a los muertos y recomponer lo destruido porque se siente interpelado por las ruinas del pasado. Si nuestro ángel transitara por entre los restos y las ruinas de memoria que dejaron tras de sí los doscientos mil muertos de La Violencia, ¿podría ser testigo de las vivencias de los que nunca hablaron?, ¿de los que nunca reclamaron?, ¿de los que nunca fueron reivindicados por la justicia?, ¿podría el Ángel reclamar la representación de quienes fueron asesinados y sus cuerpos tirados a los ríos con el fin de desaparecer toda evidencia? En suma, ¿podría el ángel representar nuestra catástrofe y cómo sería esa representación?', '["La Violencia","women''s testimony","Angel of History","Walter Benjamin","anthropology of war","war trauma","war survivors","children in armed conflict","historicism","progress","Colombian civil war","oral narrative"]', '10.7476/9789587386349', '9789587386332', 'https://books.scielo.org/id/hxdx4', NULL, NULL, 'https://books.scielo.org/id/hxdx4/cover/cover_thumbnail.jpeg', 272, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hymj4', 'hymj4', 'Atenção à saúde das famílias latino-americanas: abordagens teóricas e práticas na educação', NULL, '["Javier Isidro Rodríguez López","Schwartz, Eda","Lise, Fernanda"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Esta obra, que reúne 11 capítulos escritos por 30 autores e coautores do Brasil, do Chile, da Colômbia, de Cuba, do México e do Uruguai, busca dar voz às iniciativas preocupadas com o impacto das ações humanas na saúde e no bem-estar das pessoas. Objetiva apresentar abordagens teóricas e práticas de educação em saúde nas diferentes etapas do ciclo de desenvolvimento em distintos cenários da atenção à saúde das famílias latino-americanas. Apresenta estudos que envolvem os seguintes temas: práticas educativas e de cuidados com a saúde dos indivíduos e famílias em diferentes cenários; formação de médicos e enfermeiros em saúde familiar e comunitária; bioética para o cuidado a saúde; referenciais teóricos/práticos e de pesquisa para avaliação da saúde da família. Atenção à saúde das famílias latino-americanas: abordagens teóricas e práticas na educação é fruto da união de experiências de profissionais da saúde, cujo movimento levou à criação da Rede Latino-americana de Enfermagem de Família liderada pela Universidade Federal de Pelotas do Brasil, Universidade de La República, do Uruguai e a Fundação Growing Up, da Colômbia. Essa rede reúne mais de 130 profissionais com o propósito de promover avanços na área de enfermagem de família, dar visibilidade e difundir conhecimentos teóricos, práticos e de pesquisa voltado à saúde das famílias.', '["family health","health education","family nursing","family and community health","health promotion","health care practices","family health assessment","medical and nursing education"]', '10.7476/9786550190569', '9786550190569', 'https://books.scielo.org/id/hymj4', 'https://books.scielo.org/id/hymj4/pdf/lopez-9786550190569.pdf', NULL, 'https://books.scielo.org/id/hymj4/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hyrdy', 'hyrdy', 'Diálogo interreligioso: el problema de su base común', 'el problema de su base común', '["Carlos Miguel Gómez Rincón"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '“El diálogo entre religiones es una de las tareas más urgentes y necesarias en el mundo contemporáneo, tanto para la búsqueda de la paz mundial como para la construcción de sociedades plurales. Pero esto no significa que sea una tarea fácil, ni mucho menos que sepamos cómo pueda llevarse a cabo. Dado que las diferentes tradiciones religiosas suelen realizar afirmaciones universales, que se contradicen entre sí, sobre la realidad suprema y el destino y sentido de la vida humana, además de que cada una lo hace de acuerdo con sus propios sistemas de argumentación y en concordancia con una visión de mundo que difiere de las demás, es necesario encontrar ciertos puntos comunes a partir de los cuales comunicarse. Este libro es una investigación filosófica sobre el problema de las condiciones de posibilidad para el diálogo entre religiones. Estudia algunas de las principales posturas que al respecto han surgido en la filosofía de la religión contemporánea y a partir de ellas intenta aclarar lo que significa una base común apropiada para el diálogo: una serie de principios comunicativos que, sin pertenecer de suyo a ninguna tradición particular, permitan evaluar, discernir y decidir entre las posturas presentadas en un encuentro comunicativo entre miembros de tradiciones heterogéneas.”', '["interreligious dialogue","common ground","conditions of possibility","communicative principle","religious pluralism","world peace","contemporary philosophy of religion","meaning of life"]', '10.7476/9789585005310', '9789588378183', 'https://books.scielo.org/id/hyrdy', 'https://books.scielo.org/id/hyrdy/pdf/gomez-9789585005310.pdf', NULL, 'https://books.scielo.org/id/hyrdy/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hyvcn', 'hyvcn', 'Irê Ayó: uma epistemologia afro-brasileira', NULL, '["Vanda Machado"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A partir da educação e do estudo da cultura brasileira, Vanda Machado reencontra as raízes de sua identidade negra e revela nesse livro suas vivências com as crianças do axé. Conforme traduz o título, a obra destaca a lógica diaspórica, afro-brasileira, em contraposição à epistemologia colonizadora. Afinal, ela articula essa concepção de conhecimento com as políticas educacionais relativa à Lei nº 10.639/2003, que trata da obrigatoriedade de inclusão da cultura afro-brasileira nos currículos escolares, com a noção de cosmovisão, dos fenômenos do Aiyê e do Orun como fundamento ancestral. A autora, na prática com as crianças, partindo do princípio de que a educação é uma organização viva, demonstra implicações importantes do sujeito na sua condição de pertença. Contudo, por que a escola se mantém ainda rotineira, mantendo a epistemologia dominante? É a partir desse questionamento que antes de 1985 o livro se mostra como uma epistemologia a afro-brasileira iniciada na Escola Joana D’Arc no subúrbio Ferroviário de Paripe.', '["axe","Afro-Brazilian culture","Black identity","Law 10.639/2003","cosmovision","colonial epistemology","children''s education"]', '10.7476/9786556302034', '9788523218997', 'https://books.scielo.org/id/hyvcn', NULL, NULL, 'https://books.scielo.org/id/hyvcn/cover/cover_thumbnail.jpeg', 153, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hz6s2', 'hz6s2', 'Pé preto no barro branco: a língua dos negros da Tabatinga', NULL, '["Sônia Maria De Melo Queiroz"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A MÃE PRETA CONTA "CASOS ENGRAÇADOS" AOS MENINOS DO BRASIL PAPO DE ENGRAXATEMeu primeiro contato com a Língua do Negro da Costa se deu ainda na minha infância.Eu vivia em Bom Despacho, onde, como em toda pequena cidade do interior de Minas, tudo gira em torno da igreja matriz.À volta da igreja, os casais passeiam, os políticos conchavam, as crianças brincam, passam os enterros e as procissões, as comadres (e os compadres) comentam.Enfim, tudo acontece e de tudo se toma conhecimento na praça da matriz.Nessa praça, em Bom Despacho, em frente à porta principal da igreja, havia sempre alguns engraxates que, enquanto lustravam sapatos, conversavam numa língua ininteligível para os não-iniciados e que diziam de origem africana.Eram meninos pobres vindos da Tabatinga ou da Cruz do Monte -ruas da periferia da cidade cujos habitantes sempre foram tidos por marginais.De tanto passar por ali, a gente do centro da cidade acabava por aprender alguma coisa.Viriango ''soldado'' e ingura ''dinheiro'', significativamente, são as duas palavras que me ficaram na memória, daquela época.Lembro-me ainda de uma curiosidade relacionada com o caráter de código secreto atribuído à língua por seus falantes.O tio de um amigo meu, passando férias na cidade, interessou-se pela língua dos engraxates e lhes propôs a compra do seu "dicionário".', '["Afro-Brazilian languages","Tabatinga","code-switching","code language","language contact"]', '10.7476/9788542303056', '9788542303056', 'https://books.scielo.org/id/hz6s2', 'https://books.scielo.org/id/hz6s2/pdf/queiroz-9788542303056.pdf', NULL, 'https://books.scielo.org/id/hz6s2/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hz7bt', 'hz7bt', 'O fetiche como estrutura, imagem e performance no Teatro de Nelson Rodrigues', NULL, '["Isadora Grevan de Carvalho"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O teatro de Nelson Rodrigues, por sua complexidade e gama de contradições, constitui um terreno fértil para o estudo da exploração de performance, do corpo e da imagem como um lugar de conhecimento, especialmente em suas dimensões fetichistas. Este livro tem como proposta analisar as criações do dramaturgo, investigando a estrutura, a imagem e a performance do fetiche e de que maneira se apresentam em todas as suas peças. Com esse intuito, a autora examina oito roteiros do autor, entre eles, Os sete gatinhos, Toda nudez será castigada, O beijo no asfalto e Boca de ouro. A perspectiva de fetiche em Rodrigues, apresentada no livro, dialoga diretamente com a análise estrutural de Roberto DaMatta, além de ser enriquecida por interpretações psicanalíticas e marxistas e por outras fundamentações teóricas. A leitura possibilita perceber como o recurso do fetiche inclui Nelson Rodrigues em uma linhagem de autores como Machado de Assis, Lima Barreto e Clarice Lispector, que desconstruíram discursos de gênero e raciais sobre a imaginada identidade brasileira.', '["Nelson Rodrigues","fetishism","Brazilian drama","performance","body","images","Roberto DaMatta","psychoanalysis","Marxism","gender","race","Brazilian national identity"]', '10.7476/9786587949475', '9786587949444', 'https://books.scielo.org/id/hz7bt', NULL, NULL, 'https://books.scielo.org/id/hz7bt/cover/cover_thumbnail.jpeg', 250, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-hzj5q', 'hzj5q', 'Produção de identidades e processos de subjetivação em práticas discursivas', NULL, '["Ismara Eliane Vidal de Souza Tasso","Pedro Navarro"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'CORPOREIDADE MEDIADA E SUBJETIVAÇÃO Poliana Lachi 4 , Pedro Navarro 5Não é de hoje que a ciência busca compreender a origem do homem, os seus modos de agir e a sua relação em sociedade.Se na Antiguidade esse processo se dava por meio da religião, do misticismo crente em magias e atos sobrenaturais, com o surgimento da ciência moderna, de base empírica, os saberes ganharam um novo peso de verdade e passaram para um novo estatuto, embora não tenham deixado de estar ligados à elite.Foucault faz dessa questão a sua maior inquietação.O desvendamento do sujeito moderno não ocorre apenas em As palavras e as coisas, mas é um pensamento que transpassa toda a sua obra, inclusive aquelas que tematizam o poder, o saber e a ética.Considerando essa busca por um sentido do homem atual e tomando-a como aspecto investigativo, este artigo propõe lançar um breve olhar sobre o discurso a respeito do corpo e suas formas de subjetivação.Para isso, em um primeiro momento realizará uma articulação teórica entre diferentes noções que,', '["identity construction","subjectivation","discursive practices","body discourse","Michel Foucault","modern subject","power and knowledge"]', '10.7476/9788576285830', '9788576285830', 'https://books.scielo.org/id/hzj5q', 'https://books.scielo.org/id/hzj5q/pdf/tasso-9788576285830.pdf', NULL, 'https://books.scielo.org/id/hzj5q/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j26g5', 'j26g5', 'História da raiva no Brasil', NULL, '["Marilene Fernandes de Almeida","Luzia Helena Queiroz"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A raiva é um capítulo fascinante na história da ciência e da medicina e é uma doença que acompanha a humanidade desde a Antiguidade. Neste livro, as autoras relatam a história da raiva no Brasil e, durante esse estudo, muitas dúvidas surgiram e as guiaram durante a pesquisa. Os indígenas brasileiros já conheciam a raiva? Como essa doença era vista e tratada nessas culturas? Qual a importância dessa infecção e como era tratada no período colonial e imperial brasileiro? Quais animais estavam envolvidos no ciclo epidemiológico? Os morcegos já eram reservatórios do vírus da raiva quando os europeus chegaram ao Brasil ou a doença foi introduzida pela colonização? Algumas respostas a essas questões foram obtidas em relatos de naturalistas durante viagens por terras brasileiras, revistas médicas, jornais, leis e outras publicações da época em que a doença ainda era chamada de hidrofobia. Nesta obra também são reproduzidas as descrições de receitas milagrosas e os procedimentos curiosos que prometiam a cura da infecção. Este livro dedica especial atenção à história dos Institutos Pasteur no Brasil, das instituições de pesquisa e executoras das medidas de controle da raiva país. Além disso, apresenta a ocorrência e a evolução do conhecimento sobre a doença no mundo e no Brasil ao longo dos séculos e descreve sua situação atual.', '["rabies","colonial Brazil","Brazilian Empire","epidemiological cycle","bats as reservoir","traditional remedies","rabies control","history of medicine"]', '10.7476/9786557144510', '9786557144510', 'https://books.scielo.org/id/j26g5', 'https://books.scielo.org/id/j26g5/pdf/almeida-9786557144510.pdf', NULL, 'https://books.scielo.org/id/j26g5/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j3jbg', 'j3jbg', 'Estudos territoriais no Brasil e na Costa Rica', NULL, '["Glaúcio José Marafon","Lilliam Quirós-Arias","Meylin Alvarado Sánchez"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'EdUERJ, 2018.336 p.A universidade, aliás, é, talvez, a única instituição que pode sobreviver apenas se aceitar críticas, de dentro dela própria, de uma ou outra forma.Se a universidade pede aos seus participantes que calem, ela está se condenando ao silêncio, isto é, à morte, pois seu destino é falar.A fidelidade reclamada não pode ser à universidade, e a ela não temos razão para ser fiéis.Nossa única fidelidade é com a ideia de universidade.E é a partir da ideia sempre renovada de universidade que julgamos as universidades concretas e sugerimos mudanças.Milton Santos, 1997 Apresentação O presente livro é fruto da cooperação entre o Instituto de Geografia/ PPGEO da Universidade do Estado do Rio de Janeiro (UERJ) e da escola de Ciências Geográficas da Universidade Nacional da Costa Rica (UNA).Essa parceria teve início em 2011, e nesses anos tivemos uma profícua colaboração por meio de visitas técnicas, participação em eventos, publicações em periódicos, além do ingresso de alunos da Costa Rica no Programa de Pós-Graduação em Geografia, para a realização de mestrado e doutorado.Destarte, dando continuidade a essa profícua cooperação, estamos apresentando à comunidade geográfica o presente livro denominado Estudos territoriais no Brasil e na Costa Rica, que contém artigos de profissionais das duas universidades -UERJ e UNA -, com resultados de investigações e que revelam um pouco das pesquisas que estão sendo efetuadas nessas instituições.O livro está estruturado em duas partes, com artigos do Brasil e da Costa Rica.Optamos por deixar os textos, na língua original de cada autor para que possamos nos aproximar cada vez mais e realizar mais trabalhos de forma conjunta, buscando uma maior integração entre nossos países, não sendo a língua um obtáculo.Na primeira parte, "Estudos territoriais no Brasil", os autores Monica Sampaio Machado e Thiago Adriano Machado, no capítulo "Considerações sobre as categorias analíticas do espaço geográfico em Milton Santos", apresentam a trajetória desse intelectual, que pode ser compreendida a partir de dois projetos por ele desenvolvidos: o primeiro era de produzir uma teoria geográfica.Os autores objetivam discutir alguns aspectos da sua teoria geográfica, destacando as categorias analíticas do espaço por ele desenvolvidas.É, então, tecida uma breve periodização da trajetória de Milton Santos, que distingue três principais momentos, por meio dos quais efetiva a sua produção teórica a partir de aproximações sucessivas da relação entre o espaço geográfico e o fenômeno técnico.Isso ocorre, porém, com uma renovada crítica à tradição geográfica, inclusive àquela em que o autor situa seus primeiros trabalhos.Machado e Machado identificam uma primeira fase entre 1948 e 1960, caracterizada pelos seus estudos sobre a Bahia, nos quais predominava a geografia regional de matriz lablachiana, sucedida pelo período do exílio entre 1965 e 1987, em que El capítulo "Esbozo con perspectiva geográfica de los estudios sobre la ciudad, el espacio y las cuestiones urbano-regionales en América Latina", presentado por el Dr. Omar Arrieta Chavarría; presenta un esbozo de las publicaciones realizadas en América Latina, de los estudios relacionados con la ciudad y las cuestiones urbanas; el urbanismo y la planificación; y la cuestión urbana regional y el ordenamiento del territorio.Esto con el objetivo de comprender las experiencias logradas en esta materia, aprender de ellas, y reorientar y fortalecer la producción científica sobre estos temas particularmente en Centroamérica.Para estudiar este tema, se identificó algunas instituciones que se destacan por su trayectoria en el campo de la investigación científica y técnica en la temática, se incluyen algunos centros académicos que se ocupan de estos problemas con el fin de sintetizar las principales líneas de trabajo; en el caso brasileño, dado la magnitud de los estudios relacionados se tomó una muestra significativa de universidades, departamentos e institutos brasileños que se dedican al análisis científico y técnico de estos temas.Se realiza además una revisión crítica, detenida de los artículos y textos de la extensa producción que desde diversas disciplinas se ha producido, y que son las líneas fundamentales de trabajo en América Latina.En la exposición, el texto se dividió en tres acápites, el primero hace un repaso de aportes teórico metodológicos sobre la ciudad y el espacio urbano regional vistos desde la geografía; la segunda es una revisión de las cuestiones urbano-regionales y una síntesis de los temas recientes en el ámbito de la geografía con enfoques posmodernos y socio críticos; la tercera es una reflexión de los aportes y posibilidades futuras en las investigaciones de este tipo con miras a enfrentar los retos que se tienen en el campo de las ciencias sociales vinculadas al análisis del espacio geográfico, la ciudad y la cuestión regional, asuntos que interesa profundizar en el caso centroamericano.Rio de Janeiro e Heredia, outono-primavera de 2018.Parte I -Estudos territoriais no Brasil 2. O setor sucroenergético no Brasil: efeitos e contradições Patrícia Francisca de Matos Gláucio José Marafon IntroduçãoO Brasil tornou-se, há quase duas décadas, um importante produtor e consumidor de biocombustíveis como alternativa energética, com destaque para o etanol produzido a partir da cana-de-açúcar.A necessidade de substituição dos combustíveis fósseis por "combustíveis mais limpos" conferiu uma posição de destaque ao etanol brasileiro.Com o mercado promissor, o Brasil tem visto um crescimento das monoculturas de cana-de-açúcar para abastecer o setor sucroenergético para produção de açúcar, álcool anidro (aditivo para gasolina), álcool hidratado e cogeração de energia (produzida pelo bagaço da cana).No início do século XXI, ocorreu uma expansão acelerada da cultura da cana no território brasileiro devido ao projeto dos biocombustíveis, que a colocou como a principal opção na produção de álcool, criando novas paisagens, novas formas de produção, e modificando os usos do território, especialmente de oito estados brasileiros.Para aprofundar a análise, tomaremos como exemplo o avanço do setor sucroenergético no', '["territorial studies","Milton Santos","geographic space","comparative geography"]', '10.7476/9788575114995', '9788575114995', 'https://books.scielo.org/id/j3jbg', 'https://books.scielo.org/id/j3jbg/pdf/marafon-9788575114995.pdf', NULL, 'https://books.scielo.org/id/j3jbg/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j3wfb', 'j3wfb', 'Educação para cuidar e saúde mental para aprender: ações e reflexões no momento presente', 'ações e reflexões no momento presente', '["Karla Rosane do Amaral Demoly","Maria Aridenise Macena Fontenelle"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro se organiza como um conjunto de reflexões sobre a experiência que mobiliza cientistas, educadores, artistas, estudantes e profissionais em trabalhos que discutem como acontece a promoção da saúde mental e da educação inclusiva. Os autores integram múltiplas formas de agir na linguagem e constroem métodos para potencializar modos de aprender e de cuidar nestes tempos de graves ataques à vida e à sua conservação, devido à pandemia Covid 19 e aos diversos cenários nos quais preponderam relações competitivas que se sustentam na negação do outro como legítimo outro na convivência. Os autores e autoras integram redes de pesquisa que tecem trabalhos que funcionam como convites à experiência da colaboração, da partilha, da alegria e da amorosidade. São escritas do âmbito da saúde mental e da educação que trazem possibilidades de ampliar e fortalecer a tessitura de redes de cuidado, alegria e aprendizagem no percurso do viver-conhecer.', '["mental health promotion","inclusive education","care","learning","COVID-19 pandemic","care networks","collaboration","joy","intercultural relations","living knowledge"]', '10.7476/9788557571563', '9786587108827', 'https://books.scielo.org/id/j3wfb', 'https://books.scielo.org/id/j3wfb/pdf/demoly-9788557571563.pdf', NULL, 'https://books.scielo.org/id/j3wfb/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j42t3', 'j42t3', 'A depressão como "mal-estar" contemporâneo medicalização e (ex)-sistência do sujeito depressivo', NULL, '["Leandro Anselmo Todesqui Tavares"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'medicalização e (ex)-sistência do sujeito depressivo / Leandro Anselmo Todesqui Tavares.', '["depression","medicalization","contemporary malaise","subjectivity","psychoanalysis"]', '10.7476/9788579831003', '9788579831003', 'https://books.scielo.org/id/j42t3', 'https://books.scielo.org/id/j42t3/pdf/tavares-9788579831003.pdf', NULL, 'https://books.scielo.org/id/j42t3/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j49y6', 'j49y6', 'Poéticas da paisagem: desvelamento e transcriação nos desvãos das cidades', 'desvelamento e transcriação nos desvãos das cidades', '["Arthur Simões Caetano Cabral"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A ideia de paisagem pode remeter à interação entre o ser humano e a natureza da Terra, associada à emergência de um inumano, que encontraria na imaginação poética sua fonte de expressão. Nesse sentido, a paisagem, por um lado, não teria lugar nas grandes cidades, senão em áreas excepcionalmente reservadas a ela e sob formas domesticadas da natureza. Por outro lado, caberia interrogar sua ocorrência em espaços residuais ou desfuncionalizados, que escapam às intenções de controle e amansamento. Para detectar indícios originários do natural que perfaz as cidades, este livro investiga oportunidades de fruição da paisagem em interstícios urbanos e explora maneiras de expressar essa experiência, assumindo a impossibilidade de sua reconstrução integral ou de sua representação mimética. O olhar se dirige a desvãos da cidade de São Paulo, para identificar insinuações das matérias que se ocultam. Para tanto, são cotejados diferentes meios de expressão alusivos aos horizontes inconclusos da paisagem e àquilo que, para além da racionalidade estrita, mobiliza imagens poéticas.', '["landscape poetics","urban landscape","urban interstices","São Paulo","poetic imagination","human-nature interaction","urban periphery","landscape representation"]', '10.7476/9786557145562', '9786557145562', 'https://books.scielo.org/id/j49y6', 'https://books.scielo.org/id/j49y6/pdf/cabral-9786557145562.pdf', NULL, 'https://books.scielo.org/id/j49y6/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j4gkh', 'j4gkh', 'Gestão, mediação e uso da informação', NULL, '["Marta Lígia Pomim Valentim"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro Gestão, mediação e uso da informação vai ao encontro dos estudos teóricos e metodológicos de objetos e fenômenos que envolvem a gestão, a mediação, uso e apropriação da informação em distintos ambientes', '["information management","information mediation","information use","information appropriation","information environment"]', '10.7476/9788579831171', '9788579831171', 'https://books.scielo.org/id/j4gkh', 'https://books.scielo.org/id/j4gkh/pdf/valentim-9788579831171.pdf', NULL, 'https://books.scielo.org/id/j4gkh/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j4jfj', 'j4jfj', 'Sobre educação, política e sindicalismo', NULL, '["Maurício Tragtenberg"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Após 30 anos da primeira publicação desta coletânea, o autor surpreende pela atualidade do pensamento e análises elaboradas no final dos anos 70. Com diversos artigos, depoimentos e um debate com o autor, é abordada a relação entre saber e poder, escola e burocracia, escola e domesticação e a existência da "delinqüência acadêmica". Traz, novamente, a proposta corajosa e viva de que a história construirá a escola popular e de acesso ao povo e apresenta debate que expõe o que significam os vestibulares à universidade, concluindo que "é lamentável que loucos dirijam cegos".', '["education and politics","labor movement","power and knowledge","popular education","higher education access","college entrance examination","Paulo Freire"]', '10.7476/9788539303427', '9788571395510', 'https://books.scielo.org/id/j4jfj', NULL, NULL, 'https://books.scielo.org/id/j4jfj/cover/cover_thumbnail.jpeg', 216, 27, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publication