INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j523t', 'j523t', 'Ensaios sobre desenvolvimento econômico e políticas públicas: um olhar sobre a Bahia e o Brasil', NULL, '["Mônica de Moura Pires","Andréa da Silva Gomes"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2022, '2022-09-26', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'O livro propicia ao leitor um conjunto de artigos sobre desenvolvimento e políticas públicas, apresentando distintas nuanças e aspectos, dos mais gerais aos mais específicos. Esses trabalhos foram desenvolvidos no âmbito do Programa de Pós-Graduação em Economia Regional e Políticas Públicas e visam auxiliar no debate e na construção de um processo de desenvolvimento local que beneficie a sociedade.', '["economic development","public policy","regional economics","local development","Bahia","Brazil"]', '10.7476/9786586213829', '9786586213805', 'https://books.scielo.org/id/j523t', NULL, NULL, 'https://books.scielo.org/id/j523t/cover/cover_thumbnail.jpeg', 211, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j56gd', 'j56gd', 'A família real no Brasil: política e cotidiano (1808-1821)', NULL, '["Juliana Gesuelli Meirelles"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A vinda da Corte portuguesa para o Brasil aconteceu em meio a uma conjuntura política europeia muito delicada: as guerras napoleônicas que assolavam a paz no Velho Mundo (1805)(1806)(1807)(1808)(1809)(1810)(1811)(1812)(1813)(1814)(1815).Nesse período, Napoleão não apenas destituiu dinastias e refez o mapa da Europa, como também insuflou um povo inteiro com a mística da nação.Já nos territórios conquistados, implantou uma série de valores da Revolução Francesa, cuja contribuição foi decisiva para o nascimento da política no sentido moderno.O Bloqueio Continental decretado por Bonaparte, em novembro de 1806, tinha como meta o enfraquecimento da economia inglesa, um obstáculo fundamental aos objetivos expansionistas da França.O bloqueio exigia -sob ameaça de invasão militar -que todos os países da Europa se fechassem ao comércio britânico a fim de que a economia inglesa entrasse em colapso.Se o Acordo de Tilsit, firmado com o Czar Alexandre I da Rússia em julho de 1807, garantia a Napoleão o encerramento do extremo leste da Europa, era mister a conquista a oeste, que circunscrevia os portos das cidades de Lisboa e do Porto.Portugal, porém, encontrava-se em uma situação deveras complexa.Se, por um lado, em setembro de 1807, dom João acatava as ordens de Napoleão, fechando os portos aos navios ingleses -o que consolidava a ruptura com a Inglaterra -, por outra via, postergava na prática tal atitude, uma vez que mantinha com a Inglaterra uma relação de grande dependência econômica, que o impedia de acatar integralmente as ordens francesas.A forte aliança com os ingleses colocava a situação do país em xeque.Portanto, fez-se urgente uma tomada de posição, sobretudo depois do ultimato de Napoleão que, em outubro de 1807, ordenava a invasão francesa em território luso.À "medida que os rumores [da invasão] cresciam, ao longo de novembro de 1807, o governo português buscou entabular negociações com a Inglaterra, através de uma convenção secreta, em que se previa a transferência da Família Real para o Brasil, protegida pela esquadra britânica, em troca da ocupação da Ilha da Madeira, enquanto perdurassem as operações militares no continente", contextualiza a historiadora Lúcia Neves (2008: 56).Foi diante dessa crise geopolítica do continente europeu que a Dinastia de Bragança -com D. Maria I, o Príncipe Regente dom João e grande parte da Corte portuguesa -, embarcou para o Brasil, em 29 de novembro de 1807.No dia seguinte, as tropas francesas, sob a liderança de Junot, entravam em território português.Pouco mais de três meses depois, a realeza pisava em solo fluminense. I.A chegada da família real e as mudanças sociopolíticas No dia 14 de janeiro de 1808, o brigue Voador trazia ao porto do Rio de Janeiro a notícia de que a Família Real estava a caminho do Brasil.Desde então, os ânimos da sociedade carioca fervilhavam.Três dias depois, em 17 de janeiro, o desembarque das sete naus portuguesas e dos três barcos ingleses no cais do porto despertava a imensa curiosidade da população que aguardava ansiosamente a chegada do Príncipe Regente e sua corte em terras americanas.Para desapontamento da maioria da casta real, entretanto, chegavam apenas as duas irmãs da rainha D. Maria I: d.Maria Benedita e D. Maria Ana, além das duas infantas, Maria Francisca de Assis e Isabel Maria.Sem saber o que havia acontecido com os demais membros da dinastia de Bragança, as nobres senhoras e senhoritas da família real não aceitaram o convite do conde dos Arcos para aportarem em terra firme.Preferiram ficar a bordo dos navios à espera de notícias, que só chegariam ao Rio um mês depois.Enquanto isso, os demais tripulantes circulavam pela cidade em busca de acomodação.Esse momento, ainda tão singelo perto do que viria a ser o dia 7 de março, já prenunciava as importantes transformações que ocorreriam na sociedade luso-brasileira.Novas etiquetas, rituais e solenidades começavam a ser vivenciados pelas ruas da sede da Colônia que, em 22 de fevereiro, ficava ciente de que a Família Real -juntamente com a nobre comitiva portuguesa -encontrava-se em Salvador e, tão logo fosse possível, estariam no Rio de Janeiro.A tônica das conversas girava em torno da chegada em carne e osso da Rainha, do Príncipe Regente, seus familiares e acompanhantes.Todos se preparavam para a pompa que enfeitaria a grande ocasião... * Enfim, em 7 de março, a esquadra real aportava no porto da baía de Guanabara.A cidade estava em festa e o espetáculo da chegada foi um momento único: as salvas de canhões, os tiros de fuzis e as badaladas dos sinos das igrejas anunciavam a entrada triunfal da família real que recebia as homenagens por toda a parte.D. Maria, dom João e Carlota Joaquina foram recepcionados pela elite política da cidade, composta, sobretudo, pelo Conde dos Arcos, os membros do Senado da Câmara, além de renomados eclesiásticos, civis e militares.Com olhares curiosos, o restante da população se amontoava pelas praias e morros assistindo atentamente ao entourage, que ganharia contornos mais efusivos no dia seguinte.Em suas memórias, Reforçava-se nele a autoridade paternal do soberano protetor da nação", relata Jurandir Malerba (2000: 184).Finda a recepção, a realeza seguia em coches próprios para o Palácio, sempre acompanhados da multidão curiosa para saber o que aconteceria dali em diante.Se a beleza do cenário geográfico da cidade encantava a maioria da corte portuguesa que desembarcava no porto do Rio, os primeiros dias mostrariam a precariedade da estrutura da nova capital."Numa pequena área espremida entre a praia e a montanha, formada por escassas ruas paralelas e mais algumas transversais, rodeadas por matas e logradouros desertos, mais de dez mil pessoas foram alojadas às pressas, com a chegada da Família Real, transformando a pequena cidade dos vice-reis em capital do império português na América", descreve a historiadora Leila Mezan Algranti (1988: 26).Para acomodar os acompanhantes da corte, o conde dos Arcos instituiu o sistema de aposentadorias que, na prática, requisitava as casas dos moradores locais para aconchego da nobreza.Na porta de muitas casas foram pregadas as letras PR -Príncipe Regente -, interpretadas pela população como Ponha-se na Rua."O afluxo de uma grande quantidade de pessoas agravou os problemas urbanos.Além da falta de moradia, havia carência no abastecimento de água, saneamento, segurança pública", descreve o historiador Paulo de Assunção (2008: 88).Essa situação causou um enorme rebuliço tanto para a população que ficava desabrigada, quanto para a nobreza portuguesa que considerava as moradias desconfortáveis, mal construídas e sem o luxo das suas residências em Lisboa.Já a população mais pobre ficou marginalizada à região norte da cidade, circunscritas aos bairros de Catumbi e Mata-Porcos.Nesse espaço, as habitações se restringiam a choças aglomeradas entre os morros e o mar, o que já marcava a profunda desigualdade social no especo geográfico (Lima, 2000: 106).Aos poucos, no entanto, as transformações urbanas foram modificando a estrutura da cidade.Para além das quatro freguesias já existentes -Sé, Santa Rita, São José e Candelária -, foi criada o Engenho Velho.Novas ruas foram pavimentas e as estradas alargadas.A iluminação, saneamento, abastecimento de água potável e, consequentemente, a higiene também foram aspectos que sofreram importantes melhorias na cidade.Ou seja, entre os anos de 1808 e 1822, a área do Rio de Janeiro havia triplicado.Mas como bem adverte a antropóloga Lilia Schwarcz, "Se a vila se modificou para se vestir como capital do império português, as permanências são evidentes.Suas casas e traçados coloniais, suas festas tomadas por costumes africanos, seus hábitos alimentares orientais... nada permite duvidar de um universo obrigatoriamente plural" (', '["Portuguese court in Brazil","royal family","Portuguese monarchy","Napoleonic Wars","Continental Blockade","Treaty of Tilsit","Portuguese-English relations","Portuguese Revolution of 1820","everyday life","Rio de Janeiro"]', '10.7476/9788568576960', '9788568576960', 'https://books.scielo.org/id/j56gd', 'https://books.scielo.org/id/j56gd/pdf/meirelles-9788568576960.pdf', NULL, 'https://books.scielo.org/id/j56gd/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
