s.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j5fcv', 'j5fcv', 'Geografias do drama humano: leituras do espaço em São Bernardo, de Graciliano Ramos, e Pedro Páramo, de Juan Rulfo', NULL, '["Gracielle Marques"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro analisa o processo de construção do espaço que permeia os romances São Bernardo (1934), do escritor brasileiro Graciliano Ramos (1892-1953), e Pedro Páramo (1955), escrito pelo mexicano Juan Rulfo (1918-1986), explicitando as analogias e os contrastes entre as duas obras, a partir da percepção de que ambas projetam, no processo de construção do espaço, lugares que revelam conflitos sociais, psicológicos e existenciais do homem em confronto com sua origem e seu destino. Com esse pressuposto, o livro investiga a relação íntima e direta do espaço com as personagens, as conseqüências da particularização do espaço pela violência, as paisagens que refletem a solidão, a incomunicabilidade e o desamor presentes no universo poético de ambos os romances desses dois grandes expoentes da literatura latino-americana. O livro demonstra que ambas as obras retratam a complexidade das sociedades da América Latina, simbolizadas num espaço rural emblemático que expressa, em perspectiva poética e sem caráter documental, diversas facetas da realidade.', '["Graciliano Ramos","São Bernardo","Juan Rulfo","Pedro Páramo","spatial representation","construction of space","violence","landscape","solitude","incomunicability","rural space","Latin American literature"]', '10.7476/9788579831317', '9788579831317', 'https://books.scielo.org/id/j5fcv', 'https://books.scielo.org/id/j5fcv/pdf/marques-9788579831317.pdf', NULL, 'https://books.scielo.org/id/j5fcv/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j5nsj', 'j5nsj', 'La gestión ambiental urbana en la localidad de La Candelaria', NULL, '["Alejandra Sáenz Quitian","Andrés Gómez-Rey","Gloria Amparo Rodríguez"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Si bien es cierto la eficacia de la gestión ambiental en La Candelaria ha mejorado considerablemente gracias al aumento del presupuesto de inversión en temas ambientales y a la implementación de programas mediante los cuales se ha logrado manejar la problemática existente, la realidad nos demuestra que muchos de estos problemas ambientales urbanos siguen afectando notablemente a los habitantes de la localidad y a la población flotante que realiza sus actividades cotidianas al interior de la misma. Por esta razón, la Línea de Investigación en Derecho Ambiental de la Universidad del Rosario, buscando incidir en la localidad donde se encuentra su sede principal, desarrolló este proyecto de investigación que estudia la problemática ambiental que afecta a La Candelaria, sus causas y consecuencias, así como las diferentes medidas que han adoptado las autoridades para solucionarlos, a fin de impulsar la generación de conocimientos y el fortalecimiento de las capacidades institucionales para responder a las necesidades ambientales. El objetivo de esta obra es avanzar en el conocimiento de los problemas ambientales de la localidad, para aportar desde los pilares básicos de la gestión ambiental urbana a la generación de posibles soluciones que permitan alcanzar la sostenibilidad y la garantía del derecho de todos los ciudadanos a gozar de un ambiente sano.', '["urban environmental management","La Candelaria","environmental problems","environmental investment","institutional capacity building","environmental sustainability","right to a healthy environment","environmental authorities","floating population"]', '10.7476/9789587385687', '9789587385670', 'https://books.scielo.org/id/j5nsj', NULL, NULL, 'https://books.scielo.org/id/j5nsj/cover/cover_thumbnail.jpeg', 210, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j6jgd', 'j6jgd', 'Identidade e resistência afro-brasileira na obra de Jorge Amado', NULL, '["Aline Santos de Brito Nascimento"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A identidade afro-brasileira é tomada como mote para reler os romances Jubiabá, Gabriela, cravo e canela e Tenda dos milagres, buscando caracterizar os traços de tradição, tradução, hibridismo e resistência neste estudo, que se justifica por analisar as características do grupo étnico afro-brasileiro como vetores para despertar no cidadão o reconhecimento do valor das minorias étnicas. As análises conduzem à conclusão de que o respeito às identidades culturais diversas deve ser propagado através da divulgação da literatura.', '["Afro-Brazilian identity","Jorge Amado","Gabriela, cravo e canela","Tenda dos Milagres","cultural resistance","cultural hybridity","ethnic minorities","cultural diversity"]', '10.7476/9786586213034', '9788574555324', 'https://books.scielo.org/id/j6jgd', NULL, NULL, 'https://books.scielo.org/id/j6jgd/cover/cover_thumbnail.jpeg', 303, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j6xy9', 'j6xy9', 'Cenas de parto e políticas do corpo', NULL, '["Rosamaria Carneiro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O Brasil é o recordista mundial de cesáreas. Aqui, de 52% a 88% dos partos são cirúrgicos na rede pública e na rede privada, respectivamente. Porém, não é só o alto número de cesarianas que chama a atenção, mas o que está por trás disso: as cesáreas são a escolha da maior parte das gestantes e dos profissionais que cuidam delas. Nesta obra, a autora - antropóloga e feminista - pesquisou um grupo que optou por parir diferentemente: da maneira mais natural possível. Ela conviveu, entre 2008 e 2010, na cidade de São Paulo, com cerca de 60 mulheres que já tinham dado à luz e, novamente grávidas, esperavam não repetir as experiências dolorosas anteriores. Rosamaria Carneiro esteve também com gestantes de “primeira viagem”, que queriam estudar possibilidades para decidir qual opção escolheriam. Sem aceitar imposições. “Poucos casos e muita densidade foram sempre meu objetivo. Porém, mais que isso, o conteúdo é fruto de uma pesquisa etnográfica, eminentemente qualitativa sobre saúde sexual e reprodutiva”, afirma ela.', '["cesarean section","childbirth","natural childbirth","body politics","reproductive health","sexual health","pregnant women","childbirth decision-making","feminist anthropology","São Paulo"]', '10.7476/9788575415146', '9788575414583', 'https://books.scielo.org/id/j6xy9', NULL, NULL, 'https://books.scielo.org/id/j6xy9/cover/cover_thumbnail.jpeg', 328, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j76hp', 'j76hp', 'Apropriação social da ciência e da tecnologia: contribuições para uma agenda', NULL, '["María Cristina Piumbato Innocentini Hayashi","Cidoval Morais de Sousa","Danilo Rothberg"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A ciência e a tecnologia na contemporaneidade condicionam a organização social e as formas existentes e emergentes de desigualdade e exclusão tanto em cada sociedade como entre sociedades e regiões do mundo. Os contextos de acesso e apropriação do conhecimento científico e tecnológico são diversificados, como diferenciados são os públicos que se constituem em relação com esses contextos e modos de acesso e de apropriação. Os textos desta coletânea problematizam sob diferentes aspectos as questões críticas para a compreensão e aplicação do conceito de apropriação social do conhecimento científico e tecnológico.', '["science and technology","access to knowledge","social inequality","social exclusion","science and society","global inequality"]', '10.7476/9788578791872', '9788578791872', 'https://books.scielo.org/id/j76hp', 'https://books.scielo.org/id/j76hp/pdf/hayashi-9788578791872.pdf', NULL, 'https://books.scielo.org/id/j76hp/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j8gtx', 'j8gtx', 'Políticas públicas &amp;amp desenvolvimento regional', NULL, '["Carlos Alberto Máximo Pimenta","Cecília Pescatore Alves"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea começou a ser organizada em meados e final do ano de 2006 e tem como propósito a busca de um olhar multidisciplinar sobre políticas públicas, levando-se em consideração o contexto regional e local, sem perder de horizonte as questões nacionais, latinas e mundiais. Tudo diante das tendências globais e suas conseqüências. (Trecho retirado da apresentação do livro)', '["public policy","regional development","local development","multidisciplinary perspectives","global trends"]', '10.7476/9788578791216', '9788578791216', 'https://books.scielo.org/id/j8gtx', 'https://books.scielo.org/id/j8gtx/pdf/pimenta-9788578791216.pdf', NULL, 'https://books.scielo.org/id/j8gtx/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j93sn', 'j93sn', 'Práticas teatrais: sobre presenças, treinamentos, dramaturgias e processos', NULL, '["Renato Ferracini","Raquel Scotti Hirson","Ana Cristina Colla"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro traz reflexões sobre os meandros invisíveis da atuação, da presença e do treinamento em processos criativos. Faz uma análise cuidadosa do tema da presença do artista cênico, articula experimentação e conceitos filosóficos, revela a delicadeza do trabalho do ator enquanto ofício e a potência da relação entre corpos possibilitada pela presença simultânea dos atores e dos espectadores. A busca poética por parte do artista traz potenciais desdobramentos para além da cena, na direção de uma vida aumentada em seu vigor e em sua intensidade de ação. São escritas poéticas permeadas por pensamentos. Pensamentos permeados por conceitos. Conceitos permeados por metáforas. Não há como ser de outro modo ao falar de criação e do suor dos corpos na construção da cena poética no teatro.', '["acting","theatrical presence","actor training","dramaturgy","creative process","performer-audience relationship","body","poetry writing"]', '10.7476/9786586253733', '9786586253559', 'https://books.scielo.org/id/j93sn', NULL, NULL, 'https://books.scielo.org/id/j93sn/cover/cover_thumbnail.jpeg', 360, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-j94p9', 'j94p9', 'Saúde mental e atenção psicossocial', NULL, '["Paulo Amarante"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O objetivo central do livro é contribuir para o entendimento das dimensões e estratégias do campo da saúde mental e atenção psicossocial, bem como para a análise dos caminhos e tendências das políticas brasileiras nessa área. Na publicação, o autor faz uma reflexão sobre o percurso que vai das bases da psiquiatria – e do manicômio – aos projetos atuais, que buscam construir um ‘novo lugar’ para as pessoas em sofrimento mental.', '["mental health","psychosocial care","mental health policy","psychiatric hospitals","history of psychiatry","mental illness"]', '10.7476/9788575413685', '9788575411353', 'https://books.scielo.org/id/j94p9', NULL, NULL, 'https://books.scielo.org/id/j94p9/cover/cover_thumbnail.jpeg', 120, 96, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jb7tc', 'jb7tc', 'Política Nacional de Aids: construção da resposta governamental à epidemia HIV/aids no Brasil', NULL, '["Sandra Garrido de Barros"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra se trata de uma análise sócio-histórica do combate ao HIV no Brasil. A autora narra a ação de diferentes agentes da luta contra o vírus, como médicos, políticos e movimentos sociais, reconstruindo a gênese de um “espaço aids brasileiro”. O resultado é um livro que é um marco para qualquer pessoa interessada na luta contra a aids, pela sociologia e pela política de saúde.', '["HIV/AIDS","health policy","social movements","physicians","politics"]', '10.7476/9788523220303', '9788523220303', 'https://books.scielo.org/id/jb7tc', 'https://books.scielo.org/id/jb7tc/pdf/barros-9788523220303.pdf', NULL, 'https://books.scielo.org/id/jb7tc/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jbcg3', 'jbcg3', 'Dança e diferença: cartografia de múltiplos corpos', NULL, '["Lúcia Helena Alfredi de Matos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro Dança e diferença: cartografia de múltiplos corpos ganha a sua segunda edição. Com uma apresentação cartográfica que esboça como novas territorializações estéticas vêm sendo tecidas na dança contemporânea, a obra aborda a análise de produtos coreográficos de grupos de dança que possuem em seu elenco dançarinos com os sem deficiência. Além da análise dos trabalhos dos grupos, o livro contém entrevistas com diretores, coreógrafos e elencos. Portanto, evidencia a existência de redes de relações estabelecidas na contemporaneidade através de conceitos chaves como o de corpo, dança contemporânea, diferença e deficiência.', '["contemporary dance","disability","difference","body","choreography","dance companies","choreographers","dance directors"]', '10.7476/9788523218164', NULL, 'https://books.scielo.org/id/jbcg3', 'https://books.scielo.org/id/cqndd/pdf/matos-9788523218164.pdf', NULL, 'https://books.scielo.org/id/jbcg3/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jbf9k', 'jbf9k', 'Eleições, opinião pública e comunicação pública no Brasil contemporâneo: homenagem a Marcus Figueiredo', NULL, '["Felipe De Moraes Borba","Alessandra Aldé"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"O livro reúne uma série de trabalhos de cientistas políticos sobre o tema opinião pública e seu impacto no comportamento político. Os autores compartilham o fato de todos terem sido influenciados pelo professor Marcus Figueiredo, um dos fundadores da moderna análise política do Brasil. A obra, organizada pelos professores e pesquisadores da Universidade do Estado do Rio de Janeiro (UERJ) Alessandra Aldé e Felipe Borba, é também uma homenagem ao professor Marcus Figueiredo e ao seu legado para a organização da subdisciplina Comunicação Política no âmbito da ciência política brasileira. A publicação integra a Coleção Sociedade e Política, editada pelo Instituto de Estudos Sociais da UERJ em parceria com a Eduerj. A coleção é dedicada aos temas cadentes da sociologia e da ciência política contemporânea.', '["public opinion","elections","political communication","political behavior","Brazilian political science"]', '10.7476/9788575114728', '9788575114353', 'https://books.scielo.org/id/jbf9k', NULL, NULL, 'https://books.scielo.org/id/jbf9k/cover/cover_thumbnail.jpeg', 538, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jbt6b', 'jbt6b', 'Brasília, metropolização e espaço vivido: práticas especiais e vida quotidiana na periferia goiana da metrópole', NULL, '["Igor Catalão"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'disponibilidade para fazer a leitura do texto final que tiveram Márcio José Catelan e Maria Angélica de O liveira Magrini.[...] the spatial dimension of our lives has never been of greater practical and political relevance than it is today.[...] we are becoming increasingly aware that we are, and always have been, intrinsically spatial beings, active participants in the social construction of our embracing spatialities.(Soja, 1996, p.1).', '["Brasília","metropolitanization","lived space","everyday life","peripheral neighborhoods","Goiânia","spatiality","social construction of space"]', '10.7476/9788579831058', '9788579831058', 'https://books.scielo.org/id/jbt6b', 'https://books.scielo.org/id/jbt6b/pdf/catalao-9788579831058.pdf', NULL, 'https://books.scielo.org/id/jbt6b/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jc8w4', 'jc8w4', 'Educação e contemporaneidade: pesquisas científicas e tecnológicas', NULL, '["Antônio Dias Nascimento","Tânia Maria Hetkowski"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A aplicação das tecnologias de informação e comunicação à educação (como o uso dos games como locus de aprendizagem e a midiatização do conhecimento na EAD), o reconhecimento da diversidade cultural, a valorização das trocas interculturais, a importância da ética e dos valores e da história oral de vida, a definição de políticas públicas e a atualidade do pensamento de Freinet, Vigotsky e Paulo Freire são alguns dos temas discutidos neste livro. Se seu tema central é a educação e os desafios que a contemporaneidade apresenta para a formação de profissionais da área, sua maior virtude é não desconhecer as densidades interpretativas que surgem com estas reflexões', '["educational technology","ICT in education","game-based learning","distance education","cultural diversity","cultural exchange","ethics in education","educational values","oral life history","education policy","Freinet pedagogy","Vygotsky"]', '10.7476/9788523208721', '9788523208721', 'https://books.scielo.org/id/jc8w4', 'https://books.scielo.org/id/jc8w4/pdf/nascimento-9788523208721.pdf', NULL, 'https://books.scielo.org/id/jc8w4/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jcgjz', 'jcgjz', 'A produção social do preconceito: subsídios para a formação de professores', NULL, '["Renata de Almeida Vieira"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro traz como temática central a compreensão da produção histórica do preconceito, tema que em nossa época tem sido objeto de atenções de diversos segmentos sociais e tem ganhado apelo popular. Nele, empreendemos uma análise que sai da mera aparência do fenômeno e buscamos divisar o seu enraizamento e discutimos aspectos teóricos referentes à produção social do preconceito.', '["prejudice","teacher professional development"]', '10.7476/9788576285885', '9788576284376', 'https://books.scielo.org/id/jcgjz', NULL, NULL, 'https://books.scielo.org/id/jcgjz/cover/cover_thumbnail.jpeg', 184, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jcgyd', 'jcgyd', 'Profissão historiadora em Santa Catarina: passados, presentes e futuros possíveis', 'passados, presentes e futuros possíveis', '["Fernando Cesar Sossai","Samira Peruchi Moretto"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Procurando dialogar com as (re)configurações do cenário profissional dos historiadores, este livro busca aprofundar debates a respeito da trajetória do ofício de historiador(a) em território catarinense, não se limitando à análise de acontecimentos passados. Dentro de suas possibilidades, a publicação visa constituir-se como uma importante referência para discussões sobre o presente e o futuro desta profissão, além de contribuir para o reconhecimento público da profissão historiadora no estado de Santa Catarina. Fruto de uma parceria colaborativa entre a diretoria e os grupos de trabalho (GTs) da ANPUH-SC, a obra reúne textos que discutem tanto aspectos da trajetória da formação do profissional de História em Santa Catarina como alguns dos principais desafios desta profissão. Com 14 capítulos distribuídos em três partes, seja pela complexidade das temáticas, seja pela diversidade das suas abordagens, o livro é uma referência fundamental para todos(as) que desejam discutir os passados, presentes e futuros possíveis da profissão historiadora no estado de Santa Catarina.', '["professionalization of historians","history education","history teacher education","Santa Catarina"]', '10.7476/9786550190958', '9786550190934', 'https://books.scielo.org/id/jcgyd', 'https://books.scielo.org/id/jcgyd/pdf/sossai-9786550190958.pdf', NULL, 'https://books.scielo.org/id/jcgyd/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jd2rr', 'jd2rr', 'Medios y opinión pública', NULL, '["Denis Porto Renó","Marcelo Martínez","Carolina Campalans"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'El concepto de opinión pública, surgido en el marco de la modernidad occidental y en el contexto del largo camino hacia la democratización del sistema político y de la sociedad, ha estado históricamente vinculado al estudio de los medios de comunicación. Dicha relación ha recibido diversos abordajes, que han oscilado entre la reflexión teórica y el empirismo, con algunas propuestas puntuales de integración entre ambas perspectivas. Los autores que participan en esta compilación se mueven entre ambos terrenos y consideran la relación que vincula opinión pública y medios desde una perspectiva plural de estos últimos; es decir, los textos presentados a continuación no restringen su ámbito de reflexión a los medios masivos. También se toman en consideración algunas manifestaciones locales de la opinión pública, incluso algunas vinculadas a expresiones culturales populares.Estos textos contribuyen a vincular los procesos de opinión pública con los debates más actuales sobre teoría de la comunicación, como por ejemplo aquellos que han vuelto a poner de relieve el concepto de narrativa, relacionándolo con la conversación pública y la producción de los medios de comunicación, sean o no de masas. La mayoría de los autores que participan en esta compilación forman parte de la Red Europa América Latina de Comunicación y Desarrollo (Real_Code), en la cual participan académicos de España y América Latina.', '["public opinion","mass media","democratization","communication theory","narrative","public dialogue","local public opinion","popular culture","media production"]', '10.7476/9789587385625', '9789587385618', 'https://books.scielo.org/id/jd2rr', NULL, NULL, 'https://books.scielo.org/id/jd2rr/cover/cover_thumbnail.jpeg', 284, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jdz9p', 'jdz9p', 'Políticas e cuidado em saúde mental: contribuições para a prática profissional', NULL, '["Marco Aurélio Soares Jorge","Maria Cecília de Araújo Carvalho","Paulo Roberto Fagundes da Silva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Ao deslocar o foco da atenção do hospital para os serviços de abordagem comunitária, o movimento da Reforma Psiquiátrica tem proporcionado, desde a década de 1980, uma série de avanços, mas também muitos desafios. Superar o aparato manicomial exige a consolidação de outras formas de lidar com o sofrimento psíquico. Exige, portanto, que os profissionais de saúde mental estejam preparados para oferecer um tipo de cuidado diferenciado. Entre esses profissionais, destaca-se o trabalhador de nível médio, que desempenha um papel de ligação fundamental entre o serviço, o paciente, sua família e a comunidade. O objetivo desta coletânea é contribuir para a formação e a capacitação desses trabalhadores. Os transtornos mentais são abordados em uma dimensão ampla ao longo do livro, que aborda temas como políticas de saúde e de saúde mental no Brasil, saúde mental na atenção básica, estratégias de intervenção e terapêuticas.', '["mental health services","psychiatric reform","community mental health services","deinstitutionalization","mental health policy","primary care","mental illness","mental health professionals","professional training","treatment options","family and community involvement"]', '10.7476/9788575415115', '9788575414415', 'https://books.scielo.org/id/jdz9p', NULL, NULL, 'https://books.scielo.org/id/jdz9p/cover/cover_thumbnail.jpeg', 296, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jfjjq', 'jfjjq', 'O Estado, a agricultura e a pequena produção', NULL, '["John Wilkinson"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O debate sobre a questão agrária no Brasil durante a década de 70 pode ser visto, retrospectivamente, como uma tentativa de enfrentar a superação política e econômica, pós-golpe militar, do debate clássico “feudalismo x capitalismo” dos anos 50 e 60.', '["agrarian question","smallholder farming","state and agriculture"]', '10.7476/9788599662717', '9788599662717', 'https://books.scielo.org/id/jfjjq', 'https://books.scielo.org/id/jfjjq/pdf/wilkinson-9788599662717.pdf', NULL, 'https://books.scielo.org/id/jfjjq/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jgkxw', 'jgkxw', 'Política e racionalidade: problemas de teoria e método de uma sociologia crítica da política', NULL, '["Fábio Wanderley Reis"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro, escrito originalmente em 1981 como tese destinada ao concurso para professor titular de ciência política da Faculdade de Filosofia e Ciências Humanas da UFMG, foi publicado inicialmente pela Editora da UFMG em 1984, como volume 37 da série Estudos Sociais e Políticos, sob o patrocínio da Revista Brasileira de Estudos Políticos, tendo tido uma segunda edição revista e atualizada, pela mesma editora, em 2000. Seu objetivo principal é o de procurar fundamentar uma abordagem dos problemas da ciência política em que a exigência de rigor possa ser conciliada com demandas de ordem prática ou normativa, as quais são vistas como inerentes à própria definição da atividade política e como impondo o interesse pelo tema do desenvolvimento político, ou da mudança política avaliada em termos de concepções doutrinárias acerca da boa sociedade a ser erigida', '["political rationality","political theory","political development","political transition","good society"]', '10.7476/9788579820281', '9788579820281', 'https://books.scielo.org/id/jgkxw', 'https://books.scielo.org/id/jgkxw/pdf/reis-9788579820281.pdf', NULL, 'https://books.scielo.org/id/jgkxw/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jhfsj', 'jhfsj', 'Arte-ciência: processos criativos', NULL, '["Evandro Fiorin","Paula da Cruz Landim","Rosangela da Silva Leote"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'da Silva, Maria Antônia Benutti, Paula da Cruz Landim, Paulo Roberto Masseran, Rosa Maria Araújo Simões e Rosangela da Silva Leote (de diversas unidades universitárias e cursos diferentes), debateu as ideias de sua formulação segundo o seguinte enfoque "Arte, ciência e processos criativos; filosofia no Brasil: incorporação ou criação".A partir dessa temática, a equipe optou por uma coletânea intitulada Arte-ciência: processos criativos, a ser organizada por representantes do Instituto de Artes (IA), câmpus de São Paulo, da Faculdade de Arquitetura, Artes e Comunicação (FAAC), câmpus de Bauru, e da Faculdade de Ciências e Tecnologia (FCT), câmpus de Presidente Prudente -todas instituições vinculadas à Unesp.Nessa proposição, vários docentes foram convidados a participar deste livro, que engloba diversos trabalhos ligados ao âmbito das manifestações artísticas, arquitetura e ao design contemporâneos, além dos processos criativos inerentes ao ensino dessas linguagens. EVANDRO FIORIN -PAULA DA CRUZ LANDIM -ROSANGELA S. LEOTECuriosamente, a multiplicidade de temas que estas diferentes unidades da Unesp vêm investigando trouxe um mote significativo para a definição do ponto de conexão, entre os processos criativos, das áreas de conhecimento aí compreendidas.Nosso recorte curatorial é constrito, no sentido em que acata a multiplicidade como diretriz.Em tempos de acondicionamento do conhecimento em suportes de armazenamento cada vez mais fluidos e, de certa forma, fora da mente, abre-se o espaço, nesta mente, para processos criativos tão ousados como a forma de comunicação que desenvolvemos na interface com o mundo.Portanto, a diversidade de enfoques trazidos nesta publicação, dividida por capítulos de especificidades temáticas, faz entender o subtexto da produção acadêmica nas áreas múltiplas aqui friccionadas.Este subtexto declara que, independentemente da área onde se proceda a transformação do conhecimento, se encontrará correlação de pensamentos e achados teóricos, que reflita o sistema de relações com o mundo e sua criação, em todas as direções.Há forte ligação, porém, entre os procedimentos operados pelos autores aqui selecionados.Vê-se uma coerente ligação entre as percepções e proposições que fazem diante da ação, em sua área.Para eles é a fácil relação com a ciência e/ou a tecnologia.Estas, evidentemente, indissociáveis do nosso momento cultural.Por essa razão, este livro não é sobre Ciência, sobre Arte, ou sobre Processos Criativos, mas sobre o corpo amalgamado das contaminações, nesta indissociabilidade que gera nossos bens culturais.Para propor um caminho possível de leitura, escolhemos uma distribuição de capítulos em ordem de aproximações temáticas.Entretanto, a visita pode ser aleatória, não hierárquica, fluídica como o nosso mundo, onde as mentes são entrecruzadas em macroexpansão.De qualquer modo, o leitor navegante encontrará no primeiro capítulo, "Heurística híbrida e processos criativos híbridos: uma reflexão sobre as metodologias da criação no contexto do hibridismo em artes", Agnus Valente revisa os processos criativos e as metodologias de criação sob a perspectiva do hibridismo em artes, como uma forma de compreender as operações artísticas atuais, uma vez que a ARTE-CIÊNCIA 9 hibridação como poética e metodologia (intencionalmente buscada pelo artista) tem se revelado um catalisador de encontros inéditos e férteis na criação contemporânea.No capítulo seguinte, "Arte dentro e fora do corpo", Rosangela da Silva Leote apresenta alguns modelos de interfaces físicas, procurando, a partir da identificação de alguns modos de aplicação de tais interfaces, encontrar certas interferências na percepção do corpo e do espaço do usuário/interator.O percurso textual é desenvolvido com apontamentos sobre as tecnologias mecatrônicas para próteses e órteses, e sua relação com as produções em arte com mídias emergentes.No terceiro ensaio da obra, "O processo criador no ensino da arte e do design: paradigma da representação & paradigma da diferença", Solange Bigal esboça um olhar sobre o ensino da arte e do design.Nele produz algumas inferências ativas e criativas sobre o tema, partindo do princípio da invenção poética e não de uma metodologia específica: uma flexão estética sobre aquelas disciplinas.No capítulo posterior, "Design contemporâneo: poéticas da diversidade no cotidiano", Mônica Moura faz uma investigação a respeito das diversidades presentes no design contemporâneo brasileiro, a partir dos anos 1990, adotando uma abordagem qualitativa, incorporando revisão de literatura, pesquisa documental e de campo.A autora apresenta as principais questões que estruturam o design na contemporaneidade e aponta rupturas, fusões e poéticas a partir do pensamento projetual.', '["art science","creative process","philosophy in Brazil","artistic manifestations","contemporary architecture","contemporary design","art education","design education","knowledge integration","UNESP","art and science","Brazilian design"]', '10.7476/9788579836244', '9788579836244', 'https://books.scielo.org/id/jhfsj', 'https://books.scielo.org/id/jhfsj/pdf/fiorin-9788579836244.pdf', NULL, 'https://books.scielo.org/id/jhfsj/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jhw6k', 'jhw6k', 'Uma genealogia do autor: a emergência e o funcionamento da autoria moderna', NULL, '["Marco Antônio Sousa Alves"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'De tão arraigada em nossas práticas discursivas, tendemos a naturalizar a figura do autor proprietário de sua obra, como se sempre tivesse existido. Mas nem sempre foi assim. Uma genealogia do autor procura explorar essa questão e investigar a emergência e o funcionamento da autoria moderna, aprofundando aspectos teórico-conceituais e históricos. Seguindo a via proposta por Michel Foucault de uma crítica genealógica, este livro descortina e questiona a posição que assumimos ao tomar a palavra e o regime de poder/saber que conforma a maneira como ainda hoje, em grande medida, produzimos, ordenamos e fazemos circular discursos.', '["authorship","modern authors","Michel Foucault","power and knowledge","discourse"]', '10.7476/9786558580850', '9786558580430', 'https://books.scielo.org/id/jhw6k', NULL, NULL, 'https://books.scielo.org/id/jhw6k/cover/cover_thumbnail.jpeg', 478, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jj4dt', 'jj4dt', 'Justiça reprodutiva: desafios interseccionais na saúde coletiva', 'desafios interseccionais na saúde coletiva', '["Brandão, Elaine Reis","Lowenkron, Laura","Carneiro, Rosamaria Giatti"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea reúne pesquisadoras de diferentes áreas para discutir como desigualdades de gênero, raça, classe, deficiência, território e identidade de gênero impactam o exercício dos direitos sexuais e reprodutivos no Brasil. Com base em experiências de grupos historicamente marginalizados, os capítulos propõem um novo olhar para a saúde coletiva, ancorado na justiça social e na equidade.', '["reproductive justice","intersectionality","sexual and reproductive rights","gender inequality","racial inequality","social class","disability","territory","gender identity","collective health","social justice","equity"]', '10.7476/9786557082898', '9786557082003', 'https://books.scielo.org/id/jj4dt', NULL, NULL, 'https://books.scielo.org/id/jj4dt/cover/cover_thumbnail.jpeg', 262, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jjksf', 'jjksf', 'O coronel e o lobisomem nas veredas da literatura regionalista brasileira', NULL, '["Naiara Alberti Moreno"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este trabalho apresenta uma leitura do romance O coronel e o lobisomem, publicado em 1964, pelo escritor brasileiro José Cândido de Carvalho. Ao problematizar o conceito de regionalismo literário, busca-se averiguar em que medida é possível aproximar essa obra da chamada tendência super-regionalista, a fim de determinar o lugar que ocupa tanto na produção do autor, quanto no conjunto da literatura regionalista brasileira. O estudo da categoria crítica do super-regionalismo convoca a compreensão de outros conceitos, como o de transculturação narrativa, que também serão dimensionados no sentido de contribuir para uma leitura da narrativa regionalista em sua dimensão insólita. A partir disso, propõe-se um delineamento dos procedimentos formais e dos eixos temáticos mobilizados pelo autor na composição de seu romance, de modo a contribuir para a revisão de sua fortuna crítica, bem como ampliar a compreensão dos paradigmas que orientam tal momento, ainda pouco estudado de maneira sistemática, do regionalismo literário brasileiro.', '["regionalism in literature","regionalist novel","critical reception"]', '10.7476/9788579836756', '9788579836756', 'https://books.scielo.org/id/jjksf', 'https://books.scielo.org/id/jjksf/pdf/moreno-9788579836756.pdf', NULL, 'https://books.scielo.org/id/jjksf/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jjss3', 'jjss3', 'Rumores da escrita, vestígios do passado: uma interpretação fonológica das vogais do português arcaico por meio da poesia medieval', NULL, '["Juliana Simões Fonte"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A proposta do presente livro é oferecer ao leitor uma descrição fonológica das qualidades vocálicas vigentes na primeira fase (período trovadoresco) do português arcaico a partir da análise das rimas e da grafia das Cantigas de Santa Maria, de Afonso X, o Sábio, Rei de Leão e Castela, elaboradas na segunda metade do século XIII.', '["Old Portuguese","phonology","vowels","Cantigas de Santa Maria","Afonso X","medieval poetry","rhyme","spelling","13th century"]', '10.7476/9788579831027', '9788579831027', 'https://books.scielo.org/id/jjss3', 'https://books.scielo.org/id/jjss3/pdf/fonte-9788579831027.pdf', NULL, 'https://books.scielo.org/id/jjss3/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jjx94', 'jjx94', 'Violências e vulnerabilidades nos desenhos infantis', NULL, '["Simone Gonçalves de Assis","Joviana Quintes Avanci"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', '"Crianças sempre gostam de brincar e de desenhar, uma maneira de expressar suas fantasias e energias sobre como sentem o mundo à sua volta. Os desenhos são comumente utilizados na escola e como estratégia diagnóstica nas clínicas de pediatria e psicologia. Violências e Vulnerabilidades nos Desenhos Infantis pode contribuir com novas visões e com sugestão de metodologia diversificada de trabalho e interlocução entre pesquisadores, clínicos e demais profissionais que atuam com crianças e famílias. Abre-se, assim, uma oportunidade para se aproximar do universo familiar das crianças por meio de seus desenhos, de ouvir seus pontos de vista, sentimentos e medos, de compreender suas habilidades e competências e de identificar vulnerabilidades e violências que vivenciaram. Contudo, desvendar a comunicação da criança sobre si e sua família por meio do desenho é território repleto de desafios e incertezas." (Evelyn Eisenstein, professora associada de pediatria e clínica de adolescentes da Faculdade de Ciências Médicas da Universidade do Estado do Rio de Janeiro, membro do Departamento Científico de Adolescência e do Grupo de Trabalho sobre Violência e Drogas da Sociedade Brasileira de Pediatria)', '["children''s drawings","violence against children","child vulnerability","children''s communication","family communication","child psychology","pediatrics"]', '10.7476/9786557082959', '9788575414835', 'https://books.scielo.org/id/jjx94', 'https://books.scielo.org/id/jjx94/pdf/assis-9786557082959.pdf', NULL, 'https://books.scielo.org/id/jjx94/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jkc92', 'jkc92', 'Cuentas y cuentos… Cuida de las cuentas públicas: custodia de la probidad', NULL, '["Jesús Alberto Suárez Pineda","María Luz Cárdenas Chaves","Vernon Weis Méndez Parada","Luisa Katherine Rojas Ávila","Iván Jesús Castillo Caicedo","Claudia Patricia Wilches Cuervo","Laura Contento Sanz","Jorge de Jesús Varela Urrego"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'De antemano cabe aclarar que no pretendemos dar respuesta a tales in-terrogantes. Solo queremos poner de relieve que son muchas las dificultades con que tropezamos al querer comprender la naturaleza del arte de contar en contabilidad. Sea como fuere, el caso es que nadie ha dado la última pa-labra a propósito de tales interrogantes. Más aún, basta reflexionar sobre la complejidad de esos problemas, para darse cuenta de que nunca obtendremos una fórmula mágica en el arte de resolverlos. En este capítulo estudiaremos la acepción contar con el sentido de computar o calcular, en sus relaciones con la contabilidad.', '["public accounts","probity","accounting","accounting ethics"]', '10.7476/9786289558241', '9786289558241', 'https://books.scielo.org/id/jkc92', 'https://books.scielo.org/id/jkc92/pdf/suarez-9786289558241.pdf', NULL, 'https://books.scielo.org/id/jkc92/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jkwf2', 'jkwf2', 'O processo de escolarização e a produção da queixa escolar: reflexões a partir de uma perspectiva critica em psicologia', NULL, '["Nilza Sanches Tessaro Leonardo","Záira Fátima de Rezende Gonzalez Leal","Adriana de Fátima Franco"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este Livro se caracteriza como resultado de pesqueisas que foram desenvolvidas tendo como foco a queixa escolar, o processo de escolarização e seus desdobramentos, buscando apreender os aspectos envolvidos no cotidiano escola, visando uma analise que se distancie do modelo centralizado no indivíduo. Neste aspectos, são decorrentes de estudos que se debruçaram sobre a presente temática e tangenciam a psicologia escolar, a educação, a educação especial e a Psicologia Histórico-Cultural.', '["school complaints","school psychology","critical psychology","school everyday life","special education","historical-cultural psychology","critique of individualism"]', '10.7476/9788576286936', '9788576285786', 'https://books.scielo.org/id/jkwf2', NULL, NULL, 'https://books.scielo.org/id/jkwf2/cover/cover_thumbnail.jpeg', 177, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jm3g9', 'jm3g9', 'O aspecto verbal no Português: a categoria e sua expressão', NULL, '["Luiz Carlos Travaglia"]', 'SciELO', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Um clássico dos estudos verbais no português, essa obra permite compreender as nuances dessa categoria morfossintática fundamental. Enquanto o escrutínio dos tempos verbais do português é de longa data, o “O aspecto verbal no Português: a categoria e sua expressão” inova em analizar a duração e as fases das situações verbais.', '["verbal aspect","Portuguese language","tense","morphosyntax"]', '10.7476/9786558240143', NULL, 'https://books.scielo.org/id/jm3g9', 'https://books.scielo.org/id/jm3g9/pdf/travaglia-9786558240143.pdf', NULL, 'https://books.scielo.org/id/jm3g9/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jm5wd', 'jm5wd', 'Estado sem Cidadãos: seguridade social na América Latina', NULL, '["Sônia Fleury"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1994, '1994-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Modalidades de transição e padrões de incorporação de demandas sociais 59', '["social security","Latin America","social rights","social needs","social policy"]', '10.7476/9788575412428', '9788575412428', 'https://books.scielo.org/id/jm5wd', 'https://books.scielo.org/id/jm5wd/pdf/fleury-9788575412428.pdf', NULL, 'https://books.scielo.org/id/jm5wd/cover/cover_thumbnail.jpeg', NULL, 52, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COA