INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jmpzg', 'jmpzg', 'O que é o SUS', NULL, '["Jairnilson Silva Paim"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A luta pelo direito à saúde e pela consolidação do Sistema Único de Saúde (SUS) brasileiro tem se expressado a partir da articulação de trabalhadores dos campos da saúde, pesquisadores e militantes dos movimentos sociais nas duas últimas décadas. Este livro busca esclarecer o que é, o que não é, o que faz, o que deve fazer e o que pode fazer o SUS. É destinado a todos que estão na luta por uma saúde pública de qualidade, aos trabalhadores do SUS, estudantes, pesquisadores, militantes de movimentos sociais e a sociedade em geral.', '["right to health","public health","health care reform","healthcare workers","social movements","health policy","Brazilian health system"]', '10.7476/9788575413425', '9788575411858', 'https://books.scielo.org/id/jmpzg', NULL, NULL, 'https://books.scielo.org/id/jmpzg/cover/cover_thumbnail.jpeg', 148, 64, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jn3yf', 'jn3yf', 'Sobre o suicídio (no Brasil contemporâneo): um retorno a Marx', 'um retorno a Marx', '["Pedro Henrique Antunes da Costa","Kíssila Teixeira Mendes"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Na presente obra, realiza-se um resgate e atualização da interpretação de Marx sobre o suicídio, tomando como parâmetro suas manifestações na contemporaneidade brasileira. Para além da descrição e aparência fenomênica, ensejando também subsidiar a abordagem ao suicídio em sua concretude, é necessário conhecê-lo a partir de sua determinação social. A teoria social marxiana como visão social de mundo reflexionada num/por um método de apreensão da realidade, bem como uma práxis orientada à transformação radical, justamente, por sua radicalidade de ir à raiz das coisas, pode contribuir para a interpretação e abordagem do suicídio no presente. Para isso, primeiramente, introduz-se a análise marxiana sobre o suicídio, junto dos desenvolvimentos e reelaborações para o escrutínio de tal fenômeno na realidade brasileira contemporânea. Em segundo lugar, são apresentados e debatidos quatro conjuntos de casos de suicídio referentes ao desemprego, à opressão patriarcal e machista, ao racismo estrutural e ao genocídio dos povos originários. Por fim, analisa-se a complexidade do suicídio na particularidade social brasileira, que se desenvolve historicamente até desaguar no presente. A exigência da supressão do suicídio como expressão máxima da impossibilidade de os indivíduos se efetivarem efetivarmos como humanos, de realizarem sua própria humanidade humanamente, é a exigência da supressão de um modo de produção da vida que não só necessita e produz suicídio, como o faz em larga escala.', '["suicide","Karl Marx","contemporary Brazilian society","unemployment","patriarchy","machismo","structural racism","humanization","modes of production","praxis"]', '10.7476/9786558462729', '9786558461029', 'https://books.scielo.org/id/jn3yf', NULL, NULL, 'https://books.scielo.org/id/jn3yf/cover/cover_thumbnail.jpeg', 109, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jn8dd', 'jn8dd', 'Acidentes industriais ampliados: desafios e perspectivas para o controle e a prevenção', NULL, '["Carlos Machado de Freitas","Marcelo Firpo Porto","Jorge Mesquita Huet Machado"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Contempla: aspectos teóricos e metodólogicos referentes às causas de acidentes industriais ampliados numa abordagem interdisciplinar; cenários em que estes se dão e mudanças possíveis a partir de sua ocorrência, tendo como referência casos de eventos passados e situações críticas presentes; planejamento de emergências e critérios para a gestão de desastres; estratégias institucionais de controle e prevenção. A obra se espraia pela multiplicidade de olhares de vinte especialistas, brasileiros e estrangeiros, de várias instituições e formações, que, em 13 capítulos, garantem ao leitor um panorama abrangente e atual sobre tema tão pouco explorado, mas tão importante para a preservação da vida.', '["industrial accidents","accident prevention","accident control","emergency planning","disaster management","critical incidents","occupational safety","interdisciplinary approach"]', '10.7476/9788575415085', '9788575415085', 'https://books.scielo.org/id/jn8dd', 'https://books.scielo.org/id/jn8dd/pdf/freitas-9788575415085.pdf', NULL, 'https://books.scielo.org/id/jn8dd/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jn9s4', 'jn9s4', 'Andrés de Santa María en los críticos de arte colombianos', NULL, '["Víctor Alberto Quinche Ramírez"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'La figura del crítico de arte es una instancia de mediación en el proceso social de “lectura” de las obras de arte. La lectura de una obra hace que de una existencia previa meramente virtual, la obra pase a ser actualizada en la experiencia que el receptor hace de ella en el proceso de actualización de sentido mediante el acto mismo de la lectura. De esta manera, la lectura que propone el crítico es o aspira a ser canónica, y su pretensión de corrección aspira a ser normativa e ilustradora para la experiencia del receptor “normal”. Este trabajo reconstruye la forma como los críticos de arte en Colombia se han referido (han “leído”) a la producción pictórica de Andrés de Santa María (1860-1945) desde la fase de su estancia en Bogotá a finales del siglo xix, hasta el año 2002. La herramienta que se emplea para leer el desarrollo del lenguaje de los críticos es una combinación de la estética de la recepción, la hermenéutica y algunos rasgos de la filosofía analítica del arte.', '["art critics","reception theory","hermeneutics","analytic philosophy of art","history of art criticism","19th-century art","20th-century art"]', '10.7476/9789587385069', '9789587385052', 'https://books.scielo.org/id/jn9s4', NULL, NULL, 'https://books.scielo.org/id/jn9s4/cover/cover_thumbnail.jpeg', 104, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jnhs5', 'jnhs5', 'Franceses no Brasil: séculos XIX-XX', NULL, '["Laurent Vidal","Tania Regina de Luca"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A admiração pela França constituiu um traço marcante das elites brasileiras desde os primórdios da independência, momento em que se tornou urgente dotar o jovem país de uma identidade capaz de lhe assegurar feições próprias. Sob a batuta de um diminuto grupo, concebeu-se e projetou-se uma representação da nação que não pode ser dissociada dos valores e da auto-imagem de seus propugnadores. O livro, organizado no bojo das comemorações do Ano da França no Brasil, pretende reunir estudos que analisam a presença de imigrantes franceses em território brasileiro, temática que ocupa lugar bem menos proeminente que o reservado à influência da cultura francesa.', '["French-Brazilian relations","national identity","Brazilian elites","French cultural influence","immigration history","19th-20th century"]', '10.7476/9788539304387', '9788571399181', 'https://books.scielo.org/id/jnhs5', NULL, NULL, 'https://books.scielo.org/id/jnhs5/cover/cover_thumbnail.jpeg', 487, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jnj37', 'jnj37', 'Pesquisas, Vivências e Práticas de Educação em Saúde na Escola', NULL, '["Ronaldo Adriano Ribeiro da Silva","Tiago Venturi"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta é uma obra que oportuniza o compartilhar de experiências, de reflexões e de investigações sobre a Saúde na Escola, reconhecendo a diversidade de saberes que circulam nesse espaço. Nas últimas décadas, a Educação em Saúde realizada na escola deixou de ser apenas um campo de práticas, passando a constituir-se como um campo de estudos e pesquisas, envolvendo diversas áreas do conhecimento. A Escola é um espaço privilegiado para trabalhar propostas educativas que visem a transformação das condições de vida e o exercício da cidadania dos sujeitos, numa perspectiva de promoção da saúde. A pesquisa em Educação em Saúde destaca-se no campo da Educação Científica, tendo em vista os vínculos da saúde com a área das Ciências Naturais. Esta obra, constituída de vinte e seis capítulos, busca dialogar com as diferentes perspectivas oriundas destes campo de pesquisa, estudos e prática. Trata-se do primeiro volume da Coleção Ensino de Ciências, organizada pelos pesquisadores Roque Ismael da Costa Güllich, Rosangela Inês Matos Uhmann e Rosemar Ayres dos Santos.', '["school-based health education","school health","health promotion","citizenship education","science education","living conditions"]', '10.7476/9786586545722', '9786586545722', 'https://books.scielo.org/id/jnj37', 'https://books.scielo.org/id/jnj37/pdf/silva-9786586545722.pdf', NULL, 'https://books.scielo.org/id/jnj37/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jnkmq', 'jnkmq', 'Patrimonio inmaterial en el Ecuador: una construcción colectiva', NULL, '["Eloísa Teresita Carbonell Yonfá"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Las tradiciones, en contextos de fragilidades geopolíticas, se han visto afectadas por prácticas aculturizantes. Estas, unidas al consumismo y al mercantilismo, pasan, de manera silenciosa, a la trastienda del imperio monocultural. Con la Declaratoria del Patrimonio Inmaterial realizada en la convención de París, en 2003, y ratificada por Ecuador en 2005, se crea una mayor conciencia sobre la importancia de salvaguardar la memoria social, patrimonio colectivo de los pueblos. El presente texto documenta la participación ciudadana en esa tarea de cuidar saberes y prácticas que son parte de la vida cotidiana de las comunidades, ciudades, pueblos y colectivos; por tanto, parte del patrimonio inmaterial y legado cultural para las presentes y futuras generaciones.', '["intangible cultural heritage","collective heritage","social memory","citizen participation","cultural heritage preservation","consumerism","cultural imperialism","Ecuador"]', '10.7476/9789978106228', '9789978103968', 'https://books.scielo.org/id/jnkmq', 'https://books.scielo.org/id/jnkmq/pdf/carbonell-9789978106228.pdf', NULL, 'https://books.scielo.org/id/jnkmq/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jnrq6', 'jnrq6', 'Companheiros servidores: o sindicalismo do setor público na CUT', NULL, '["Sidney Jard da Silva"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Nos anos 1990s, quando as reformas estruturais entraram na agenda política nacional, a oposição da CUT à mudança do regime previdenciário brasileiro foi explicada como resultado do poder dos sindicatos do setor público sobre as decisões da central que os abrigava. Assim, o “corporativismo” dos sindicatos de servidores públicos seria o principal responsável pela paralisação da reforma da previdência pública. Contrário a tal interpretação - e apoiado em cuidadosa pesquisa - Sidney Jard mostra uma realidade bem mais complexa. Ao manejar um conjunto expressivo de dados, identifica a importância das lideranças sindicais da área pública na CUT. Demonstra, também, que os companheiros servidores estavam bem mais divididos do que se supunha - e alguns se revelavam mais dispostos a discutir com o governo os termos da reforma do que a ela se opor frontalmente.', '["public sector unions","public sector employees","pension reform","corporatism","union leadership","union centralization","structural reforms","1990s Brazil","labor movement"]', '10.7476/9788568576830', '9788568576830', 'https://books.scielo.org/id/jnrq6', 'https://books.scielo.org/id/jnrq6/pdf/silva-9788568576830.pdf', NULL, 'https://books.scielo.org/id/jnrq6/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jnzhd', 'jnzhd', 'Visões do feminino: a medicina da mulher nos séculos XIX e XX', NULL, '["Ana Paula Tavares Martins"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O presente livro da coleção História e Saúde ao mesmo tempo que enfoca o nascimento de duas especialidades da medicina - a obstetrícia e a ginecologia - aborda, a partir de pesquisa aprofundada - o nascimento de todo um discurso que pretendia conhecer a natureza feminina.Quando o corpo feminino passa a ser um objeto de estudo e quando o discurso médico-científico passa a discursar sobre este corpo, a medicina também se torna responsável pela construção de muitos mitos ainda hoje presentes no imaginário ocidental acerca da mulher. Desse modo, trabalhando não só com o discurso médico europeu, mas também com trabalhos diversos de renomados intelectuais brasileiros acerca do corpo feminino, Ana Paula Vosne Martins revela diferentes representações construídas sobre a mulher ao longo dos séculos XIX e XX.', '["history of medicine","women''s health","obstetrics","gynecology","female body","representation of women","medical discourse","gender myths","19th century","20th century","Brazilian intellectuals"]', '10.7476/9788575414514', '9788575414514', 'https://books.scielo.org/id/jnzhd', 'https://books.scielo.org/id/jnzhd/pdf/martins-9788575414514.pdf', NULL, 'https://books.scielo.org/id/jnzhd/cover/cover_thumbnail.jpeg', NULL, 52, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jppjz', 'jppjz', 'Manuais para educação do corpo: educação física, moral e higiene', NULL, '["Moreno, Andrea","Quitzau, Evelise Amgarten","Anjos, Iara Marina dos Bonifácio"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro Manuais para educação do corpo: educação física, moral e higiene reúne estudos e pesquisas históricas a partir de manuais para a educação do corpo produzidos por pesquisadores da Argentina, Brasil e Uruguai. Em cada capítulo, os autores e as autoras analisam um manual que tematiza a Educação do Corpo. O resultado são textos que discutem um amplo espectro de temas que vão das práticas corporais a questões de gênero e sexualidade. A obra conta ainda com um capítulo introdutório que aborda possibilidades teórico-metodológicas para mobilizar manuais como objeto e fonte de pesquisa. Assim, o livro é um convite ao constante (re)pensar na pesquisa histórica acerca da educação do corpo e a uma potencial agenda de pesquisa.', '["body education","physical education","moral education","hygiene","educational manual","history of education","gender","sexuality","body practices","Argentina","Brazil"]', '10.7476/9786588592311', '9786588592144', 'https://books.scielo.org/id/jppjz', NULL, NULL, 'https://books.scielo.org/id/jppjz/cover/cover_thumbnail.jpeg', 178, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jpst2', 'jpst2', 'A Petrobrás e a gestão do território no Recôncavo Baiano', NULL, '["Cristóvão Brito"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Estudo de geografia regional histórica que investiga o universo político, social, econômico, técnico-produtivo e espacial do Recôncavo Baiano em dois períodos: 1930 até meados de 1950 e a partir daí até o ano 2000. Parte do princípio da ressignificação do conceito de território para examinar a situação do Recôncavo pré-Petrobras e depois do impacto produzido com a sua introdução e expansão. Observa a atuação dos vários atores sociais no cenário territorial estudado.', '["Petrobras","territorial management","Recôncavo Baiano","oil and gas industry","territoriality","regional history","social actors","territorial expansion"]', '10.7476/9788523209216', '9788523209216', 'https://books.scielo.org/id/jpst2', 'https://books.scielo.org/id/jpst2/pdf/brito-9788523209216.pdf', NULL, 'https://books.scielo.org/id/jpst2/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jq5dd', 'jq5dd', 'Apiterapia: medicamentos das abelhas e possíveis tratamentos', NULL, '["José Maurício Sforcin","Wilson Antonio Weis","Nicolas Ripari","Fernanda Lopes Conte","Mariana da Silva Honorio","Arthur Alves Sartori","Karina Basso Santiago"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Os produtos apícolas têm sido utilizados há séculos por vários povos para o tratamento de diversas enfermidades. Nos dias atuais, seu consumo vem aumentando, seja na forma de suplementos para prevenção ou tratamento de doenças, seja como nutracêuticos. As pesquisas sobre as propriedades dos produtos apícolas também cresceram nas últimas décadas, com consequente aumento do interesse pela apiterapia, que atualmente integra o rol de atividades de medicina complementar de vários países. Experimentos realizados in vitro e in vivo, bem como ensaios clínicos, têm demonstrado que esses produtos podem ser indicados para o tratamento de várias enfermidades ou associados a tratamentos convencionais para manutenção da saúde. Visando estabelecer uma ponte entre apicultores, apiterapeutas e pesquisadores, este livro apresenta informações sobre os produtos apícolas, as evidências científicas de seu uso pelas abelhas e pelo homem e as aplicações desses produtos na apiterapia.', '["apitherapy","bee products","nutraceuticals","complementary therapy"]', '10.7476/9786557142974', '9786557142974', 'https://books.scielo.org/id/jq5dd', 'https://books.scielo.org/id/jq5dd/pdf/sforcin-9786557142974.pdf', NULL, 'https://books.scielo.org/id/jq5dd/cover/cover_thumbnail.jpeg', NULL, 17, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jqpk8', 'jqpk8', 'Políticas de saúde no Brasil: continuidades e mudanças', NULL, '["Cristiani Vieira Machado","Tatiana Wargas de Faria Baptista","Luciana Dias de Lima"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Analisar o contexto e a dinâmica da política de saúde brasileira, com ênfase nos anos 2000, é a proposta desta coletânea. O livro traz uma síntese da política de saúde contemporânea e apresenta perspectivas para o futuro. Ainda que com base em perspectivas teóricas e recortes empíricos distintos, os capítulos caracterizam-se pela valorização da dimensão histórica e a consideração da multiplicidade de fatores – econômicos, políticos e sociais – que influenciam a formulação e a implementação das políticas setoriais. O livro está organizado em três partes: contexto, caminhos e processos. A primeira discute as relações entre desenvolvimento, atuação do Estado nas políticas sociais e na saúde, e a dinâmica dos mercados em saúde no Brasil no período recente. O planejamento, o modelo regulatório, o financiamento, a atenção primária à saúde, a gestão do trabalho e da educação em saúde estão entre os temas analisados na segunda parte. Aborda-se ainda a dinâmica da agenda federal da saúde, com destaque para a condução de diferentes políticas, como o Brasil Sorridente, o Serviço de Atendimento Móvel de Urgência e a Farmácia Popular. A terceira parte abrange os processos de interação entre atores relevantes para a construção das políticas nacionais de saúde: as relações intergovernamentais, particularmente na descentralização e regionalização; as relações entre Ministério da Saúde, Conselho Nacional de Saúde e movimentos sociais, associadas a iniciativas de fortalecimento da gestão participativa na saúde; a atuação do Legislativo e suas relações com o Executivo na definição da política setorial.', '["health policy","Brazilian health policy","2000s","health care financing","primary care","health market","state intervention in health","health regulation","health planning","health education","health workforce management","mobile emergency care"]', '10.7476/9788575415832', '9788575414194', 'https://books.scielo.org/id/jqpk8', NULL, NULL, 'https://books.scielo.org/id/jqpk8/cover/cover_thumbnail.jpeg', 324, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jqwf5', 'jqwf5', 'Farmacovigilância: da teoria à prática', NULL, '["Fabiana Rossi Varallo","Patrícia de Carvalho Mastroianni"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Pharmacology, Toxicology and Pharmaceutics', 'Este livro analisa questões relacionadas à farmacovigilância num contexto histórico – traça um panorama acerca do assunto que abrange da antiguidade ao Brasil atual, abordando facetas como reações adversas a medicamentos, erros de prescrição, desvios de qualidade e suspeitas de inefetividade de medicamentos. Além de análises, a obra traz propostas para a implantação de um serviço diferenciado de farmacovigilância. A ideia de que tratamentos médicos possuem reações adversas que devem ser evitadas, mostra o livro, vem de longo tempo. Na Antiguidade, o Código de Hammurabi, conjunto de leis escritas da Babilônia, de 2.200 a.C., já previa punição ao médico causasse a morte de um paciente – ele teria as mãos amputadas. Já Hipócrates (460-370 a.C.), considerado o “pai da medicina” postulava: “primeiramente não causar danos”. E o médico e filósofo Galeno (131-201) advertia contra os perigos das prescrições mal-escritas e obscuras. De acordo com a pesquisa, teria sido feito na Grã-Bretanha o primeiro registro de Reação Adversa a Medicamentos (RAM), em 1848. Desde essa época, a vigilância e a fiscalização sobre esses produtos têm se tornado cada vez mais intensas em todo o mundo, inclusive com forte atuação da Organização Mundial da Saúde. No Brasil, legislação relacionada às reações adversas a medicamentos existe desde a década de 1970. A primeira data de 1976 e, entre outras providências, submete à vigilância sanitária medicamentos, drogas, insumos farmacêuticos e correlatos, assim como cosméticos e saneantes, entre alguns outros produtos. Hoje, o governo brasileiro exige que os detentores de registro de medicamentos gerenciem os riscos dos produtos.', '["pharmacovigilance","adverse drug reactions","prescribing errors","drug ineffectiveness","history of pharmacovigilance","pharmacovigilance legislation","drug safety regulation","Brazil"]', '10.7476/9786557140307', '9786557140307', 'https://books.scielo.org/id/jqwf5', 'https://books.scielo.org/id/jqwf5/pdf/varalho-9786557140307.pdf', NULL, 'https://books.scielo.org/id/jqwf5/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jqzqj', 'jqzqj', 'Perspectivas de responsabilidad por daños ambientales en Colombia', NULL, '["Gloria Amparo Rodríguez","Iván Vargas-Chaves"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Aunque el daño ambiental desde sus dos esferas, individual y colectiva, ha despertado un notable interés en las últimas décadas por parte de la doctrina en Colombia, se trata de una disciplina que en nuestro país aún no se aborda con el suficiente rigor y profundidad que merece. La razón, es el idéntico abordaje de las problemáticas asociadas, así como la omisión de los avances dados en el derecho comparado, donde la concepción del rol que deben tener las instituciones jurídicas va más allá, hacia una comprensión integral del daño a partir de la alteración funcional de los ecosistemas, de los cuales hacen parte tanto los individuos como la naturaleza. En efecto, hoy en día existe cierto consenso desde el derecho comparado, respecto al deber ser del régimen de responsabilidad aplicable a esta noción moderna e integral del daño ambiental. Un régimen capaz de hacer frente no sólo a los componentes del medio natural, sino a todos aquellos que lo conforman, desde la capa de ozono afectada por las emisiones de gases de efecto invernadero, o un paisaje deteriorado por la contaminación visual, hasta las semillas modificadas genéticamente e incluso los animales que han sido objeto de apropiación por el ser humano. Desde la Especialización y la Línea de Investigación en Derecho Ambiental de la Universidad del Rosario, se impulsó este libro colectivo sin otro ánimo que el de aportar al estudio del daño ambiental, una propuesta de construcción doctrinal en dirección a la tendencia antes descrita. Las contribuciones aquí reunidas proceden de diez autores, incluyendo las de sus editores académicos, todos ellos artífices de un meritorio esfuerzo de sistematización, transmisión de conocimientos y experiencia.', '["environmental degradation","environmental liability","environmental law doctrine","comparative environmental law"]', '10.7476/9789587386448', '9789587386448', 'https://books.scielo.org/id/jqzqj', 'https://books.scielo.org/id/jqzqj/pdf/amparo-9789587386448.pdf', NULL, 'https://books.scielo.org/id/jqzqj/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jr25z', 'jr25z', 'Santo Tomás de Aquino: ideas políticas y jurídicas. Proyección en el derecho tributario', NULL, '["Mauricio A. Plazas Vega","Andrea Amatucci"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Santo Tomás de Aquino es uno de los más grandes filósofos de la historia Universal. Su monumental obra Suma de teología no solo ha sido y seguirá siendo un referente de primer orden para la doctrina de la Iglesia, sino que ha sido y será determinante en las más variadas expresiones en las ciencias sociales y, por supuesto en el derecho. La teoría de la ley, las profundas reflexiones sobre el derecho natural, la teoría de la justicia y su relación con el derecho, la teoría de la causa, la función del juez; estos, y muchos otros temas trascendentales para los juristas, son abordados con excepcional inspiración en esa obra que, como bien dijo el Papa Juan XXII durante el proceso de canonización de su autor, fue el verdadero y más grande milagro del Aquinate. Los dos textos que integran este volumen, de Andrea Amatucci y Mauricio A Plazas Vega, versan, en su orden, sobre el pensamiento político y jurídico del tomismo en general y su proyección el derecho tributario. De esta manera, se pretende ofrecer a los lectores una visión global del pensamiento ético de Tomás de Aquino que les permita adentrarse en la materia estrictamente tributaria, siempre de la mano de la obra del Angellico. Entre los temas que aborda el primer ensayo se hace especial énfasis en la teoría de la ley, la teoría de la justicia y la teoría de la causa. Sobre esa base, viene a obrar como un verdadero contexto para el segundo de los ensayos dedicado, en esencia, a la fundamentación filosófica tomista del principio fiscal de capacidad contributiva. Todo lo cual es muy pertinente en los tiempos actuales en los cuales la preocupación legal, doctrinaria y jurisprudencial por el principio fundamental de justicia es una constante en los regímenes de democracia liberal.', '["Thomas Aquinas","Summa Theologiae","political thought","legal thought","tax law","legal theory","natural law","theory of justice","contributive capacity principle","liberal democracy","canonization"]', '10.7476/9789587386080', '9789587386073', 'https://books.scielo.org/id/jr25z', NULL, NULL, 'https://books.scielo.org/id/jr25z/cover/cover_thumbnail.jpeg', 94, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jr2x9', 'jr2x9', 'As representações sociais e a experiência com o diabetes: um enfoque socioantropológico', NULL, '["Reni Aparecida Barsaglini"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A proposta do livro é lançar um olhar diferenciado sobre o diabetes, a partir da sociologia e da antropologia. A obra destaca a importância de ouvir com atenção as pessoas que vivenciam uma condição crônica como o diabetes: essa escuta pode subsidiar intervenções de saúde que sejam mais sensíveis aos aspectos culturais e favoreçam a interação entre profissionais e adoecidos. A pesquisa que originou a publicação utilizou metodologia qualitativa, incluindo consulta à literatura biomédica básica e a documentos de entidades ligadas ao diabetes, entrevistas com pacientes, familiares e profissionais de saúde, e observações em campo (no bairro, na residência e na unidade de saúde).', '["diabetes mellitus","social representations","illness experience","chronic disease","patient experience","cultural factors in health","health interventions","family caregivers"]', '10.7476/9788575413609', '9788575412084', 'https://books.scielo.org/id/jr2x9', NULL, NULL, 'https://books.scielo.org/id/jr2x9/cover/cover_thumbnail.jpeg', 248, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jr9nm', 'jr9nm', 'Subordinação racial no Brasil e na América Latina: o papel do Estado, o Direito Costumeiro e a Nova Resposta dos Direitos Civis', NULL, '["Tanya Katerí Hernández"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra esmiúça o direito costumeiro de regulação racial e analisa o progresso recente de legislações de igualdade racial no Brasil e em países latino-americanos, a partir da examinação dos costumes legais e a histórica cumplicidade dos Estados da região com a criação e manutenção de hierarquias raciais. A tradução abre possibilidades para outros debates dentro do campo científico enquanto resposta legal ao histórico de marginalização e negação do racismo no Brasil e críticas ao modelo de Estado Desenvolvimentista que também contribui para as desigualdades raciais na região.', '["racial subordination","racial hierarchy","customary law","role of the state","racism","racial inequality","Brazil","Latin America"]', '10.7476/9788523220150', '9788523220150', 'https://books.scielo.org/id/jr9nm', 'https://books.scielo.org/id/jr9nm/pdf/hernandez-9788523220150.pdf', NULL, 'https://books.scielo.org/id/jr9nm/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jrdjn', 'jrdjn', 'Atores e poderes na nova ordem global: assimetrias, instabilidades e imperativos de legitimação', NULL, '["Gilberto Dupas"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O autor Gilberto Dupas é um dos principais estudiosos das lógicas e efeitos do capitalismo global e volta ao tema da globalização nesta obra, onde aborda os destinos da humanidade, tratando de suas incursões na filosofia, na política, na economia e apontando os impasses gerados nessa nova ordem global. Aborda a assimetria entre os poderes que os principais atores econômicos, políticos e sociais exercem sobre a nova ordem global e caracteriza as instabilidades e os impasses na formulação de modelos consistentes de equilíbrio e governabilidade sistêmica para a primeira metade do século XXI.', '["international order","globalization","global capitalism","power imbalance","global actors","political instability","legitimacy","systemic governance","global equilibrium","21st century"]', '10.7476/9788539302802', '9788571395749', 'https://books.scielo.org/id/jrdjn', NULL, NULL, 'https://books.scielo.org/id/jrdjn/cover/cover_thumbnail.jpeg', 319, 30, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-js4st', 'js4st', 'Construcción de agendas interinstitucionales ambientales: una mirada desde los derechos humanos', NULL, '["Leonardo Güiza Suárez","María Teresa Palacios Sanabria"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este texto hace el abordaje de las temáticas ambientales a partir de un enfoque de Derechos Humanos, entendido como una metodología de comprensión de las diversas funciones que al interior de los Estados democráticos se deben adoptar en compatibilidad con el ordenamiento internacional y el desarrollo normativo de esta rama del derecho. Para llevar a cabo este trabajo, la Corporación Autónoma Regional de Cundinamarca –CAR– y la Universidad del Rosario, adelantaron un proyecto piloto fundado en la necesidad de preservar las condiciones naturales y de biodiversidad que hoy se ven amenazadas por el crecimiento y la expansión de las actividades industriales, comerciales, turísticas y de urbanización, entre otras. Bajo este marco conceptual se focalizaron los principales ejes temáticos sobre los conflictos socio-ambientales y se fijó el objetivo principal del proyecto de investigación el cual consistió en llevar a cabo una agenda interinstitucional como estudio de caso para generar los lineamientos y poner en marcha un observatorio de agendas interinstitucionales en la jurisdicción de la CAR.', '["environmental rights","socio-environmental conflicts","biodiversity conservation","agenda setting","environmental observatory","regional autonomy","Cundinamarca"]', '10.7476/9789587384857', '9789587384840', 'https://books.scielo.org/id/js4st', NULL, NULL, 'https://books.scielo.org/id/js4st/cover/cover_thumbnail.jpeg', 306, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-js9g6', 'js9g6', 'Cultura contemporânea, identidades e sociabilidades: olhares sobre corpo, mídia e novas tecnologias', NULL, '["Ana Lúcia de Castro"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne a reflexão acerca das identidades na cultura contemporânea,realizada por pesquisadores que participaram do Seminário: Cultura contemporânea, corpo e novas tecnologias: diálogos em torno das identidades. O objetivo geral das reflexões aqui apresentadas é tomar as inovações tecnológicas e seus impactos na vida cotidiana - particularmente na renovação e reinvenção de formas de sociabilidade e de construção de identidades - como uma chave privilegiada para o adentramento em meandros da cultura contemporânea. O corpo, suporte da cultura e território de construção de identidades, ao incorporar os recursos tecnológicos disponibilizados pelo mercado estético, como próteses, implantes, intervenções e tratamentos à base de laser, tem seu estatuto modificado e as fronteiras entre natureza e cultura passam a ser revistas em novos parâmetros, impondo novos desafios à reflexão sócio-antropológica. Este livro busca contribuir para este debate, somar um pequena centelha ao enorme esforço que se faz necessário no sentido de repensarmos as clássicas dicotomias conceituais que vem marcando a reflexão das ciências humanas e se demonstrando cada vez mais abaladas em seu alcance explicativo, frente às aceleradas transformações vivenciadas na vida social nesta modernidade do início do século XXI.', '["contemporary culture","identity construction","sociability","body","new technologies","media","prosthetics","implants","laser therapy","nature and culture","sociocultural anthropology","everyday life"]', '10.7476/9788579830952', '9788579830952', 'https://books.scielo.org/id/js9g6', 'https://books.scielo.org/id/js9g6/pdf/castro-9788579830952.pdf', NULL, 'https://books.scielo.org/id/js9g6/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jsn9h', 'jsn9h', 'Na trajetória das Letras: reflexões sobre a construção coletiva da experiência acadêmica na UFFS', NULL, '["Morgana Fabiola Cambrussi"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea de textos que constitui esta obra analisa, relata e compartilha as experiências acadêmicas vivenciadas pelo Curso de Letras ao longo dos dez primeiros anos de atuação. Ao abordar a própria experiência, são debatidos aspectos da formação superior, em especial nos cursos de licenciatura. A obra trata de questões históricas, como o desenvolvimento do ensino superior na região oeste de Santa Catarina, e de questões atuais, a exemplo das políticas de acessibilidade, ações afirmativas e curricularização da extensão. O público de interesse são as pessoas vinculadas à área de Letras e Linguística, assim como profissionais de demais áreas das Ciências Humanas, para as quais se apresentem problemáticas correlatas. “Na trajetória das Letras: reflexões sobre a construção coletiva da experiência acadêmica na UFFS”, constituído de 16 capítulos, em três partes – Programas de formação acadêmica e de inserção social do Curso de Letras, Projetos e políticas de ação pedagógica e A história e nosso futuro em Letras – tanto celebra os 10 anos do Curso de Letras – Campus Chapecó, como lança um compromisso com a atuação profissional combativa em resguardo do porvir, da continuidade das conquistas que permitiram o Curso chegar até aqui.', '["Letters course","teacher professional development","higher education history","western Santa Catarina","accessibility policy","affirmative action","curricularization of extension","social inclusion"]', '10.7476/9786586545975', '9786586545975', 'https://books.scielo.org/id/jsn9h', 'https://books.scielo.org/id/jsn9h/pdf/cambrussi-9786586545975.pdf', NULL, 'https://books.scielo.org/id/jsn9h/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jsy9s', 'jsy9s', 'De Cuba a Tenochtitlán. A busca dos ‘segredos da terra’. Estudo da trajetória de Fernando Cortés no México (de 18 de fevereiro a 8 de novembro de 1519)', NULL, '["José Joaquím Pereira Melo"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste trabalho foi feita uma opção de centralizar o tema a ser discutido – a Conquista do Império Asteca - no acompanhamento das ações de Fernando Cortés, desde a sua saída de Cuba, a 18 de fevereiro de 1519, até a ocupação de Tenochtitlán, em 8 de novembro de 1519. Para esta análise foram privilegiadas as informações prestadas pelo próprio conquistador, particularmente as contidas em suas Cartas de Relação, dirigidas ao Rei, relatos paralelos de cronistas da época, e bibliografia que aborda o tema. A ação de Cortés deve ser entendida desenvolvendo-se em direção às autoridades coloniais, aos seus homens e aos nativos insatisfeitos com o Império Asteca e de Carlos V, Rei da Espanha. Para obter o que pretendia, Cortés oferecia a cada uma dessas frentes o que parecia ser seu centro de interesse, num exercício complexo de convencimento, que foi chamado de ‘estratégia de sedução’. Entre as questões abordadas estão o projeto de Cortés de conhecer as novas terras: a ligação que promoveu diretamente com a Metrópole, desqualificando as autoridades cubanas e se apresentando como vassalo ideal e fiel; a organização da empresa conquistadora em buscar conhecer os ‘segredos’ da terra, a partir dos aspectos legais, diplomáticos, religiosos e militares; na fundação de Vera Cruz, enquanto ponto de apoio do processo conquistador, e no desvendamento dos ‘segredos’ da terra, em suas particularidades.', '["Hernán Cortés","Tenochtitlan","Vera Cruz","conquistadors","colonial authority","Aztec Empire","Charles V"]', '10.7476/9788576287421', '9788576286905', 'https://books.scielo.org/id/jsy9s', NULL, NULL, 'https://books.scielo.org/id/jsy9s/cover/cover_thumbnail.jpeg', 278, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jv5k9', 'jv5k9', 'Escritos sobre a universidade', NULL, '["Marilena de Souza Chauí"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Uma das mais brilhantes intelectuais brasileiras, Marilena Chauí discute em diversos ensaios a questão da universidade pública no Brasil. Temas como o da autonomia universitária cedendo lugar à universidade administrada nos moldes das grandes empresas privadas, a conseqüente confusão de critérios na avaliação de sua produtividade e a recente questão dos professores ditos improdutivos da Universidade de São Paulo, são tratados pela autora de forma combativa nesta obra.', '["public universities","university autonomy","privatization of higher education","academic freedom","Brazilian higher education","Marilena Chauí","Universidade de São Paulo"]', '10.7476/9788539303045', '9788571393271', 'https://books.scielo.org/id/jv5k9', NULL, NULL, 'https://books.scielo.org/id/jv5k9/cover/cover_thumbnail.jpeg', 205, 651, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jvcnv', 'jvcnv', 'Educação das relações étnico-raciais: avaliação da formação de docentes', NULL, '["Dalila Fernandes de Negreiros"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro analisa a implementação da Educação das Relações Étnico-raciais no Brasil, a partir da Lei 10639/2003, que estabelece a obrigatoriedade do ensino de história e cultura africana e afro-brasileira no currículo da educação básica. No livro é descrito o processo de implementação da lei no contexto da luta do movimento negro brasileiro. São apresentadas e sistematizadas avaliações sobre a implementação realizadas pelo Ministério da Educação, a Secretaria de Políticas de Promoção de Igualdade Racial da Presidência da República e por pesquisadores da temática. Foram analisados dois programas federais que visaram implementar a educação das relações étnico-raciais: o Programa Educação Africanidades Brasil (Africanidades) e Programa de Ações Afirmativas para a População Negra nas Instituições Federais e Estaduais de Educação Superior (Uniafro). A partir da análise desses modelos de execução de política pública, bem como das avaliações da implementação da educação das relações étnico-raciais é possível indicar caminhos para a implementação de uma política efetiva de formação de docentes para a implementação da Lei 10639/2003.', '["ethnic-racial relations education","Law 10.639/2003","teacher professional development","implementation evaluation","Afro-Brazilian history and culture","Black movement","public policy implementation","affirmative action","racial equality policy","basic education curriculum"]', '10.7476/9788568576946', '9788568576946', 'https://books.scielo.org/id/jvcnv', 'https://books.scielo.org/id/jvcnv/pdf/negreiros-9788568576946.pdf', NULL, 'https://books.scielo.org/id/jvcnv/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jvjh7', 'jvjh7', 'Francisco Brennand: aspectos da construção de uma obra em escultura cerâmica', NULL, '["Camila da Costa Lima"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Referências bibliográfi cas 185 Anexos 193 INTRODUÇÃOPor que um artista cria, de onde partem suas ideias, como é seu método para elaboração de sua obra, seu processo de execução?Essas foram algumas questões que ajudaram a nortear o rumo desta pesquisa.A curiosidade de saber sobre o que está por trás da obra que chega a nossos olhos acabada, bela, pronta para ser admirada; talvez, sabendo-se sobre o processo envolvido em sua realização, o modo como vemos essa obra torna-se diferente, seria como, de certa forma, acompanhar um pouco de seu nascimento, para enfi m habitar o mundo.O objetivo principal desta pesquisa está justamente em levantar informações sobre os elementos formadores da obra em escultura cerâmica de Brennand, as influências recebidas pelo artista, seu processo de criação e a materialização de sua obra, enfatizando o barro como sua matéria de trabalho e diferencial de sua produção.Na obra de Brennand tudo chama muito a atenção, principalmente pelo fato de ser ele um artista que trabalha em distintas modalidades e faz uso de variados materiais.Apesar das diferentes técnicas trabalhadas pelo artista, há um elo que relaciona sua produção (independentemente da técnica e material).Por esse motivo, para realizar um estudo sobre sua arte em escultura cerâmica, houve a necessidade de se comentar sobre seu desenho, pintura em tela e mural, uma vez 12 CAMILA DA COSTA LIMA que sua produção de esculturas não se originou isoladamente.Em meio à vasta obra de Francisco Brennand, sua escultura se destaca, seja pelo material de que é feita, suas formas e volumes.O tema abordado pelo artista é o mesmo, independentemente do material ou técnica utilizados.Rege sua produção o mistério da origem da vida e todos os elementos associados a esta temática: o nascimento, o ovo, fi guras de corpos e de seus fragmentos, a fi gura da mulher -geradora da vida.Na obra de Brennand há ainda uma forte infl uência mitológica, assunto que será abordado ao longo deste trabalho, de modo a facilitar um entendimento sobre a criação do artista.Francisco Brennand é um artista contemporâneo, nordestino, cuja produção possui forte significado e importância para a arte brasileira.Na década de 1970, participou do Movimento Armorial, junto a outros nomes importantes da cultura pernambucana, como Ariano Suassuna.Sua formação artística, misto de um aprendizado europeu com o brasileiro, soma-se a um fator determinante, que vai além do espaço e do tempo e está marcado em sua própria origem: a ligação de sua família com a indústria cerâmica.Sua escultura é também brasileira no material.As argilas utilizadas vêm do nordeste, de regiões que produzem variedades não encontradas em nenhum outro local.Seus temas, ideias e formas, entretanto, superam nacionalidades e regionalismos.Inegavelmente o material utilizado por Brennand em sua escultura exerce notável fascínio para quem a aprecia.O domínio que o artista possui sobre a técnica da cerâmica, bem como os processos e transformações envolvidos na concepção de sua escultura, é elemento diferencial no resultado dessas obras.Talvez parte do "encanto" da escultura de Brennand esteja justamente no material -sua cerâmica com características técnicas e estéticas únicas.Na escultura de Brennand todo o seu conjunto atrai: tema, forma, dimensão e, principalmente, a matéria de que é feita -fosse outro material e sua escultura não teria as mesmas características.O barro é uma matéria que acompanha a própria evolução do homem, sua manipulação é uma das mais antigas ações da humanidade.Suas características são singulares, assim também como o processo que envolve a técnica da cerâmica: modelagem, esmaltação, queima. FRANCISCO BRENNAND 13Meu interesse pela obra de Francisco Brennand vem de longe.No ano de 1999 tive contato pela primeira vez com suas obras.Havia terminado uma exposição de esculturas do artista na Pinacoteca do Estado de São Paulo, mas ainda habitava o lugar uma obra ou outra, sufi ciente para captar minha atenção.Até o momento não tinha uma real dimensão da produção de Brennand e principalmente de seu trabalho em outras técnicas.Acreditava, assim como grande parte do público que aprecia sua obra sem grande aprofundamento, que Brennand produzia apenas esculturas, que fosse exclusivamente um escultor.As formas, cores, o material, a dimensão de suas esculturas em muito me admiraram e, a partir do catálogo da exposição que havia terminado "Brennand -Esculturas 1974 /1998", acompanhado do belo ensaio de Olívio Tavares de Araújo (também curador da exposição) "Proposta para uma Leitura de Brennand", conheci um pouco mais sobre o artista e sua produção.Até o momento, ainda não possuía muito conhecimento sobre a cerâmica, o que ocorreria um pouco adiante e acrescentaria maior interesse sobre a escultura de Brennand, como também a esta técnica.No ano de 2002 realizei o trabalho de conclusão do curso de Graduação, com a análise de um conjunto de esculturas de Brennand -trabalho ainda breve e de caráter inicial -que me trouxe o interesse em dar continuidade à pesquisa.Os anos foram passando e meu interesse pela obra de Brennand, assim como pela cerâmica, aumentou.A motivação e curiosidade me levaram como aluna especial, no ano de 2006, a conhecer a professora Lalada Dalglish.Sua experiência e conhecimento em cerâmica despertaram em mim uma atração ainda maior por esta área; ao cursar a disciplina "Tridimensionalidade: Fundamentos da Cerâmica, do popular ao contemporâneo" descobri um pouco mais da história, das variedades e particularidades que envolvem esta técnica, ainda hoje pouco pesquisada e explorada, dentro da dimensão de sua riqueza.Cada novo conhecimento sobre Brennand, bem como pela cerâmica, signifi cava uma surpresa, mas principalmente, ao aprender e realizar relações sobre os métodos empregados pelo artista, seus ção da escultura: o desenho inicial -estudo -, o modelo em menor escala, a modelagem, as diversas queimas, o processo de esmaltação, a montagem dos módulos das esculturas.Técnicas e processos que vêm sendo elaborados e readaptados constantemente por Brennand e por toda uma equipe de funcionários de sua Ofi cina.Nesse capítulo também consta um breve levantamento sobre as fases envolvidas no processo da cerâmica, a fi m de esclarecer dados sobre a técnica e suas possibilidades.O uso de imagens, ainda mais que em outros momentos deste trabalho, é de importância fundamental para, além de ilustrar o que será comentado, estabelecer relações dentro do processo de elaboração de sua escultura.Há uma variedade de material de pesquisa sobre Francisco Brennand, são várias as entrevistas, textos escritos pelo próprio artista, além de textos de críticos de arte, intelectuais e pesquisadores, catálogos e documentários.Tive acesso a diversas fontes, inclusive a oportunidade de trocar', '["ceramic sculpture","artistic process","artistic influence","mythological themes","origin of life","female figure","body fragments","drawing and painting","mural painting","Brazilian contemporary art","artist''s book","artists'' film"]', '10.7476/9788579830402', '9788579830402', 'https://books.scielo.org/id/jvjh7', 'https://books.scielo.org/id/jvjh7/pdf/lima-9788579830402.pdf', NULL, 'https://books.scielo.org/id/jvjh7/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jvycv', 'jvycv', 'Alegria é devoção: sambas, santos e novenas numa tradição afro-diaspórica da Bahia', NULL, '["Michael Iyanaga"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Em Alegria é devoção, Michael Iyanaga nos oferece uma análise inédita e minuciosa sobre uma das mais significativas tradições afro-diaspóricas da Bahia: a tradição domiciliar de sambar e cantar para São Roque, São Cosme, Santo Antonio e outros santos de devoção. Fundamentado em mais de dez anos de pesquisas históricas, antropológicas e musicológicas, o estudo apresenta os pormenores dessa tradição baiana, as músicas e as vidas dos devotos e das devotas, sempre realçando o seu legado africano. A partir daí, o autor questiona conceitos acadêmicos consagrados como “sincretismo”, “catolicismo popular” e outros. Alegria é devoção nos revela mais uma face da vasta complexidade religiosa e cultural da diáspora africana no Brasil.', '["samba","Afro-Brazilian religions","novenas","São Roque","Santo Antônio","African diaspora","Bahia","syncretism","popular Catholicism","worship music"]', '10.7476/9788526816497', '9788526815551', 'https://books.scielo.org/id/jvycv', NULL, NULL, 'https://books.scielo.org/id/jvycv/cover/cover_thumbnail.jpeg', 343, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jwq6p', 'jwq6p', 'O charme da ciência e a sedução da objetividade: Oliveira Vianna entre intérpretes do Brasil', NULL, '["Maria Stella Martins Bresciani"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A autora revisita a obra de Oliveira Vianna, intelectual estigmatizado por suas posições controversas, com o intuito de buscar o bacharel em Direito, preocupado com questões jurídicas e constitucionais, que se lança num trabalho de cientista social com a convicção, amplamente aceita na primeira metade do século XX, de que a situação presente, e os problemas econômicos, políticos e sociais do Brasil só seriam corretamente equacionados se sua história fosse bem analisada, desde os primórdios da colonização. Nesse sentido, traça um preliminar e rápido percurso pela questão da tessitura das identidades nacionais no século XIX, dado seu caráter amplo e recorrente no âmbito do universo de nossa "cultura ocidental".', '["Oliveira Vianna","social sciences","objectivity","Brazilian history","national identity","19th century","historiography","Brazilian intellectuals","colonial Brazil"]', '10.7476/9788539302888', '9788571397828', 'https://books.scielo.org/id/jwq6p', NULL, NULL, 'https://books.scielo.org/id/jwq6p/cover/cover_thumbnail.jpeg', 502, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jwskd', 'jwskd', 'Uma ciência sobre “coisa” alguma: relações funcionais, comportamento e cultura', NULL, '["Kester Carrara"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Embora seu conteúdo seja do interesse de áreas vizinhas, como Antropologia, Filosofia, Sociologia e Biologia, o livro está situado no âmbito da Análise Comportamental da Cultura. Essa área representa um campo temático relevante no contexto de uma das mediações teórico-epistemológicas da Psicologia e é constituída por uma ciência, a Análise do Comportamento, e uma filosofia de ciência, o Behaviorismo Radical. O texto, mais precisamente, está centrado nas práticas culturais, que se referem às ações humanas executadas de maneira entrelaçada com ações de outros indivíduos, característica inerente aos comportamentos sociais. Tecnicamente, o conteúdo examinado é o anunciado no subtítulo do livro, ou seja: relações funcionais, comportamento e cultura. No entanto, para além dessa instância, o texto trata da lógica subjacente às relações ou interações entre as pessoas, e entre estas e as agências de controle (como governo, lei e religião), ocupando-se de examinar tais relações de maneira funcional. Pode-se dizer que o texto, paralelamente ao interesse por precisão técnica na ciência do comportamento, busca estimular o leitor para uma avaliação sobre quanto temos, tradicionalmente, construído pressupostos, princípios, sistemas explicativos, escolas de pensamento e teorias voltados à defesa de explicações do comportamento humano com base em estruturas, quer físicas, quer conceituais, que não passam de constructos hipotéticos que se supõe sejam diretamente causadores de ações, atividades, comportamentos. Conceber uma “estrutura cognitiva”, uma “mente pensante”, uma “estrutura de personalidade”, um ego, um eu, um id, um superego, um traço de caráter, uma estrutura fisiológica, enfim, um mecanismo subjacente responsável pela causalidade primeira do comportamento parece constituir um equívoco perene na história da Psicologia e, talvez mais, na história da ciência. Embora sem, naturalmente, negar um monismo fisicalista, ontológico, de substância, o livro rejeita o status prioritário de importância tradicionalmente atribuído às estruturas, em si mesmas, como entes explicativos do comportamento humano.', '["functional relationships","cultural practices","social behavior","radical behaviorism","behavior analysis","critique of structuralism","mind-body problem","social control","behaviorism","philosophy of science","epistemology of psychology","history of psychology"]', '10.7476/9788579836572', '9788579836572', 'https://books.scielo.org/id/jwskd', 'https://books.scielo.org/id/jwskd/pdf/carrara-9788579836572.pdf', NULL, 'https://books.scielo.org/id/jwskd/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jx8dk', 'jx8dk', 'La cocina de los venenos: aspectos de la criminalidad en el Nuevo Reino de Granada, siglos XVII y XVIII', NULL, '["Juan Sebastián Ariza Martínez"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Durante los siglos XVII y XVIII se presentaron varias querellas ante el tribunal de justicia criminal del nuevo reino de granada, en las que se denunciaba que había personas que ejercían los oficios médicos sin tener títulos que los acreditaran como facultativos en las artes curativas. Por ese entonces, se creía que quienes utilizaban yerbas y conjuros como métodos terapéuticos, por lo general mujeres, debían ser juzgadas como yerbateras-envenenadoras, porque no pretendían curar sino matar a quien consumiera sus preparados.El texto establece que los procesos criminales por envenenamiento constituyen un prisma en el que convergen diferentes problemáticas del periodo colonial neogranadino, relacionadas con la salud, los oficios médicos, las enfermedades, las creencias mágico-religiosas, el ideal de mujer en la época, la delincuencia, y las dinámicas de las instituciones españolas, entre otras. De esta manera, se estudió cómo fue la relación entre los aspectos jurídicos, las leyes criminales (dictadas por la corona) y las conductas “desviadas” (relacionadas con el crimen por envenenamiento) de los habitantes del nuevo reino de granada, entre los siglos XVII y XVIII. Para ello se revistaron desde diferentes perspectivas, varios temas del mundo colonial neogranadino, relacionados con los rumores, la comidilla, los chismes y la importancia de la comunicación hablada en el virreinato; el problema de la honra, como una de las virtudes más sobresalientes de la época y las creencias de la cultura popular con relación al envenenamiento y los diferentes métodos curativos.', '["poisoning","criminality","New Kingdom of Granada","colonial medicine","unlicensed medical practice","women healers","herbal medicine","witchcraft beliefs","criminal trials","ideal of womanhood","delinquency","Spanish colonial institutions"]', '10.7476/9789587385502', '9789587385502', 'https://books.scielo.org/id/jx8dk', 'https://books.scielo.org/id/jx8dk/pdf/ariza-9789587385502.pdf', NULL, 'https://books.scielo.org/id/jx8dk/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jxw3s', 'jxw3s', 'O petróleo no Brasil: exploração, capacitação técnica e ensino de geociências (1864-1968)', NULL, '["Drielli Peyerl"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A indústria do petróleo nasceu muito tardiamente no Brasil, mesmo quando comparada a de outros países da América Latina. A emergência dessa atividade produtiva no país ocorre em consequência da persistência de atores nacionais públicos e privados, que apostaram no potencial geológico do país. Nessa trajetória singular evidencia-se também que a institucionalização das geociências ocorre a reboque da atividade produtiva. Foi quando o Estado brasileiro se empenhou em desenvolver a atividade petrolífera no país, por meio da criação do Conselho Nacional do Petróleo, em 1938, e, posteriormente, da Petrobras, em 1953, que ficou evidente a ausência de recursos humanos qualificados no campo das geociências no Brasil. Esse último aspecto é particularmente impressionante em um país de dimensão continental e de tantas riquezas minerais. Essa experiência singular é descrita de forma cativante e magistral por Drielli Peyerl. Ela retoma essa história desde os albores da indústria do petróleo, em 1864, até o final dos anos 1960, quando a Petrobras realiza os seus primeiros avanços na produção offshore. O caso brasileiro ilustra claramente a tese de que o progresso na formação de recursos humanos e, posteriormente, na pesquisa, somente se deu, em nosso país, em decorrência de um projeto explícito de desenvolvimento. De fato, foi a partir do imperativo da industrialização, e da decorrente expansão da demanda interna de derivados de petróleo, que surgiu a necessidade de produzir petróleo em solo nacional. Contudo, foi apenas com a expansão da indústria do petróleo no país que se consolidou a necessidade de formar recursos humanos qualificados, contribuindo para a sedimentação da ciência geológica no país. Nesse sentido, a Petrobras teve um papel decisivo na criação dos primeiros cursos de geologia do país, cabendo-lhe exercer a função de agência de fomento na institucionalização dessa disciplina', '["oil industry history","Brazil","petroleum exploration","technical training","geoscience education","Petrobras","human resource development","state development policy","industrialization","offshore oil production"]', '10.7476/9788568576786', '9788568576786', 'https://books.scielo.org/id/jxw3s', 'https://books.scielo.org/id/jxw3s/pdf/peyerl-9788568576786.pdf', NULL, 'https://books.scielo.org/id/jxw3s/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jxywm', 'jxywm', 'As persistentes desigualdades brasileiras como temas para o ensino médio', NULL, '["Ângela Maria de Souza Lima","Ileizi Luciana Fiorelli Silva","María José de Rezende"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] Este livro aborda diferentes temáticas todas elas inerentes aos problemas das desigualdades sociais: política, cidadania, trabalho, gênero, raça, memória, patrimônio, escola, jovens, indústria cultural e universidade. Todos estes assuntos foram tratados com base em uma sofisticada literatura das Ciências Sociais Clássicas e Contemporâneas.', '["social inequality","upper secondary school","citizenship","gender","race","memory","cultural heritage","education","youth","cultural industries","universities","labor"]', '10.7476/9788572166492', '9788572166492', 'https://books.scielo.org/id/jxywm', NULL, NULL, 'https://books.scielo.org/id/jxywm/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jy2pf', 'jy2pf', 'Filosofia, racionalidade, democracia: os debates Rorty &amp; Habermas', NULL, '["José Crisóstomo de Souza"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Rorty e Habermas estão entre os mais importantes intelectuais e filósofos hoje em atividade, no mundo, e são provavelmente aqueles que têm maior público, dentro e fora das universidades. Entrevistas e artigos seus aparecem em jornais e revistas de grande circulação, e seus livros são traduzidos e publicados pelo mundo afora. Neste livro, Habermas e Rorty debatem e dialogam, entre si, sobre suas concepções mais gerais e, em especial, sobre filosofia, cultura, razão e política, num confronto que envolve posições de outros importantes pensadores, de ontem e de hoje, como Apel e os "pós- modernos" franceses, como Dewey e Wittgenstein, como Heidegger e Nietzsche, como Hegel e Kant. Suas concepções tratam de levar em conta os desenvolvimentos mais recentes da filosofia, em relação a temas como valores, linguagem, verdade e conhecimento.', '["Richard Rorty","Jürgen Habermas","political philosophy of democracy","rationality","political philosophy","culture","values","language","truth","knowledge","postmodernism"]', '10.7476/9788539303069', '9788571396197', 'https://books.scielo.org/id/jy2pf', NULL, NULL, 'https://books.scielo.org/id/jy2pf/cover/cover_thumbnail.jpeg', 272, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-jy7mt', 'jy7mt', 'Baía de todos os santos: aspectos humanos', NULL, '["Carlos Caroso","Fátima Regina Gomes Tavares","Pereira, Cláudio"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'A presente obra foi pensada em dois volumes. O primeiro, intitulado Ambiente Físico, foi lançado em 2009 e aborda os aspectos oceanográficos da BTS. Para a organização deste segundo volume, Ambiente Humano, foi convidado o antropólogo Carlos Caroso que, junto com a Profª. Fátima Tavares e o Prof. Cláudio Pereira, contribuiu para uma reflexão nos modos de pensar e agir a Baía de Todos os Santos. Dividido em três eixos temáticos, que envolvem desde a dimensão histórica da região até questões econômicas e de infra-estrutura, este livro tem como objetivo compor um quadro o mais rico possível da diversidade da Baía de Todos os Santos.', '["Baía de Todos os Santos","human dimension","local history","regional economy","infrastructure","human-environment relations","coastal communities","anthropological perspective"]', '10.7476/9788523211622', '9788523211622', 'https://books.scielo.org/id/jy7mt', 'https://books.scielo.org/id/jy7mt/pdf/caroso-9788523211622.pdf', NULL, 'https://books.scielo.org/id/jy7mt/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k29dm', 'k29dm', 'Resíduos plásticos e reciclagem: aspectos gerais e tecnologia', NULL, '["María Zanín","Sandro Donnini Mancini"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', '[RETIRADO/WITHDRAWN] Resíduos plásticos e reciclagem: aspectos gerais e tecnologia aborda o assunto dos plásticos presentes nos resíduos sólidos urbanos, enfatizando aspectos sociais, ambientais, políticos, econômicos, legais, técnicos e científicos que podem ajudar a entender porque a reciclagem deste tipo de material é possível, viável, necessária e urgente. O livro é apresentado numa linguagem simples e concisa, tratando-se de uma referência interessante para leigos no assunto, profissionais de administrações públicas e estudantes de cursos técnicos, de graduação e pós-graduação nas áreas ambiental, sanitária, de engenharia e de ciência dos materiais.', '["plastic waste","plastic recycling","municipal solid waste","recycling technology","environmental policy","waste management"]', '10.7476/9788576004578', '9788576004578', 'https://books.scielo.org/id/k29dm', NULL, NULL, 'https://books.scielo.org/id/k29dm/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k2xr6', 'k2xr6', 'Catálogo da fauna terrestre de importância médica na Bahia', NULL, '["Tânia Kobler Brazil"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Este livro expõe, de maneira sintética e padronizada, os principais animais terrestres de importância médica que ocorrem no Estado da Bahia, sendo organizado como uma obra de referência direcionada aos profissionais da área da saúde dos seus diversos municípios. Constam, neste catálogo, 28 espécies de animais peçonhentos, 13 de animais vetores e 19 de animais reservatório. Foram estruturadas fichas com textos em linguagem adequada ao público-alvo, porém cientificamente correta, para cada animal ou grupo de animais.', '["venomous animals","disease vectors","disease reservoirs","zoonoses"]', '10.7476/9788523211660', '9788523211660', 'https://books.scielo.org/id/k2xr6', 'https://books.scielo.org/id/k2xr6/pdf/brazil-9788523211660.pdf', NULL, 'https://books.scielo.org/id/k2xr6/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k3bpr', 'k3bpr', 'Misiones, pueblos indígenas y la conformación de la Región Amazónica. Actores, tensiones y debates actuales', NULL, '["José Enrique Juncosa Blasco","Blas Garzón Vera"]', 'SciELO', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Las drásticas transformaciones que vive la Amazonía ecuatoriana, expresadas en la expansión del extractivismo, la desterritorialización de los pueblos indígenas y la consolidación del Estado como actor clave y preponderante son aspectos pendientes de ser comprendidos en tanto resultado de procesos históricos de larga data. Esta obra colectiva contribuye a su comprensión y profundiza las complejas relaciones entre los actores que interactuaron en la conformación regional de la Amazonía ecuatoriana, enfatizando el rol de las misiones y de los pueblos indígenas junto a otras agencias tales como los militares, colonos, mineros y élites regionales. La obra convoca a especialistas de diferentes perfiles perfiles y adscripciones institucionales (historiadores, educadores, antropólogos, politólogos...) cuyas contribuciones arrojan una visión compleja y heterogénea, y dan luces para entender la trama del presente a través de estudios de caso regionales, de análisis del discurso y de la investigación del pensamiento y la acción de figuras preponderantes.', '["mission","indigenous peoples","Ecuadorian Amazon","regional formation","extractivism","deterritorialization","state formation","colonialism","military","colonists","miners","regional elites"]', '10.7476/9789978104941', NULL, 'https://books.scielo.org/id/k3bpr', 'https://books.scielo.org/id/k3bpr/pdf/juncosa-9789978104941.pdf', NULL, 'https://books.scielo.org/id/k3bpr/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k3fy2', 'k3fy2', 'Saúde coletiva: políticas públicas em defesa do sistema universal de saúde', NULL, '["Daniela Savi Geremia","Maria Eneida de Almeida"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra “Saúde Coletiva: políticas públicas em defesa do Sistema Universal de Saúde” organiza-se em cinco partes: 1) Movimento da Reforma Sanitária Brasileira: avanços, retrocessos, desafios e perspectivas na conjuntura nacional; 2) Sistema Universal e Direito à Saúde; 3) Investimento Social e Austeridade Fiscal: desafios para o planejamento e a gestão pública; 4) Saúde e Ambiente; 5) Educação e Formação em Saúde. É resultado do I Congresso Internacional de Políticas Públicas de Saúde: em defesa do Sistema Universal de Saúde, realizado em dezembro de 2017. Esse congresso buscou espaço para reflexão, discussão e intercâmbio de conhecimentos técnico-científicos entre estudantes, pesquisadores, professores, gestores, profissionais da saúde e áreas afins para fortalecer os princípios de justiça social mediante políticas públicas de acesso universal. A obra fundamenta-se, portanto, na luta permanente pelo direito da população brasileira à saúde pública e de qualidade em todo o território nacional. O direito universal à saúde é uma condição de cidadania, já conquistado no Brasil mediante lutas e resistências dos movimentos sociais, principalmente do Movimento da Reforma Sanitária Brasileira, que foi institucionalizado em 1976, com a criação do Centro Brasileiro de Estudos de Saúde (CEBES), do qual a Universidade Federal da Fronteira Sul (UFFS) é membro institucional, culminando com a elaboração do texto constitucional de criação do Sistema Único de Saúde, em 1988. O público de interesse da obra é a área da Saúde em geral e, em particular, o campo da Saúde Coletiva da UFFS e da Região Oeste Catarinense.', '["universal health systems","Unified Health System (SUS)","right to health","health policy","social investment","austerity","health and environment","health education","social movements","social justice","health care access","Cebes"]', '10.7476/9786586545562', NULL, 'https://books.scielo.org/id/k3fy2', 'https://books.scielo.org/id/k3fy2/pdf/geremia-9786586545562.pdf', NULL, 'https://books.scielo.org/id/k3fy2/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k3pht', 'k3pht', 'Análise de discurso crítica: um método de pesquisa qualitativa', NULL, '["Izabel Magalhães","André Ricardo Martins","Viviane de Melo Resende"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Um livro para quem quer fazer análise de discurso e não sabe como Análise de Discurso Crítica: um método de pesquisa qualitativa é um lançamento que prestigia uma teoria da Linguística que cada vez mais desperta o interesse de pesquisadores de várias áreas. Este livro privilegia uma abordagem metodológica. Os autores buscam contribuir para o debate a partir de uma perspectiva teórico-metodológica que, embora não seja tão nova, tem gerado diversos desdobramentos. A própria Análise de Discurso Crítica (ADC) é uma dentre as várias vertentes no largo campo dos estudos do discurso. Nesta obra – escrita a seis mãos – o(a) leitor(a) vai encontrar uma abordagem sistemática do discurso, que busca evitar generalizações e promover análises de textos e das práticas que os produzem. Ela é composta de três partes: a primeira traz uma discussão sobre a ADC como método de pesquisa qualitativa para a crítica social; a segunda aborda a relação entre ADC e etnografia; e a terceira apresenta exemplos de análise. É, como se pretende, o método em ação, numa perspectiva didática, de modo a facilitar o uso do instrumental por pesquisadores ainda sem muita familiaridade com a abordagem.', '["critical discourse analysis","qualitative research methodology","discourse studies","ethnography","social criticism","text analysis","research methodology training"]', '10.7476/9788523013370', '9788523011956', 'https://books.scielo.org/id/k3pht', NULL, NULL, 'https://books.scielo.org/id/k3pht/cover/cover_thumbnail.jpeg', 260, 41, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k3w36', 'k3w36', 'Cambio climático, biodiversidad y sistemas agroalimentarios: avances y retos a 10 años de la Ley Orgánica del Régimen de la Soberanía Alimentaria en Ecuador', NULL, '["Esteban Daza","Tamara Artacker","Ronnie Xavier Lizano Acevedo"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Hacer un balance crítico de los diez años de vigencia de la Ley Orgánica de Régimen de Soberanía Alimentaria es uno de los objetivos principales que han propuesto los autores de este libro, Analizar los límites y ventajas de este cuerpo normativo, establecer su relación con la nutrición y la comercialización y, finalmente, identificar experiencias territoriales más allá de la ley, hacen parte de este balance. El texto hay que leerlo en el marco de las tensiones entre el modelo agrícola dominante que estandariza los sistemas de producción.consumo de alimentos y las agriculturas familiares, campesinas, indígenas y comunitarias que en base a su diversificación productiva, conservan los agroecosistemas y reactivan los patrimonios agroalimentarios como elementos estratégicos para un Buen Vivir rural en el contexto del cambio climático. El libro concluye que la lucha por la soberanía alimentaria no debe agotarse en la esfera del discurso jurídico y normativo. En su lugar, la propuesta revaloriza las reivindicaciones históricas de las luchas indígenas y campesinas y hace de sus principales demandas, principios para la construcción de un programa agrario transformador.', '["food sovereignty","agroecology","climate change","biodiversity","family farming","agroecological diversification","good life","nutrition","food commercialization","territorial experience","agricultural transformation","Ecuador"]', '10.7476/9789978105689', '9789978105689', 'https://books.scielo.org/id/k3w36', 'https://books.scielo.org/id/k3w36/pdf/daza-9789978105689.pdf', NULL, 'https://books.scielo.org/id/k3w36/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k3zs8', 'k3zs8', 'Matronas Afro-pacíficas: tramas da resistência na fronteira Colômbia-Equador', 'tramas da resistência na fronteira Colômbia-Equador', '["Paula Balduíno de Melo"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, a violência militar, o narcotráfico e a corrupção não silenciam a voz das mulheres afro-pacíficas. Ele não interrompe o fluxo das águas internas que constituem sua subjetividade ou seu árduo trabalho político de resistência e direito à diferença. Na etnografia de Paula Balduino, acompanhamos o fluxo dessas mulheres, das associações em que atuam, de suas histórias, de seus antepassados, dos palenques, das periferias urbanas, das indústrias extrativistas e armamentícias que destroem corpos e paisagens, das crianças que crescem em seus corpos, dos corpos desaparecidos, do rio que lhes dá vida e que carrega seus cadáveres anônimos, do rio que deságua no mar, da vida marinha como a dos mariscos que deságua em vida dos povos desse lugar. Subvertendo os limites entre Equador e Colômbia, o movimento dessas mulheres decompõe tempos e espaços do colonialismo e do capitalismo, construindo uma territorialidade afro-pacífica. Na esteira de grandes fontes de inspiração, como Lélia Gonzales, este livro é leitura obrigatória a todas as pessoas – acadêmicas ou não – que nutram um interesse existencial pelas experiências de quem – como as mulheres afro-pacíficas – põe em prática o feminismo afrolationamericano e seu anseio por um mundo livre de racismo e de violência de gênero.', '["resistance","Ecuador-Colombia border","women''s organizations","Palenque","drug trafficking","corruption","colonialism","capitalism","racism","gender-based violence","right to difference"]', '10.7476/9786558462736', '9786558462590', 'https://books.scielo.org/id/k3zs8', 'https://books.scielo.org/id/k3zs8/pdf/melo-9786558462736.pdf', NULL, 'https://books.scielo.org/id/k3zs8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k42ry', 'k42ry', 'A máscara no teatro moderno: do avesso da tradição à contemporaneidade', NULL, '["Vinícius Torres Machado"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro apresenta algumas das iniciativas para a retomada da máscara no teatro moderno. No amplo quadro da primeira metade do século XX, o autor selecionou quatro principais artistas que abordaram esse objeto: Gordon Craig, Meyerhold, Jacques Copeau e Jacques Lecoq. Nesses autores, a máscara não é apenas um elemento colocado em cena, mas também um princípio organizador da teatralidade que almejam. A partir das reflexões desses autores, Vinícius Torres Machado analisa algumas características da máscara que podem ser reelaboradas no teatro contemporâneo.', '["theatrical masks","modern theatre","Gordon Craig","Vsevolod Meyerhold","Jacques Copeau","Jacques Lecoq","theatre of the absurd","theatricality","contemporary theatre","avant-garde theatre","20th-century theatre"]', '10.7476/9788595462878', '9788595462878', 'https://books.scielo.org/id/k42ry', 'https://books.scielo.org/id/k42ry/pdf/machado-9788595462878.pdf', NULL, 'https://books.scielo.org/id/k42ry/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k4gdn', 'k4gdn', 'Umbu-cajazeira: descrição e técnicas de cultivo', NULL, '["Francisco Xavier de Souza","Francisco de Queiroz Porto Filho","Nouglas Veloso Barbosa Mendes"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Árvore frutífera, xerófita, da família Anacardiácea e do gênero Spondias, mas ainda sem nome especifíco. Nativa do semiárido brasileiro, onde existe uma grande população de plantas centenárias e produtivas, clonadas por estaquia, dispersas, notadamente em quintais, produzindo milhões de toneladas de frutos para as CEASAs e agroindústrias, é a principal matéria-prima de muitas fábricas. Igualmente às outras Spondias, seus frutos são chamados por diversos nomes comuns: umbu-cajá, cajá-umbu, cajarana, cajazinha, cajá-amarelo, cajá-do-sertão, umbu-amarelo e também umbu ou cajá. Dessa forma, são disseminadas informações equivocadas que tornam imprecisos os dados de produção do IBGE e das CEASAs impedindo a identidade nominal, a mensuração do real volume de produção e a sua importância agrossocioeconômica. Daí a necessidade de citações idôneas e fidedignas. A umbu-cajazeira é pouco pesquisada – esta obra consiste em um compêndio de informações obtidas através de trabalhos experimentais, análises, interpretação, adaptação, visitas de campo, contatos e conhecimentos tácitos de produtores. Contém conhecimentos e informações aplicáveis à sua cadeia produtiva, que podem ser úteis para a tomada de decisões estratégicas de gestão e de operacionalização para agricultores familiares, empreendedores, órgãos de assistência técnica, P&DI, agroindústrias, instituições de fomento e formuladores de políticas públicas para alavancar com sustentabilidade esse importante agronegócio.', '["Spondias tuberosa","Spondias","Anacardiaceae","fruit trees","xerophytes","fruit growing","family farming","cultivation techniques","plant descriptions","vernacular names","production chain","sustainable agriculture"]', '10.7476/9786587108599', '9786587108599', 'https://books.scielo.org/id/k4gdn', 'https://books.scielo.org/id/k4gdn/pdf/souza-9786587108599.pdf', NULL, 'https://books.scielo.org/id/k4gdn/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k4m6j', 'k4m6j', 'Atenção primária à saúde em municípios rurais remotos no Brasil', NULL, '["Fausto, Márcia Cristina Rodrigues","Almeida, Patty Fidelis de","Santos, Adriano Maia dos","Bousquat, Aylene","Giovanella, Ligia"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-08-16', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'A obra busca compreender as particularidades dos contextos rurais remotos brasileiros, tendo em vista a organização e provisão da Atenção Primária à Saúde (APS), alinhada aos princípios basilares do Sistema Único de Saúde (SUS). O livro é composto de 14 capítulos distribuídos em três partes, além da Introdução. Cada capítulo trata de temas diversos envolvidos no acesso e na organização da APS nos diferentes cenários da pesquisa e relacionados com dificuldades presentes em todos os territórios do estudo. A obra instiga o interesse acerca de realidades tão singulares, pouco exploradas, por vezes invisibilizadas e não dimensionadas no financiamento, planejamento e execução de políticas públicas. Fruto do esforço do grupo de pesquisa interdisciplinar e interinstituicional do CNPq, Pesquisas em Atenção Primária à Saúde, o estudo é decorrente do Programa Nacional de Melhoria do Acesso e da Qualidade da Atenção Básica (Pmaq-AB) do Ministério da Saúde, em cooperação com a Fiocruz.', '["primary care","Unified Health System (SUS)","health care access","health policy","PMAQ-AB","rural health","health care financing"]', '10.7476/9786557082140', '9786557081488', 'https://books.scielo.org/id/k4m6j', NULL, NULL, 'https://books.scielo.org/id/k4m6j/cover/cover_thumbnail.jpeg', 387, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k4vp7', 'k4vp7', 'O nervo cala, o nervo fala: a linguagem da doença', NULL, '["Maria Lúcia da Silveira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Resulta de uma pesquisa sobre o sofrimento de nervos entre mulheres na comunidade do Campeche, em Florianópolis, Santa Catarina. Entremeando relatos das pacientes a observações pessoais e teóricas, a autora traça um retrato do atendimento médico no local, bem como das relações interpessoais, utilizando, como cenário, o problema dos nervos. Antropologia e medicina se unem, oferecendo uma visão mais completa de uma queixa cada vez mais freqüente nos consultórios em todo o mundo. Mais do que uma pesquisa, é um relato permeado de humanidade. Fica para o leitor a tarefa, sugerida pela autora, de refletir sobre a relação entre gênero, saúde, violência e nervos.', '["neurological disorders","women''s health","gender and health","health care","interpersonal relationships","illness narratives","violence against women","Florianópolis"]', '10.7476/9788575416099', '9788575416099', 'https://books.scielo.org/id/k4vp7', 'https://books.scielo.org/id/k4vp7/pdf/silveira-9788575416099.pdf', NULL, 'https://books.scielo.org/id/k4vp7/cover/cover_thumbnail.jpeg', NULL, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k4vrh', 'k4vrh', 'História do Paraná: séculos XIX e XX', NULL, '["Angelo Priori","Luciana Regina Pomari","Silvia Maria Amâncio","Verônica Karina Ipólito"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'História do Paraná: séculos XIX e XX é uma obra que analisa diversos temas da história do Estado, buscando compreender a diversidade das experiências sociais, culturais e políticas, a partir de uma postura crítica e interpretativa. A análise do passado, quando submetida a uma metodologia histórica adequada, faz com que os leitores possam ampliar a compreensão dos fatos históricos. O objetivo principal deste livro não é mostrar uma história tradicional, mas contribuir para o entendimento da história do Paraná, sempre levando em consideração as experiências sociais do nosso povo, no tempo e no espaço. Portanto, o livro não abarca todos os temas fundamentais da história do Paraná. Houve uma seleção de assuntos. O livro parte de um perfil bem definido: a história vista a partir dos seus movimentos sociais, políticos, econômicos e culturais. Para isso, definiu-se analisar aqueles movimentos mais importantes e as mudanças estruturais que marcaram o Paraná dos séculos XIX e XX.', '["19th century","20th century","social movements","political history","economic history","cultural history","structural change","social experience"]', '10.7476/9788576285878', '9788576285878', 'https://books.scielo.org/id/k4vrh', 'https://books.scielo.org/id/k4vrh/pdf/priori-9788576285878.pdf', NULL, 'https://books.scielo.org/id/k4vrh/cover/cover_thumbnail.jpeg', NULL, 35, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k53tv', 'k53tv', 'Ver, fazer e viver cinema: experiências envolvendo curso de extensão universitária', NULL, '["Humberto Perinelli Neto"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Humberto Perinelli NetoO cinema é, muitas vezes, definido como uma linguagem marcada pela "imagem em movimento" (Araújo, 1995).Tal definição traduz questão essencial dessa linguagem/arte: o fato de pertencer à modernidade, ou seja, ao processo histórico profun damente relacionado à aceleração das experiências humanas e, mediante isso, à transformação da percepção que homens e mulheres passaram a ter sobre o tempo e o espaço, especialmente a contar do século XIX (Harvey, 1998;Berman, 1996).Contudo, responsáveis por enorme revolução cultural no século XX, os filmes reuniram em si mesmos as outras artes já conhecidas (a dança, o teatro, a música, a literatura, a pintura e a escultura) e, cada vez mais, deixaram de ser meros "registros do movimento".A contar da criação do cinema (1895), os filmes expressaram uma maneira peculiar de transformar o mundo em discurso, segundo o desenvolvimento de narrativa marcada por um sistema simbólico de produção/reprodução de significados específicos, daí o emprego de expressões como cultura cinematográfica e linguagem cinematográfica, igualmente tradutoras de certa "sensibilidade moderna" (Aumont et al., 2005;', '["cinema","university extension course","film education","moving image","modernity","film language","film culture","perception of space and time"]', '10.7476/9788579837586', '9788579837586', 'https://books.scielo.org/id/k53tv', 'https://books.scielo.org/id/k53tv/pdf/perinelli-9788579837586.pdf', NULL, 'https://books.scielo.org/id/k53tv/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k55yv', 'k55yv', 'O sistema segmental do português: constituição e simplificação fonológica', 'constituição e simplificação fonológica', '["Elizabeth Reis Teixeira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Esta obra apresenta os aspectos fonoarticulatórios de composição e de combinação do inventário de sons do português, como também os padrões de simplificação do sistema fonológico durante o desenvolvimento da fala e da escrita em situações típicas e não típicas. Além disso, traça um interessante paralelo entre padrões aquisicionais e padrões de simplificação fonológica marcadores de estigmatização sociolinguística. Aborda, ainda, a contagem de frequência de ocorrência de padrões segmentais, silábicos, lexicais, intrassilábicos e intersilábicos, mostrando, estatisticamente, os padrões que têm maior representatividade na língua, e são mais simplificados na fala infantil e na fala adulta, com destaque especial para os Erros de Ordenação Serial, e a Permutação Segmental lntersilábica da fala infantil.', '["Portuguese phonology","phonological simplification","children''s speech","speech development","phonological development","syllable structure"]', '10.7476/9786556309439', '9786556308296', 'https://books.scielo.org/id/k55yv', 'https://books.scielo.org/id/k55yv/pdf/teixeira-9786556309439.pdf', NULL, 'https://books.scielo.org/id/k55yv/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k5kb5', 'k5kb5', 'Ypabuçu: a vida nas lagoas', NULL, '["Marcos Allyson Felipe Rodrigues"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'A partir de crônicas interligadas como num almanaque no qual cada mês do ano mostra as relações ecológicas que podem ser observadas em qualquer lagoa do planeta, os comentários do autor partem para outras localidades, como os grandes lagos da África e da América do Norte, os lagos salgados dos Andes, os grandes lagos fluviais da Amazônia e até o mar da Galileia. Nesse passeio ou viagem, Marcos Rodrigues descreve fenômenos da natureza pouco percebidos, quando não inusitados: a floração das árvores mais antigas do mundo, as viagens transcontinentais de aves, a descoberta das tilápias sagradas pescadas pelos apóstolos, as algas sufocadas por bactérias, a formação de cemitérios de conchas, as viagens de alevinos e muito mais. À medida que os meses passam, encontramos exploradores, naturalistas, poetas, cisnes, baobás, capivaras, urubus, ervas “daninhas” e até estranhos seres como as lampreias e os microcrustáceos. Esses encontros vão construir uma curiosa teia de relações entre caminhada, história, contemplação e ecologia.', '["lagoons","ecological interactions","nature writing","travel writing","Lake Galilee","lamprey","microcrustaceans","Adansonia digitata","capybara","harpy eagle","naturalists","exploration history"]', '10.7476/9788526816671', '9788526815537', 'https://books.scielo.org/id/k5kb5', NULL, NULL, 'https://books.scielo.org/id/k5kb5/cover/cover_thumbnail.jpeg', 230, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k64dr', 'k64dr', 'Mediação &amp; midiatização', NULL, '["Maria Ângela Mattos","Jeder Silveira Janotti","Nilda Jacks"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro aborda os conceitos de Mediação e Midiatização, levando em consideração suas limitações, potencialidades, articulações e contribuições para as análises dos processos comunicacionais contemporâneos. Divide-se em duas partes: Mediação e midiatização: conexões epistemológicas, que discute aportes teórico-metodológicos e conceitos-chave da área, e Percursos investigativos, que aborda as noções de midiatização e mediação no campo da pesquisa empírica e na análise dos processos e produtos midiáticos.', '["mediation (cultural/media theory)","midiatization","media theory","media products"]', '10.7476/9788523212056', '9788523212056', 'https://books.scielo.org/id/k64dr', 'https://books.scielo.org/id/k64dr/pdf/rodrigues-9788579820205.pdf', NULL, 'https://books.scielo.org/id/k64dr/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k6sdp', 'k6sdp', 'Salvador: transformações e permanências (1549-1999)', NULL, '["Pedro de Almeida Vasconcelos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra realiza uma análise diacrônica da relação entre processo social e forma espacial, recuperando toda a complexidade do processo histórico de produção do território soteropolitano. Momentos deste processo são revelados e analisados pelo autor, que identifica, para cada período estudado, os agentes modeladores principais, as contradições socioespaciais existentes, as heranças, rupturas e permanências.', '["Salvador, Bahia","urban history","territorial production","urban form","social processes","urban transformation"]', '10.7476/9788523217365', '9788523215118', 'https://books.scielo.org/id/k6sdp', NULL, NULL, 'https://books.scielo.org/id/k6sdp/cover/cover_thumbnail.jpeg', 569, 26, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k8463', 'k8463', 'Pesquisa de verdade ou pesquisa de boca? Enfrentamentos metodológicos e éticos em pesquisas sociais no mundo dos psicoativos', NULL, '["MacRae, Edward","Medeiros, Regina","Alencar, Roca"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea é resultado de debates nos grupos de trabalho no âmbito das Reuniões Brasileira de Antropologia 2018 e 2020, onde pesquisadores, professores e estudantes apresentaram resultados de pesquisa ou de intervenções bem-sucedidas no campo das substâncias psicoativas. O livro busca estimular discussões no ainda pouco explorado campo das pesquisas empíricas de caráter etnográfico sobre o uso de drogas, focando os desafios éticos encontrados como ponto central, partindo dos princípios de relação entre pesquisadores e interlocutores: a autonomia, a beneficência e a igualdade.', '["psychoactive substances","drug use","research ethics","ethnography","researcher-participant relationship","autonomy","beneficence","equality","methodological issues","drug use research"]', '10.7476/9786556308777', '9786556305394', 'https://books.scielo.org/id/k8463', NULL, NULL, 'https://books.scielo.org/id/k8463/cover/cover_thumbnail.jpeg', 368, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
